    const HOWDI_OPENAI_MODEL = String(process.env.OPENAI_MODEL || "gpt-5.6-luna").trim();
    const HOWDI_OPENAI_API_KEY = String(process.env.OPENAI_API_KEY || "").trim();

    function extractOpenAIResponseText(payload){
      if(payload && typeof payload.output_text === "string" && payload.output_text.trim()) return payload.output_text.trim();
      const chunks=[];
      for(const item of (payload?.output||[])){
        for(const part of (item?.content||[])){
          if(typeof part?.text==="string" && part.text.trim()) chunks.push(part.text.trim());
        }
      }
      return chunks.join("\n\n").trim();
    }

    function callHowdiOpenAIResponses({instructions,input,model=HOWDI_OPENAI_MODEL,maxOutputTokens=1800}){
      return new Promise((resolve,reject)=>{
        if(!HOWDI_OPENAI_API_KEY) return reject(new Error("OPENAI_API_KEY is not configured"));
        const body=JSON.stringify({
          model,
          instructions,
          input,
          max_output_tokens:maxOutputTokens
        });
        const req=https.request({
          hostname:"api.openai.com",
          port:443,
          path:"/v1/responses",
          method:"POST",
          headers:{
            "Authorization":`Bearer ${HOWDI_OPENAI_API_KEY}`,
            "Content-Type":"application/json",
            "Content-Length":Buffer.byteLength(body)
          },
          timeout:60000
        },res=>{
          let raw="";
          res.on("data",d=>raw+=d);
          res.on("end",()=>{
            let data={};
            try{data=raw?JSON.parse(raw):{};}catch{}
            if(res.statusCode<200||res.statusCode>=300){
              const msg=data?.error?.message||`OpenAI request failed (${res.statusCode})`;
              return reject(new Error(msg));
            }
            const text=extractOpenAIResponseText(data);
            if(!text) return reject(new Error("AI provider returned no usable text"));
            resolve({text,id:data.id||null,model:data.model||model,usage:data.usage||null});
          });
        });
        req.on("timeout",()=>req.destroy(new Error("AI provider request timed out")));
        req.on("error",reject);
        req.write(body);
        req.end();
      });
    }
