    async function cleanupStaleWorksTriggers() {
      const targets = ["works_work_orders", "works_work_offers"];
      for (const table of targets) {
        try {
          const q = await pool.query(
            `SELECT t.tgname
               FROM pg_trigger t
               JOIN pg_class c ON c.oid=t.tgrelid
               JOIN pg_namespace n ON n.oid=c.relnamespace
              WHERE n.nspname=current_schema()
                AND c.relname=$1
                AND NOT t.tgisinternal`,
            [table]
          );
          for (const row of q.rows) {
            const triggerName = String(row.tgname || "").replace(/"/g, '""');
            if (!triggerName) continue;
            console.log(`⚠️ Removing stale HOWDI Works trigger ${triggerName} from ${table}`);
            await pool.query(`DROP TRIGGER IF EXISTS "${triggerName}" ON ${table}`);
          }
        } catch (error) {
          console.warn(`⚠️ Trigger cleanup skipped for ${table}:`, error.message);
        }
      }
    }

