        // =====================================================
        // HOWDI V16.6J — ROLE CENTER LIFECYCLE UPGRADE
        // One HOWDI account can carry multiple public capability roles.
        // Internal staff roles remain in RBAC but are never exposed by My Roles.
        // =====================================================
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS role_status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE'`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS requested_at TIMESTAMPTZ`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS decided_at TIMESTAMPTZ`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS decided_by_reference VARCHAR(180)`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS rejection_reason TEXT`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS onboarding_state VARCHAR(40)`);
        await pool.query(`ALTER TABLE user_roles ADD COLUMN IF NOT EXISTS role_metadata JSONB NOT NULL DEFAULT '{}'::jsonb`);
        await pool.query(`UPDATE user_roles SET role_status='ACTIVE', requested_at=COALESCE(requested_at,created_at), decided_at=COALESCE(decided_at,created_at), onboarding_state=COALESCE(onboarding_state,'COMPLETE') WHERE role_status IS NULL OR role_status=''`);

        // CUSTOMER is a permanent base capability. It must never disappear when
        // another role (Creator, Vendor, Worker, Learner, Teacher) is activated.
        await pool.query(`
          INSERT INTO user_roles(user_id,role_id,is_primary,role_status,requested_at,decided_at,onboarding_state)
          SELECT
            u.id,
            r.id,
            CASE WHEN EXISTS(SELECT 1 FROM user_roles x WHERE x.user_id=u.id AND x.is_primary=TRUE) THEN FALSE ELSE TRUE END,
            'ACTIVE',
            COALESCE(u.created_at,NOW()),
            COALESCE(u.created_at,NOW()),
            'COMPLETE'
          FROM users u
          JOIN roles r ON r.code='CUSTOMER'
          ON CONFLICT(user_id,role_id)
          DO UPDATE SET
            role_status='ACTIVE',
            requested_at=COALESCE(user_roles.requested_at,EXCLUDED.requested_at),
            decided_at=COALESCE(user_roles.decided_at,EXCLUDED.decided_at),
            onboarding_state='COMPLETE',
            rejection_reason=NULL,
            updated_at=NOW();
        `);

