    const PORT = Number(process.env.PORT) || 5000;
    const HOST = "127.0.0.1";
    const DATA_DIR = path.join(__dirname, "data");

    const FILES = {
      users: path.join(DATA_DIR, "users.json"),
      orders: path.join(DATA_DIR, "orders.json"),
      addresses: path.join(DATA_DIR, "addresses.json"),
      categories: path.join(DATA_DIR, "categories.json"),
      subcategories: path.join(DATA_DIR, "subcategories.json"),
      products: path.join(DATA_DIR, "products.json"),
    };

    if (!fs.existsSync(DATA_DIR)) {
      fs.mkdirSync(DATA_DIR, {
        recursive: true,
      });
    }

    for (const file of Object.values(FILES)) {
      if (!fs.existsSync(file)) {
        fs.writeFileSync(
          file,
          "[]",
          "utf8"
        );
      }
    }


    // =====================================================
    // DATA HELPERS
    // =====================================================

    function readList(key) {
      try {
        const data = JSON.parse(
          fs.readFileSync(
            FILES[key],
            "utf8"
          )
        );

        return Array.isArray(data)
          ? data
          : [];
      } catch {
        return [];
      }
    }


    function saveList(key, value) {
      fs.writeFileSync(
        FILES[key],
        JSON.stringify(
          value,
          null,
          2
        ),
        "utf8"
      );
    }


    function id() {
      return crypto.randomUUID();
    }


    function customerId() {
      const date = new Date();

      const year = date.getFullYear();
      const month = String(
        date.getMonth() + 1
      ).padStart(2, "0");

      const day = String(
        date.getDate()
      ).padStart(2, "0");

      const random = crypto
        .randomBytes(3)
        .toString("hex")
        .toUpperCase();

      return `HOWDI-CUS-${year}${month}${day}-${random}`;
    }


    function hashPassword(password) {
      return crypto
        .createHash("sha256")
        .update(String(password))
        .digest("hex");
    }


    function now() {
      return new Date().toISOString();
    }



    // =====================================================
    // IDENTITY / LIFECYCLE HELPERS
    // =====================================================

    const ACCOUNT_STATUS_CODES = new Set([
      "PENDING",
      "ACTIVE",
      "SUSPENDED",
      "BLOCKED",
      "INACTIVE",
      "DELETED",
    ]);

    function normalizeAccountStatus(value) {
      return clean(value).toUpperCase();
    }

    function accountStatusAllowsLogin(status) {
      return normalizeAccountStatus(status) === "ACTIVE";
    }

    function accountStatusToIsActive(status) {
      return normalizeAccountStatus(status) === "ACTIVE";
    }

    function masterIdentityIdFromUserId(userId) {
      return `HWD-M-${String(userId).padStart(7, "0")}`;
    }


    function clean(value, fallback = "") {
      if (
        value === undefined ||
        value === null
      ) {
        return fallback;
      }

      return String(value).trim();
    }


    function number(value, fallback = 0) {
      const n = Number(value);

      return Number.isFinite(n)
        ? n
        : fallback;
    }


    function bool(value, fallback = true) {
      return typeof value === "boolean"
        ? value
        : fallback;
    }

    // =====================================================
    // RESPONSE HELPERS
    // =====================================================

    function sendJSON(
      res,
      statusCode,
      data
    ) {
      res.writeHead(
        statusCode,
        {
          "Content-Type":
            "application/json; charset=utf-8",

          "Access-Control-Allow-Origin":
            "*",

          "Access-Control-Allow-Methods":
            "GET,POST,PUT,PATCH,DELETE,OPTIONS",

          "Access-Control-Allow-Headers":
            "Content-Type, Authorization, x-howdi-admin-token, x-howdi-worker-id",
        }
      );

      res.end(
        JSON.stringify(data)
      );
    }


    // =====================================================
    // REQUEST BODY
    // =====================================================

    function getBody(req) {
      return new Promise(
        (
          resolve,
          reject
        ) => {
          let body = "";

          req.on(
            "data",
            (chunk) => {
              body += chunk.toString();

              if (
                body.length >
                12 * 1024 * 1024
              ) {
                req.destroy();

                reject(
                  new Error(
                    "Request too large"
                  )
                );
              }
            }
          );

          req.on(
            "end",
            () => {
              try {
                resolve(
                  body
                    ? JSON.parse(body)
                    : {}
                );
              } catch {
                reject(
                  new Error(
                    "Invalid JSON"
                  )
                );
              }
            }
          );

          req.on(
            "error",
            reject
          );
        }
      );
    }


    // =====================================================
    // URL HELPER
    // =====================================================

    function requestURL(req) {
      return new URL(
        req.url,
        `http://${HOST}:${PORT}`
      );
    }


    // =====================================================
    // ADDRESS HELPERS
    // =====================================================

    function normalizeAddress(
      body,
      existing = {}
    ) {
      return {
        ...existing,

        label:
          clean(
            body.label ??
            existing.label ??
            "Home"
          ) || "Other",

        full_name:
          clean(
            body.full_name ??
            body.fullName ??
            existing.full_name
          ),

        phone:
          clean(
            body.phone ??
            existing.phone
          )
            .replace(/\D/g, "")
            .slice(0, 10),

        address_line1:
          clean(
            body.address_line1 ??
            body.addressLine1 ??
            existing.address_line1
          ),

        address_line2:
          clean(
            body.address_line2 ??
            body.addressLine2 ??
            existing.address_line2
          ),

        city:
          clean(
            body.city ??
            existing.city
          ),

        state:
          clean(
            body.state ??
            existing.state
          ),

        pincode:
          clean(
            body.pincode ??
            existing.pincode
          )
            .replace(/\D/g, "")
            .slice(0, 6),

        updated_at:
          now(),
      };
    }


    function validateAddress(address) {
      if (!address.full_name) {
        return "Full name is required";
      }

      if (
        !/^[0-9]{10}$/.test(
          address.phone
        )
      ) {
        return "A valid 10-digit mobile number is required";
      }

      if (
        !address.address_line1
      ) {
        return "Address line 1 is required";
      }

      if (!address.city) {
        return "City is required";
      }

      if (!address.state) {
        return "State is required";
      }

      if (
        !/^[1-9][0-9]{5}$/.test(
          address.pincode
        )
      ) {
        return "A valid 6-digit pincode is required";
      }

      return null;
    }


    // =====================================================
    // CATEGORY HELPERS
    // =====================================================

    function normalizeCategory(
      body,
      existing = {}
    ) {
      return {
        ...existing,

        name:
          clean(
            body.name,
            existing.name || ""
          ),

        icon:
          clean(
            body.icon,
            existing.icon || "🧶"
          ) || "🧶",

        description:
          clean(
            body.description,
            existing.description || ""
          ),

        visible:
          bool(
            body.visible,
            existing.visible !== false
          ),

        showOnHome:
          bool(
            body.showOnHome,
            existing.showOnHome !== false
          ),

        updatedAt:
          now(),
      };
    }


    // =====================================================
    // SUBCATEGORY HELPERS
    // =====================================================

    function normalizeSubcategory(
      body,
      existing = {}
    ) {
      return {
        ...existing,

        categoryId:
          clean(
            body.categoryId ??
            body.category_id,
            existing.categoryId || ""
          ),

        name:
          clean(
            body.name,
            existing.name || ""
          ),

        icon:
          clean(
            body.icon,
            existing.icon || "🧶"
          ) || "🧶",

        visible:
          bool(
            body.visible,
            existing.visible !== false
          ),

        updatedAt:
          now(),
      };
    }


    // =====================================================
    // PRODUCT HELPERS
    // =====================================================

    function normalizeProduct(
      body,
      existing = {}
    ) {
      const mrp = Math.max(0, number(
        body.mrp,
        number(existing.mrp, number(existing.price, 0))
      ));

      const sellingPrice = Math.max(0, number(
        body.sellingPrice ?? body.selling_price ?? body.price,
        number(existing.sellingPrice, number(existing.price, mrp))
      ));

      const offerPrice = Math.max(0, number(
        body.offerPrice ?? body.offer_price ?? body.discountPrice ?? body.discount_price,
        number(existing.offerPrice, sellingPrice)
      ));

      const effectivePrice = offerPrice > 0 ? offerPrice : sellingPrice;

      const discountPercent =
        mrp > 0 && effectivePrice >= 0 && effectivePrice < mrp
          ? Number((((mrp - effectivePrice) / mrp) * 100).toFixed(2))
          : 0;

      const platformChargePercent = Math.max(0, number(
        body.platformChargePercent ?? body.platform_charge_percent,
        number(existing.platformChargePercent, 0)
      ));

      const platformChargeAmount = Number(
        ((effectivePrice * platformChargePercent) / 100).toFixed(2)
      );

      const requestedStatus = clean(
        body.status,
        existing.status || "active"
      ).toLowerCase();

      const normalizeMedia = (value, fallback = []) => {
        const source = Array.isArray(value)
          ? value
          : Array.isArray(fallback)
            ? fallback
            : [];

        return source
          .slice(0, 8)
          .map((item, index) => ({
            id: clean(item?.id, `media-${index + 1}`) || `media-${index + 1}`,
            url: clean(item?.url ?? item?.src ?? ""),
            name: clean(item?.name, ""),
            type: clean(item?.type, ""),
          }))
          .filter((item) => item.url);
      };

      const normalizeSpecifications = (value, fallback = []) => {
        const source = Array.isArray(value)
          ? value
          : Array.isArray(fallback)
            ? fallback
            : [];

        return source
          .slice(0, 40)
          .map((item) => ({
            label: clean(item?.label ?? item?.name ?? ""),
            value: clean(item?.value ?? ""),
          }))
          .filter((item) => item.label || item.value);
      };

      const requestedUnit = clean(
        body.unit,
        existing.unit || "piece"
      ).toLowerCase();

      const unit = [
        "piece",
        "kg",
        "gram",
        "litre",
        "ml",
        "pack",
        "box",
        "set",
        "bundle",
        "metre",
        "dozen",
      ].includes(requestedUnit)
        ? requestedUnit
        : "piece";

      const requestedInventoryType = clean(
        body.inventoryType,
        existing.inventoryType || "simple"
      ).toLowerCase();

      const inventoryType = [
        "simple",
        "variant",
        "bulk",
      ].includes(requestedInventoryType)
        ? requestedInventoryType
        : "simple";

      const requestedDeliveryMode = clean(
        body.deliveryMode,
        existing.deliveryMode || "platform"
      ).toLowerCase();

      const deliveryMode = [
        "platform",
        "free",
        "paid",
        "conditional",
      ].includes(requestedDeliveryMode)
        ? requestedDeliveryMode
        : "platform";

      return {
        ...existing,

        // PRODUCT IDENTITY
        name: clean(body.name, existing.name || ""),
        summary: clean(
          body.summary ?? body.shortSummary,
          existing.summary ?? existing.shortSummary ?? ""
        ),
        description: clean(body.description, existing.description || ""),
        brand: clean(body.brand, existing.brand || ""),
        productType: clean(
          body.productType ?? body.product_type,
          existing.productType || ""
        ),
        sku: clean(body.sku, existing.sku || ""),
        barcode: clean(body.barcode, existing.barcode || ""),
        hsnCode: clean(
          body.hsnCode ?? body.hsn_code,
          existing.hsnCode || ""
        ),

        categoryId: clean(
          body.categoryId ?? body.category_id,
          existing.categoryId || ""
        ),

        subcategoryId: clean(
          body.subcategoryId ?? body.subcategory_id,
          existing.subcategoryId || ""
        ),

        subcategory: clean(
          body.subcategory,
          existing.subcategory || ""
        ),

        tags: Array.isArray(body.tags)
          ? body.tags.map((item) => clean(item)).filter(Boolean)
          : typeof body.tags === "string"
            ? body.tags.split(",").map((item) => clean(item)).filter(Boolean)
            : Array.isArray(existing.tags)
              ? existing.tags
              : [],

        icon: clean(
          body.icon,
          existing.icon || "🧶"
        ) || "🧶",

        // MEDIA
        media: normalizeMedia(
          body.media,
          existing.media
        ),

        // CUSTOMER CONTENT
        material: clean(
          body.material,
          existing.material || ""
        ),
        usage: clean(
          body.usage,
          existing.usage || ""
        ),
        care: clean(
          body.care,
          existing.care || ""
        ),
        specifications: normalizeSpecifications(
          body.specifications,
          existing.specifications
        ),
        sizeType: clean(
          body.sizeType,
          existing.sizeType || "standard"
        ) || "standard",
        freeSize: bool(
          body.freeSize,
          existing.freeSize === true
        ),
        washable: bool(
          body.washable,
          existing.washable === true
        ),
        washType: clean(
          body.washType,
          existing.washType || ""
        ),
        ironable: bool(
          body.ironable,
          existing.ironable === true
        ),
        ironTemperature: clean(
          body.ironTemperature,
          existing.ironTemperature || ""
        ),

        // PRICING
        mrp,
        sellingPrice,
        offerPrice,
        discountPercent,

        // Backward compatibility with existing customer/admin code
        price: effectivePrice,

        // COMMERCIAL
        costPrice: Math.max(0, number(
          body.costPrice ?? body.cost_price ?? body.vendorPrice ?? body.vendor_price,
          number(existing.costPrice, 0)
        )),

        gstPercent: Math.max(0, number(
          body.gstPercent ?? body.gst_percent,
          number(existing.gstPercent, 0)
        )),

        platformChargePercent,
        platformChargeAmount,

        appliedOfferCode: clean(
          body.appliedOfferCode,
          existing.appliedOfferCode || ""
        ),

        // INVENTORY / UNITS
        inventoryType,
        unit,
        netWeight: Math.max(0, number(
          body.netWeight,
          number(existing.netWeight, 0)
        )),
        stock: Math.max(0, number(
          body.stock,
          number(existing.stock, 0)
        )),
        lowStockThreshold: Math.max(0, number(
          body.lowStockThreshold ?? body.low_stock_threshold,
          number(existing.lowStockThreshold, 5)
        )),

        // SHIPPING / DELIVERY
        deliveryMode,
        deliveryCharge: Math.max(0, number(
          body.deliveryCharge,
          number(existing.deliveryCharge, 0)
        )),
        freeDeliveryAbove: Math.max(0, number(
          body.freeDeliveryAbove,
          number(existing.freeDeliveryAbove, 0)
        )),
        packageLength: Math.max(0, number(
          body.packageLength,
          number(existing.packageLength, 0)
        )),
        packageWidth: Math.max(0, number(
          body.packageWidth,
          number(existing.packageWidth, 0)
        )),
        packageHeight: Math.max(0, number(
          body.packageHeight,
          number(existing.packageHeight, 0)
        )),

        // RETURNS / CUSTOMISATION
        returnable: bool(
          body.returnable,
          existing.returnable !== false
        ),
        returnDays: Math.max(0, number(
          body.returnDays,
          number(existing.returnDays, 7)
        )),
        customizationAvailable: bool(
          body.customizationAvailable,
          existing.customizationAvailable === true
        ),
        customizationNote: clean(
          body.customizationNote,
          existing.customizationNote || ""
        ),

        // STATUS
        status: [
          "draft",
          "active",
          "inactive",
          "archived"
        ].includes(requestedStatus)
          ? requestedStatus
          : "draft",

        visible: bool(
          body.visible,
          existing.visible !== false
        ),

        // CUSTOMER DISPLAY
        featured: bool(
          body.featured,
          existing.featured === true
        ),

        newArrival: bool(
          body.newArrival ?? body.new_arrival,
          existing.newArrival === true
        ),

        bestSeller: bool(
          body.bestSeller ?? body.best_seller,
          existing.bestSeller === true
        ),

        offerProduct: bool(
          body.offerProduct ?? body.offer_product,
          existing.offerProduct === true
        ),

        updatedAt: now(),
      };
    }

