    // =====================================================
    // POSTGRESQL ADDRESS BOOK HELPERS
    // =====================================================
    function normalizePostgresAddress(body = {}, existing = {}) {
      const phone = clean(body.phone ?? body.mobile ?? existing.phone ?? "").replace(/\D/g, "").slice(0, 15);
      const pincode = clean(body.pincode ?? body.pin_code ?? existing.pincode ?? "").replace(/\D/g, "").slice(0, 12);
      return {
        label: clean(body.label ?? existing.label ?? "Home") || "Home",
        full_name: clean(body.full_name ?? body.fullName ?? existing.full_name ?? ""),
        phone,
        address_line1: clean(body.address_line1 ?? body.addressLine1 ?? body.house ?? existing.address_line1 ?? ""),
        address_line2: clean(body.address_line2 ?? body.addressLine2 ?? body.area ?? existing.address_line2 ?? ""),
        landmark: clean(body.landmark ?? existing.landmark ?? ""),
        city: clean(body.city ?? existing.city ?? ""),
        state: clean(body.state ?? existing.state ?? ""),
        pincode,
        country: clean(body.country ?? existing.country ?? "India") || "India",
        address_type: (clean(body.address_type ?? body.addressType ?? body.type ?? existing.address_type ?? "HOME") || "HOME").toUpperCase(),
        is_default: typeof body.is_default === "boolean" ? body.is_default : typeof body.isDefault === "boolean" ? body.isDefault : !!existing.is_default,
      };
    }
    function validatePostgresAddress(a) {
      if (!a.full_name) return "Full name is required";
      if (!a.phone || a.phone.length < 6) return "Valid mobile number is required";
      if (!a.address_line1) return "House / building / address line is required";
      if (!a.city) return "City is required";
      if (!a.state) return "State is required";
      if (!a.pincode || a.pincode.length < 4) return "Valid pincode is required";
      return "";
    }
    // =====================================================
    // SECURITY HELPERS
    // =====================================================

    function getRequestIp(req) {
      const forwarded = String(req.headers["x-forwarded-for"] || "").split(",")[0].trim();
      return forwarded || req.socket?.remoteAddress || "";
    }

    function getBrowserName(userAgent = "") {
      const ua = String(userAgent);
      if (/Edg\//i.test(ua)) return "Microsoft Edge";
      if (/Firefox\//i.test(ua)) return "Firefox";
      if (/Chrome\//i.test(ua)) return "Google Chrome";
      if (/Safari\//i.test(ua)) return "Safari";
      return "Unknown browser";
    }

    function getDeviceName(userAgent = "") {
      const ua = String(userAgent);
      if (/iPhone/i.test(ua)) return "iPhone";
      if (/Android/i.test(ua) && /Mobile/i.test(ua)) return "Android phone";
      if (/iPad|Tablet/i.test(ua)) return "Tablet";
      return "Computer";
    }

    function createSessionToken(userId) {
      return "howdi-session-" + Buffer.from(
        `${userId}:${Date.now()}:${crypto.randomBytes(18).toString("hex")}`
      ).toString("base64url");
    }

    async function logSecurityEvent({
      userId,
      eventType,
      eventMessage = "",
      req = null,
      metadata = {},
    }) {
      if (!userId) return;
      const userAgent = req ? String(req.headers["user-agent"] || "") : "";
      await pool.query(
        `
          INSERT INTO user_security_events
          (user_id, event_type, event_message, device_name, browser_name, ip_address, metadata)
          VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb)
        `,
        [
          userId,
          eventType,
          eventMessage,
          getDeviceName(userAgent),
          getBrowserName(userAgent),
          req ? getRequestIp(req) : "",
          JSON.stringify(metadata || {}),
        ]
      );
    }

    async function createUserSession(userId, req) {
      const userAgent = String(req.headers["user-agent"] || "");
      const sessionToken = createSessionToken(userId);

      const result = await pool.query(
        `
          INSERT INTO user_sessions
          (user_id, session_token, device_name, browser_name, ip_address)
          VALUES ($1, $2, $3, $4, $5)
          RETURNING id, user_id, device_name, browser_name, ip_address, created_at, last_seen_at
        `,
        [
          userId,
          sessionToken,
          getDeviceName(userAgent),
          getBrowserName(userAgent),
          getRequestIp(req),
        ]
      );

      return {
        session: result.rows[0],
        token: sessionToken,
      };
    }



    async function getSessionUserFromRequest(req) {
      const auth = String(req.headers.authorization || "");
      const token = auth.toLowerCase().startsWith("bearer ") ? auth.slice(7).trim() : "";
      if (!token) return null;
      const result = await pool.query(`
        SELECT u.*
        FROM user_sessions s
        JOIN users u ON u.id=s.user_id
        WHERE s.session_token=$1 AND s.is_active=TRUE
        LIMIT 1
      `,[token]);
      if (!result.rows[0]) return null;
      await pool.query(`UPDATE user_sessions SET last_seen_at=NOW() WHERE session_token=$1`,[token]).catch(()=>{});
      return result.rows[0];
    }


    function adminTokenHash(token){
      return crypto.createHash("sha256").update(String(token||"")).digest("hex");
    }
    function newAdminSessionToken(){
      return "howdi-admin-" + crypto.randomBytes(32).toString("hex");
    }
    async function createPersistentAdminSession(username,req){
      const rawToken=newAdminSessionToken();
      const hours=Math.max(1,Math.min(168,Number(process.env.ADMIN_SESSION_HOURS||12)));
      const row=(await pool.query(`
        INSERT INTO howdi_admin_sessions(username,token_hash,ip_address,user_agent,expires_at)
        VALUES($1,$2,$3,$4,NOW()+($5||' hours')::interval)
        RETURNING id,username,created_at,last_seen_at,expires_at
      `,[username,adminTokenHash(rawToken),getRequestIp(req),String(req.headers["user-agent"]||"").slice(0,1000),String(hours)])).rows[0];
      await pool.query(`
        INSERT INTO howdi_admin_security_audit(session_id,username,action,method,path,ip_address,metadata)
        VALUES($1::uuid,$2,'ADMIN_LOGIN_SUCCESS',$3,$4,$5,$6::jsonb)
      `,[row.id,username,req.method,req.url,getRequestIp(req),JSON.stringify({session_hours:hours})]);
      return {token:rawToken,session:row};
    }
    async function getAdminSessionFromRequest(req){
      const raw=String(req.headers["x-howdi-admin-token"]||"").trim();
      if(!raw)return null;
      const row=(await pool.query(`
        SELECT id,username,ip_address,user_agent,is_active,created_at,last_seen_at,expires_at
        FROM howdi_admin_sessions
        WHERE token_hash=$1 AND is_active=TRUE AND expires_at>NOW()
        LIMIT 1
      `,[adminTokenHash(raw)])).rows[0];
      if(!row)return null;
      await pool.query(`UPDATE howdi_admin_sessions SET last_seen_at=NOW() WHERE id=$1::uuid`,[row.id]).catch(()=>{});
      return row;
    }
    async function auditAdminSecurity(req,session,action,metadata={}){
      await pool.query(`
        INSERT INTO howdi_admin_security_audit(session_id,username,action,method,path,ip_address,metadata)
        VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)
      `,[session?.id||null,session?.username||null,action,req.method,req.url,getRequestIp(req),JSON.stringify(metadata||{})]).catch(()=>{});
    }
