    async function ensureHPayTables() {
      await pool.query(`
        CREATE TABLE IF NOT EXISTS hpay_accounts (
          id BIGSERIAL PRIMARY KEY,
          user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
          hpay_id VARCHAR(120) NOT NULL UNIQUE,
          status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
          kyc_status VARCHAR(30) NOT NULL DEFAULT 'BASIC',
          single_limit NUMERIC(14,2) NOT NULL DEFAULT 25000,
          daily_limit NUMERIC(14,2) NOT NULL DEFAULT 100000,
          risk_level VARCHAR(20) NOT NULL DEFAULT 'LOW',
          qr_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          upi_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          bank_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          requests_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          chat_pay_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_transactions (
          id BIGSERIAL PRIMARY KEY,
          transaction_id VARCHAR(80) NOT NULL UNIQUE,
          transaction_type VARCHAR(30) NOT NULL,
          sender_account_id BIGINT REFERENCES hpay_accounts(id) ON DELETE SET NULL,
          receiver_account_id BIGINT REFERENCES hpay_accounts(id) ON DELETE SET NULL,
          amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
          currency VARCHAR(3) NOT NULL DEFAULT 'INR',
          method VARCHAR(40) NOT NULL DEFAULT 'HPAY',
          status VARCHAR(30) NOT NULL DEFAULT 'CREATED',
          provider VARCHAR(80),
          provider_reference VARCHAR(180),
          client_reference VARCHAR(180),
          description TEXT,
          risk_level VARCHAR(20) NOT NULL DEFAULT 'LOW',
          risk_reason TEXT,
          metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          completed_at TIMESTAMPTZ
        );

        CREATE TABLE IF NOT EXISTS hpay_payment_requests (
          id BIGSERIAL PRIMARY KEY,
          request_id VARCHAR(80) NOT NULL UNIQUE,
          requester_account_id BIGINT NOT NULL REFERENCES hpay_accounts(id) ON DELETE CASCADE,
          payer_account_id BIGINT REFERENCES hpay_accounts(id) ON DELETE SET NULL,
          amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
          currency VARCHAR(3) NOT NULL DEFAULT 'INR',
          note VARCHAR(300),
          status VARCHAR(30) NOT NULL DEFAULT 'PENDING',
          expires_at TIMESTAMPTZ,
          transaction_id BIGINT REFERENCES hpay_transactions(id) ON DELETE SET NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_qr_codes (
          id BIGSERIAL PRIMARY KEY,
          account_id BIGINT NOT NULL REFERENCES hpay_accounts(id) ON DELETE CASCADE,
          qr_reference VARCHAR(120) NOT NULL UNIQUE,
          qr_type VARCHAR(30) NOT NULL DEFAULT 'PERSONAL',
          amount NUMERIC(14,2),
          label VARCHAR(120),
          is_active BOOLEAN NOT NULL DEFAULT TRUE,
          expires_at TIMESTAMPTZ,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_bank_accounts (
          id BIGSERIAL PRIMARY KEY,
          account_id BIGINT NOT NULL REFERENCES hpay_accounts(id) ON DELETE CASCADE,
          account_holder_name VARCHAR(180) NOT NULL,
          bank_name VARCHAR(180),
          account_number_masked VARCHAR(40) NOT NULL,
          account_number_token TEXT,
          ifsc VARCHAR(20),
          verification_status VARCHAR(30) NOT NULL DEFAULT 'PENDING',
          is_default BOOLEAN NOT NULL DEFAULT FALSE,
          is_active BOOLEAN NOT NULL DEFAULT TRUE,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_refunds (
          id BIGSERIAL PRIMARY KEY,
          refund_id VARCHAR(80) NOT NULL UNIQUE,
          transaction_id BIGINT NOT NULL REFERENCES hpay_transactions(id) ON DELETE RESTRICT,
          amount NUMERIC(14,2) NOT NULL CHECK (amount > 0),
          reason VARCHAR(300),
          status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED',
          provider_reference VARCHAR(180),
          requested_by VARCHAR(120),
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          completed_at TIMESTAMPTZ
        );

        CREATE TABLE IF NOT EXISTS hpay_status_history (
          id BIGSERIAL PRIMARY KEY,
          transaction_id BIGINT NOT NULL REFERENCES hpay_transactions(id) ON DELETE CASCADE,
          old_status VARCHAR(30),
          new_status VARCHAR(30) NOT NULL,
          source VARCHAR(50) NOT NULL DEFAULT 'SYSTEM',
          note TEXT,
          metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_risk_events (
          id BIGSERIAL PRIMARY KEY,
          account_id BIGINT REFERENCES hpay_accounts(id) ON DELETE SET NULL,
          transaction_id BIGINT REFERENCES hpay_transactions(id) ON DELETE SET NULL,
          severity VARCHAR(20) NOT NULL DEFAULT 'LOW',
          event_type VARCHAR(80) NOT NULL,
          reason TEXT,
          status VARCHAR(30) NOT NULL DEFAULT 'OPEN',
          reviewed_by VARCHAR(120),
          reviewed_at TIMESTAMPTZ,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_audit_logs (
          id BIGSERIAL PRIMARY KEY,
          actor_type VARCHAR(30) NOT NULL DEFAULT 'SYSTEM',
          actor_id VARCHAR(120),
          action VARCHAR(120) NOT NULL,
          entity_type VARCHAR(80),
          entity_id VARCHAR(120),
          ip_address VARCHAR(100),
          metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        CREATE TABLE IF NOT EXISTS hpay_platform_settings (
          id SMALLINT PRIMARY KEY DEFAULT 1 CHECK (id = 1),
          enabled BOOLEAN NOT NULL DEFAULT TRUE,
          qr_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          upi_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          bank_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          requests_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          chat_pay_enabled BOOLEAN NOT NULL DEFAULT TRUE,
          auto_refund_enabled BOOLEAN NOT NULL DEFAULT FALSE,
          default_single_limit NUMERIC(14,2) NOT NULL DEFAULT 25000,
          default_daily_limit NUMERIC(14,2) NOT NULL DEFAULT 100000,
          risk_mode VARCHAR(20) NOT NULL DEFAULT 'BALANCED',
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );

        INSERT INTO hpay_platform_settings(id)
        VALUES (1)
        ON CONFLICT (id) DO NOTHING;

        CREATE INDEX IF NOT EXISTS hpay_transactions_status_idx ON hpay_transactions(status);
        CREATE INDEX IF NOT EXISTS hpay_transactions_created_idx ON hpay_transactions(created_at DESC);
        CREATE INDEX IF NOT EXISTS hpay_transactions_sender_idx ON hpay_transactions(sender_account_id);
        CREATE INDEX IF NOT EXISTS hpay_transactions_receiver_idx ON hpay_transactions(receiver_account_id);
        CREATE INDEX IF NOT EXISTS hpay_requests_status_idx ON hpay_payment_requests(status);
        CREATE INDEX IF NOT EXISTS hpay_risk_status_idx ON hpay_risk_events(status, severity);
      `);
    }












    async function getAdminPaymentTransactions(searchText='',statusFilter='all'){
      const search=clean(searchText);
      const status=String(statusFilter||'all').toUpperCase();
      const params=[];
      const where=[];

      if(search){
        params.push(`%${search}%`);
        where.push(`(
          p.transaction_code ILIKE $${params.length}
          OR COALESCE(o.order_number,'') ILIKE $${params.length}
          OR COALESCE(u.full_name,'') ILIKE $${params.length}
          OR COALESCE(u.howdi_id,'') ILIKE $${params.length}
          OR COALESCE(p.reference,'') ILIKE $${params.length}
          OR COALESCE(p.provider_payment_id,'') ILIKE $${params.length}
        )`);
      }

      if(status!=='ALL'){
        params.push(status);
        where.push(`p.status=$${params.length}`);
      }

      const rows=(await pool.query(`
        SELECT
          p.*,
          o.order_number,
          o.status AS order_status,
          o.payment_status AS order_payment_status,
          o.grand_total AS order_total,
          u.full_name AS customer_name,
          u.howdi_id,
          u.email AS customer_email,
          u.phone AS customer_phone,
          COALESCE(
            (
              SELECT jsonb_agg(jsonb_build_object(
                'id',e.id,
                'event_type',e.event_type,
                'from_status',e.from_status,
                'to_status',e.to_status,
                'actor',e.actor,
                'note',e.note,
                'created_at',e.created_at
              ) ORDER BY e.created_at DESC)
              FROM payment_transaction_events e
              WHERE e.transaction_id=p.id
            ),
            '[]'::jsonb
          ) AS events
        FROM payment_transactions p
        LEFT JOIN orders o ON o.id=p.order_id
        LEFT JOIN users u ON u.id=p.customer_user_id
        ${where.length?'WHERE '+where.join(' AND '):''}
        ORDER BY p.created_at DESC,p.id DESC
        LIMIT 500
      `,params)).rows;

      const summary=(await pool.query(`
        SELECT
          COUNT(*)::int AS total_count,
          COALESCE(SUM(amount),0)::numeric AS total_value,
          COALESCE(SUM(amount) FILTER(WHERE status='PAID'),0)::numeric AS paid_value,
          COALESCE(SUM(amount) FILTER(WHERE status IN ('PENDING','INITIATED','PROCESSING')),0)::numeric AS pending_value,
          COALESCE(SUM(amount) FILTER(WHERE status IN ('REFUNDED','REFUND_PENDING')),0)::numeric AS refunded_value,
          COUNT(*) FILTER(WHERE status='FAILED')::int AS failed_count
        FROM payment_transactions
      `)).rows[0];

      return {rows,summary};
    }

    async function updateAdminPaymentTransactionStatus(transactionId,nextStatus,actor='ADMIN'){
      const allowed=new Set(['PENDING','INITIATED','PROCESSING','PAID','FAILED','REFUND_PENDING','REFUNDED']);
      const status=String(nextStatus||'').toUpperCase();
      if(!allowed.has(status))throw new Error("Unsupported payment status");

      const client=await pool.connect();
      try{
        await client.query('BEGIN');
        const current=(await client.query(`
          SELECT * FROM payment_transactions WHERE id=$1 FOR UPDATE
        `,[Number(transactionId)])).rows[0];
        if(!current)throw new Error("Payment transaction not found");

        const now=new Date();
        const q=(await client.query(`
          UPDATE payment_transactions
          SET status=$1,
              paid_at=CASE WHEN $1='PAID' THEN COALESCE(paid_at,NOW()) ELSE paid_at END,
              failed_at=CASE WHEN $1='FAILED' THEN COALESCE(failed_at,NOW()) ELSE failed_at END,
              refunded_at=CASE WHEN $1='REFUNDED' THEN COALESCE(refunded_at,NOW()) ELSE refunded_at END,
              source=CASE WHEN source='ORDER_BACKFILL' THEN 'ADMIN_OPERATION' ELSE source END,
              updated_at=NOW()
          WHERE id=$2
          RETURNING *
        `,[status,Number(transactionId)])).rows[0];

        await client.query(`
          INSERT INTO payment_transaction_events(
            transaction_id,event_type,from_status,to_status,actor,note,metadata
          ) VALUES($1,'STATUS_UPDATED',$2,$3,$4,$5,$6::jsonb)
        `,[
          q.id,current.status,status,clean(actor)||'ADMIN',
          'Operational payment status updated from HOWDI Admin',
          JSON.stringify({manual:true,at:now.toISOString()})
        ]);

        // Keep the linked commerce order aligned with the payment ledger.
        // This is an operational override, not a gateway webhook.
        if(q.order_id){
          await client.query(`
            UPDATE orders
            SET payment_status=$1,updated_at=NOW()
            WHERE id=$2
          `,[status,q.order_id]);
        }

        if(q.order_id){
          await reconcileVibePaymentConversionPipelineV152E(client,q.order_id,'PAYMENT_STATUS_UPDATED');
        }
        await client.query('COMMIT');
        return q;
      }catch(error){
        await client.query('ROLLBACK');
        throw error;
      }finally{
        client.release();
      }
    }


    async function getPaymentRefundControl(transactionId){
      const tx=(await pool.query(`
        SELECT p.*,o.order_number
        FROM payment_transactions p
        LEFT JOIN orders o ON o.id=p.order_id
        WHERE p.id=$1
        LIMIT 1
      `,[Number(transactionId)])).rows[0];
      if(!tx)throw new Error("Payment transaction not found");

      const refunds=(await pool.query(`
        SELECT
          r.*,
          COALESCE(
            (
              SELECT jsonb_agg(jsonb_build_object(
                'id',e.id,
                'event_type',e.event_type,
                'from_status',e.from_status,
                'to_status',e.to_status,
                'actor',e.actor,
                'note',e.note,
                'created_at',e.created_at
              ) ORDER BY e.created_at DESC)
              FROM payment_refund_events e
              WHERE e.refund_id=r.id
            ),
            '[]'::jsonb
          ) AS events
        FROM payment_refunds r
        WHERE r.transaction_id=$1
        ORDER BY r.created_at DESC,r.id DESC
      `,[tx.id])).rows;

      const reserved=refunds
        .filter(r=>['REQUESTED','APPROVED','PROCESSED'].includes(r.status))
        .reduce((n,r)=>n+Number(r.amount||0),0);

      const processed=refunds
        .filter(r=>r.status==='PROCESSED')
        .reduce((n,r)=>n+Number(r.amount||0),0);

      return {
        transaction:tx,
        refunds,
        summary:{
          paymentAmount:Number(tx.amount||0),
          reservedRefundAmount:reserved,
          processedRefundAmount:processed,
          refundableAmount:Math.max(0,Number(tx.amount||0)-reserved),
          remainingAfterProcessed:Math.max(0,Number(tx.amount||0)-processed)
        }
      };
    }

    async function createPaymentRefund(transactionId,body={}){
      const amount=Number(body.amount||0);
      if(!Number.isFinite(amount)||amount<=0)throw new Error("Refund amount must be greater than 0");
      const reason=clean(body.reason);if(!reason)throw new Error("Refund reason is required");
      const actor=clean(body.actor)||'ADMIN',client=await pool.connect();
      try{
        await client.query('BEGIN');
        const tx=(await client.query(`SELECT * FROM payment_transactions WHERE id=$1 FOR UPDATE`,[Number(transactionId)])).rows[0];
        if(!tx)throw new Error("Payment transaction not found");
        if(!['PAID','REFUND_PENDING'].includes(String(tx.status).toUpperCase()))throw new Error("Refund can be requested only for a paid payment");
        const reserved=Number((await client.query(`SELECT COALESCE(SUM(amount),0)::numeric n FROM payment_refunds
          WHERE transaction_id=$1 AND status IN ('REQUESTED','APPROVED','PROCESSED')`,[tx.id])).rows[0]?.n||0);
        const refundable=Math.max(0,Number(tx.amount||0)-reserved);
        if(amount>refundable+0.0001)throw new Error(`Refund exceeds refundable amount ₹${refundable.toFixed(2)}`);
        const code=`RFD-${Date.now()}-${Math.floor(Math.random()*9000+1000)}`;
        const refund=(await client.query(`INSERT INTO payment_refunds(refund_code,transaction_id,order_id,amount,currency,reason,status,requested_by,admin_note)
          VALUES($1,$2,$3,$4,$5,$6,'REQUESTED',$7,$8) RETURNING *`,
          [code,tx.id,tx.order_id,amount,tx.currency||'INR',reason,actor,clean(body.admin_note)||null])).rows[0];
        await client.query(`INSERT INTO payment_refund_events(refund_id,event_type,from_status,to_status,actor,note,metadata)
          VALUES($1,'REFUND_REQUESTED',NULL,'REQUESTED',$2,$3,$4::jsonb)`,
          [refund.id,actor,reason,JSON.stringify({amount,currency:tx.currency||'INR',integrityVersion:'V15.3A'})]);
        await client.query('COMMIT');return refund;
      }catch(error){try{await client.query('ROLLBACK')}catch{};throw error}finally{client.release()}
    }

    async function transitionPaymentRefund(refundId,action,body={}){
      const actor=clean(body.actor)||'ADMIN';
      const note=clean(body.note)||null;
      const externalReference=clean(body.external_refund_reference)||null;
      const client=await pool.connect();

      try{
        await client.query('BEGIN');

        const refund=(await client.query(`
          SELECT r.*,p.amount AS payment_amount,p.status AS payment_status
          FROM payment_refunds r
          JOIN payment_transactions p ON p.id=r.transaction_id
          WHERE r.id=$1
          FOR UPDATE OF r
        `,[Number(refundId)])).rows[0];
        if(!refund)throw new Error("Refund record not found");

        const current=String(refund.status||'').toUpperCase();
        let next=current;
        let event='REFUND_UPDATED';

        if(action==='approve'){
          if(current!=='REQUESTED')throw new Error("Only requested refunds can be approved");
          next='APPROVED'; event='REFUND_APPROVED';
        }else if(action==='reject'){
          if(!['REQUESTED','APPROVED'].includes(current))throw new Error("Refund cannot be rejected from this status");
          if(!note)throw new Error("Rejection note is required");
          next='REJECTED'; event='REFUND_REJECTED';
        }else if(action==='processed'){
          if(current!=='APPROVED')throw new Error("Only approved refunds can be marked processed");
          if(!externalReference)throw new Error("External refund / gateway reference is required");
          next='PROCESSED'; event='REFUND_PROCESSED';
        }else if(action==='failed'){
          if(current!=='APPROVED')throw new Error("Only approved refunds can be marked failed");
          if(!note)throw new Error("Failure note is required");
          next='FAILED'; event='REFUND_FAILED';
        }else{
          throw new Error("Unsupported refund action");
        }

        const updated=(await client.query(`
          UPDATE payment_refunds
          SET status=$1,
              approved_by=CASE WHEN $1='APPROVED' THEN $2 ELSE approved_by END,
              approved_at=CASE WHEN $1='APPROVED' THEN NOW() ELSE approved_at END,
              rejected_by=CASE WHEN $1='REJECTED' THEN $2 ELSE rejected_by END,
              rejected_at=CASE WHEN $1='REJECTED' THEN NOW() ELSE rejected_at END,
              processed_by=CASE WHEN $1='PROCESSED' THEN $2 ELSE processed_by END,
              processed_at=CASE WHEN $1='PROCESSED' THEN NOW() ELSE processed_at END,
              failed_by=CASE WHEN $1='FAILED' THEN $2 ELSE failed_by END,
              failed_at=CASE WHEN $1='FAILED' THEN NOW() ELSE failed_at END,
              external_refund_reference=COALESCE($3,external_refund_reference),
              admin_note=COALESCE($4,admin_note),
              updated_at=NOW()
          WHERE id=$5
          RETURNING *
        `,[next,actor,externalReference,note,refund.id])).rows[0];

        await client.query(`
          INSERT INTO payment_refund_events(refund_id,event_type,from_status,to_status,actor,note,metadata)
          VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)
        `,[refund.id,event,current,next,actor,note,JSON.stringify({externalRefundReference:externalReference})]);

        if(next==='PROCESSED'){
          const processed=(await client.query(`
            SELECT COALESCE(SUM(amount),0)::numeric AS total
            FROM payment_refunds
            WHERE transaction_id=$1 AND status='PROCESSED'
          `,[refund.transaction_id])).rows[0];

          const fullyRefunded=Number(processed.total||0) >= Number(refund.payment_amount||0)-0.0001;
          if(fullyRefunded){
            await client.query(`
              UPDATE payment_transactions
              SET status='REFUNDED',refunded_at=COALESCE(refunded_at,NOW()),updated_at=NOW()
              WHERE id=$1
            `,[refund.transaction_id]);

            if(refund.order_id){
              await client.query(`
                UPDATE orders SET payment_status='REFUNDED',updated_at=NOW() WHERE id=$1
              `,[refund.order_id]);
            }

            await client.query(`
              INSERT INTO payment_transaction_events(
                transaction_id,event_type,from_status,to_status,actor,note,metadata
              ) VALUES($1,'FULL_REFUND_RECORDED',$2,'REFUNDED',$3,$4,$5::jsonb)
            `,[
              refund.transaction_id,
              refund.payment_status,
              actor,
              'Processed refunds now equal the full payment amount',
              JSON.stringify({refundId:refund.id,externalReference})
            ]);
          }
        }

        if(refund.order_id){
          if(['FAILED','REJECTED'].includes(next))await recoverCancellationRefundV152Z(client,updated,actor);
          if(['FAILED','REJECTED'].includes(next))await syncReturnRefundExceptionV152V(client,updated);
          if(next==='PROCESSED')await syncReturnRefundProcessedV152U(client,updated);
          if(next==='PROCESSED')await syncCouponLifecycleForRefundV153L(client,updated,actor);
          if(next==='PROCESSED')await allocateCampaignRefundV152S(client,updated);
          if(next==='PROCESSED')await autoCreditNoteForProcessedRefundV153R(client,updated);
          await reconcileVibePaymentConversionPipelineV152E(client,refund.order_id,'REFUND_STATUS_UPDATED');
          if(next==='PROCESSED'){
            const linked=(await client.query(`SELECT cancellation_refund_id FROM orders WHERE id=$1`,[refund.order_id])).rows[0];
            if(String(linked?.cancellation_refund_id||'')===String(refund.id)){
              await finalizePaidOrderCancellationV152R(client,refund.order_id,refund.id,actor);
            }
          }
        }
        await client.query('COMMIT');
        if(next==='PROCESSED'){
          try{ await syncPaymentHpayIntegrityCases(); }
          catch(integrityError){ console.warn("⚠️ Payment ↔ HPay integrity sync deferred:",integrityError.message); }
        }
        return updated;
      }catch(error){
        await client.query('ROLLBACK');
        throw error;
      }finally{
        client.release();
      }
    }


    async function syncPaymentHpayIntegrityCases(){
      // Create cases only for actually PROCESSED refunds that already have Vendor settlement exposure.
      // No settlement, payout, ledger or historical period is mutated here.
      const result=await pool.query(`
        INSERT INTO payment_hpay_integrity_cases(
          case_code,payment_transaction_id,refund_id,order_id,vendor_settlement_id,
          case_type,severity,status,exposure_amount,currency
        )
        SELECT
          'PHI-'||r.id||'-'||vs.id,
          r.transaction_id,
          r.id,
          r.order_id,
          vs.id,
          CASE WHEN vs.status='PAID' THEN 'REFUND_AFTER_VENDOR_PAYOUT' ELSE 'REFUND_AFTER_VENDOR_SETTLEMENT' END,
          CASE WHEN vs.status='PAID' THEN 'CRITICAL' ELSE 'HIGH' END,
          'OPEN',
          LEAST(COALESCE(r.amount,0),COALESCE(vs.net_payable_amount,0)),
          COALESCE(r.currency,'INR')
        FROM payment_refunds r
        JOIN vendor_settlements vs ON vs.order_id=r.order_id
        WHERE r.status='PROCESSED'
          AND NOT EXISTS(
            SELECT 1
            FROM payment_hpay_integrity_cases c
            WHERE c.refund_id=r.id
              AND c.vendor_settlement_id=vs.id
              AND c.case_type=CASE WHEN vs.status='PAID' THEN 'REFUND_AFTER_VENDOR_PAYOUT' ELSE 'REFUND_AFTER_VENDOR_SETTLEMENT' END
          )
        ON CONFLICT(refund_id,vendor_settlement_id,case_type) DO NOTHING
        RETURNING id
      `);

      if(result.rows.length){
        await pool.query(`
          INSERT INTO payment_hpay_integrity_events(case_id,event_type,to_status,actor,note,metadata)
          SELECT id,'CASE_OPENED','OPEN','SYSTEM',
                 'Processed customer refund detected against an existing Vendor settlement/payout. Manual finance review required.',
                 jsonb_build_object('automatic',true)
          FROM payment_hpay_integrity_cases
          WHERE id=ANY($1::bigint[])
        `,[result.rows.map(r=>Number(r.id))]);
      }
      return result.rowCount||0;
    }

    async function getPaymentHpayIntegrityDashboard(){
      await syncPaymentHpayIntegrityCases();

      const cases=(await pool.query(`
        SELECT
          c.*,
          p.transaction_code,
          p.amount AS payment_amount,
          r.refund_code,
          r.amount AS refund_amount,
          r.external_refund_reference,
          o.order_number,
          vs.settlement_number,
          vs.status AS settlement_status,
          vs.net_payable_amount,
          vp.vendor_code,
          vp.business_name,
          ha.hpay_account_id,
          COALESCE(
            (
              SELECT jsonb_agg(jsonb_build_object(
                'id',e.id,'event_type',e.event_type,'from_status',e.from_status,
                'to_status',e.to_status,'actor',e.actor,'note',e.note,'created_at',e.created_at
              ) ORDER BY e.created_at DESC)
              FROM payment_hpay_integrity_events e WHERE e.case_id=c.id
            ),
            '[]'::jsonb
          ) AS events
        FROM payment_hpay_integrity_cases c
        JOIN payment_transactions p ON p.id=c.payment_transaction_id
        LEFT JOIN payment_refunds r ON r.id=c.refund_id
        LEFT JOIN orders o ON o.id=c.order_id
        LEFT JOIN vendor_settlements vs ON vs.id=c.vendor_settlement_id
        LEFT JOIN vendor_profiles vp ON vp.id=vs.vendor_profile_id
        LEFT JOIN hpay_universal_accounts ha
          ON ha.owner_type='VENDOR' AND ha.owner_reference=vs.vendor_profile_id::text
        ORDER BY
          CASE c.severity WHEN 'CRITICAL' THEN 1 WHEN 'HIGH' THEN 2 ELSE 3 END,
          c.created_at DESC
        LIMIT 500
      `)).rows;

      const summary=(await pool.query(`
        SELECT
          COUNT(*)::int AS total_cases,
          COUNT(*) FILTER(WHERE status='OPEN')::int AS open_cases,
          COUNT(*) FILTER(WHERE status='IN_REVIEW')::int AS review_cases,
          COUNT(*) FILTER(WHERE status='RESOLVED')::int AS resolved_cases,
          COUNT(*) FILTER(WHERE status<>'RESOLVED' AND severity='CRITICAL')::int AS critical_open,
          COALESCE(SUM(exposure_amount) FILTER(WHERE status<>'RESOLVED'),0)::numeric AS open_exposure
        FROM payment_hpay_integrity_cases
      `)).rows[0];

      return {summary,cases};
    }

    async function updatePaymentHpayIntegrityCase(caseId,action,body={}){
      const actor=clean(body.actor)||'ADMIN';
      const note=clean(body.note)||null;
      const resolutionAction=clean(body.resolution_action)||null;
      const assignedTo=clean(body.assigned_to)||null;
      const client=await pool.connect();

      try{
        await client.query('BEGIN');
        const current=(await client.query(`
          SELECT * FROM payment_hpay_integrity_cases WHERE id=$1 FOR UPDATE
        `,[Number(caseId)])).rows[0];
        if(!current)throw new Error("Finance integrity case not found");

        let next=current.status;
        let event='CASE_UPDATED';

        if(action==='review'){
          if(current.status==='RESOLVED')throw new Error("Resolved case must be reopened first");
          next='IN_REVIEW'; event='CASE_IN_REVIEW';
        }else if(action==='assign'){
          if(!assignedTo)throw new Error("Assignee is required");
          event='CASE_ASSIGNED';
        }else if(action==='resolve'){
          if(!note)throw new Error("Resolution note is required");
          if(!resolutionAction)throw new Error("Resolution action is required");
          next='RESOLVED'; event='CASE_RESOLVED';
        }else if(action==='reopen'){
          if(current.status!=='RESOLVED')throw new Error("Only resolved cases can be reopened");
          next='OPEN'; event='CASE_REOPENED';
        }else{
          throw new Error("Unsupported integrity action");
        }

        const updated=(await client.query(`
          UPDATE payment_hpay_integrity_cases
          SET status=$1,
              assigned_to=COALESCE($2,assigned_to),
              resolution_action=CASE WHEN $1='RESOLVED' THEN $3 ELSE resolution_action END,
              resolution_note=CASE WHEN $1='RESOLVED' THEN $4 ELSE resolution_note END,
              resolved_at=CASE WHEN $1='RESOLVED' THEN NOW() WHEN $1<>'RESOLVED' THEN NULL ELSE resolved_at END,
              updated_at=NOW()
          WHERE id=$5
          RETURNING *
        `,[next,assignedTo,resolutionAction,note,current.id])).rows[0];

        await client.query(`
          INSERT INTO payment_hpay_integrity_events(
            case_id,event_type,from_status,to_status,actor,note,metadata
          ) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)
        `,[current.id,event,current.status,next,actor,note,
           JSON.stringify({resolutionAction,assignedTo})]);

        await client.query('COMMIT');
        return updated;
      }catch(error){
        await client.query('ROLLBACK');
        throw error;
      }finally{
        client.release();
      }
    }

    async function getPaymentHpayTrace(orderId){
      const orderRef=clean(orderId);
      if(!orderRef)throw new Error("Order reference is required");

      const vendorSettlements=(await pool.query(`
        SELECT
          vs.*,
          vp.vendor_code,
          vp.business_name,
          vp.owner_name,
          ha.id AS hpay_account_db_id,
          ha.hpay_account_id,
          ha.howdi_id AS hpay_howdi_id,
          ha.status AS hpay_account_status
        FROM vendor_settlements vs
        LEFT JOIN vendor_profiles vp ON vp.id=vs.vendor_profile_id
        LEFT JOIN hpay_universal_accounts ha
          ON ha.owner_type='VENDOR'
          AND ha.owner_reference=vs.vendor_profile_id::text
        WHERE vs.order_id=$1
        ORDER BY vs.created_at DESC,vs.id DESC
      `,[orderRef])).rows;

      const settlementIds=vendorSettlements.map(x=>Number(x.id)).filter(Boolean);

      let payoutItems=[];
      if(settlementIds.length){
        payoutItems=(await pool.query(`
          SELECT
            bi.id AS payout_item_id,
            bi.settlement_id,
            bi.amount,
            b.id AS payout_batch_id,
            b.batch_number,
            b.status AS payout_batch_status,
            b.payout_reference,
            b.approved_at,
            b.paid_at,
            b.created_at
          FROM vendor_payout_batch_items bi
          JOIN vendor_payout_batches b ON b.id=bi.batch_id
          WHERE bi.settlement_id=ANY($1::bigint[])
          ORDER BY b.created_at DESC,b.id DESC
        `,[settlementIds])).rows;
      }

      const shipmentRows=(await pool.query(`
        SELECT
          id,
          order_id,
          vendor_profile_id,
          provider_key,
          status,
          tracking_number,
          awb_code,
          shipment_number,
          created_at,
          updated_at
        FROM order_shipments
        WHERE order_id=$1
        ORDER BY created_at DESC
        LIMIT 50
      `,[orderRef])).rows;

      const gross=vendorSettlements.reduce((n,r)=>n+Number(r.gross_amount||0),0);
      const commission=vendorSettlements.reduce((n,r)=>n+Number(r.commission_amount||0),0);
      const gatewayFee=vendorSettlements.reduce((n,r)=>n+Number(r.gateway_fee_amount||0),0);
      const delivery=vendorSettlements.reduce((n,r)=>n+Number(r.delivery_deduction_amount||0),0);
      const withholding=vendorSettlements.reduce((n,r)=>n+Number(r.tax_withholding_amount||0),0);
      const adjustments=vendorSettlements.reduce((n,r)=>n+Number(r.adjustment_amount||0),0);
      const net=vendorSettlements.reduce((n,r)=>n+Number(r.net_payable_amount||0),0);
      const paid=vendorSettlements
        .filter(r=>r.status==='PAID')
        .reduce((n,r)=>n+Number(r.net_payable_amount||0),0);

      return {
        orderId:orderRef,
        vendorSettlements,
        payoutItems,
        shipments:shipmentRows,
        totals:{
          gross,
          commission,
          gatewayFee,
          delivery,
          withholding,
          adjustments,
          net,
          paid,
          outstanding:net-paid
        },
        traceStatus:vendorSettlements.length
          ? (vendorSettlements.some(r=>r.status==='PAID') ? 'PAYOUT_RECORDED' : 'HPAY_CONTROL_ACTIVE')
          : 'NO_SETTLEMENT_YET'
      };
    }

    async function getHpayParticipants(searchText=''){
      const search=clean(searchText);
      const params=[];
      let filter='';
      if(search){
        params.push(`%${search}%`);
        filter=`
          WHERE (
            ha.hpay_account_id ILIKE $1
            OR COALESCE(ha.howdi_id,'') ILIKE $1
            OR COALESCE(ha.display_name,'') ILIKE $1
            OR ha.owner_type ILIKE $1
            OR ha.owner_reference ILIKE $1
          )
        `;
      }

      const rows=(await pool.query(`
        SELECT
          ha.id,
          ha.hpay_account_id,
          ha.owner_type,
          ha.owner_reference,
          ha.howdi_id,
          ha.display_name,
          ha.currency,
          ha.status,
          ha.created_at,
          COALESCE(
            jsonb_agg(
              DISTINCT jsonb_build_object(
                'program_key',hp.program_key,
                'program_name',hp.program_name,
                'membership_status',ap.status,
                'participant_type',ap.participant_type
              )
            ) FILTER(WHERE hp.id IS NOT NULL),
            '[]'::jsonb
          ) AS programs
        FROM hpay_universal_accounts ha
        LEFT JOIN hpay_universal_account_programs ap
          ON ap.hpay_account_id=ha.id
        LEFT JOIN hpay_programs hp
          ON hp.id=ap.program_id
        ${filter}
        GROUP BY ha.id
        ORDER BY ha.updated_at DESC,ha.id DESC
        LIMIT 200
      `,params)).rows;

      const summary=(await pool.query(`
        SELECT
          COUNT(*)::int AS total,
          COUNT(*) FILTER(WHERE owner_type='VENDOR')::int AS vendors,
          COUNT(*) FILTER(WHERE owner_type='WORKER')::int AS workers,
          COUNT(*) FILTER(WHERE owner_type='LEARNER')::int AS learners,
          COUNT(*) FILTER(WHERE status='ACTIVE')::int AS active
        FROM hpay_universal_accounts
      `)).rows[0];

      return {rows,summary};
    }

    async function getHpayParticipant360(accountId){
      const account=(await pool.query(`
        SELECT *
        FROM hpay_universal_accounts
        WHERE id=$1
        LIMIT 1
      `,[Number(accountId)])).rows[0];
      if(!account)throw new Error("HPay participant not found");

      const memberships=(await pool.query(`
        SELECT
          ap.*,hp.program_key,hp.program_name,hp.program_type,
          hp.is_enabled,hp.is_operational
        FROM hpay_universal_account_programs ap
        JOIN hpay_programs hp ON hp.id=ap.program_id
        WHERE ap.hpay_account_id=$1
        ORDER BY hp.program_name
      `,[account.id])).rows;

      const agreements=(await pool.query(`
        SELECT
          a.*,hp.program_key,hp.program_name
        FROM hpay_universal_agreements a
        JOIN hpay_programs hp ON hp.id=a.program_id
        WHERE a.hpay_account_id=$1
        ORDER BY a.created_at DESC,a.version DESC
        LIMIT 100
      `,[account.id])).rows;

      const earnings=(await pool.query(`
        SELECT
          e.*,hp.program_key,hp.program_name
        FROM hpay_universal_earnings e
        JOIN hpay_programs hp ON hp.id=e.program_id
        WHERE e.hpay_account_id=$1
        ORDER BY e.occurred_at DESC,e.id DESC
        LIMIT 200
      `,[account.id])).rows;

      const settlements=(await pool.query(`
        SELECT
          s.*,hp.program_key,hp.program_name,
          pbi.batch_id,
          pb.batch_number,
          pb.status AS payout_batch_status,
          pb.payment_reference
        FROM hpay_universal_settlements s
        JOIN hpay_programs hp ON hp.id=s.program_id
        LEFT JOIN hpay_universal_payout_batch_items pbi ON pbi.settlement_id=s.id
        LEFT JOIN hpay_universal_payout_batches pb ON pb.id=pbi.batch_id
        WHERE s.hpay_account_id=$1
        ORDER BY s.created_at DESC,s.id DESC
        LIMIT 150
      `,[account.id])).rows;

      const ledger=(await pool.query(`
        SELECT
          l.*,hp.program_key,hp.program_name
        FROM hpay_universal_ledger_entries l
        JOIN hpay_programs hp ON hp.id=l.program_id
        WHERE l.hpay_account_id=$1
        ORDER BY l.created_at DESC,l.id DESC
        LIMIT 250
      `,[account.id])).rows;

      let vendorSettlements=[];
      let vendorPayouts=[];
      if(account.owner_type==='VENDOR'){
        const vendorId=Number(account.owner_reference);
        if(Number.isFinite(vendorId)&&vendorId>0){
          vendorSettlements=(await pool.query(`
            SELECT *
            FROM vendor_settlements
            WHERE vendor_profile_id=$1
            ORDER BY created_at DESC,id DESC
            LIMIT 200
          `,[vendorId])).rows;

          vendorPayouts=(await pool.query(`
            SELECT
              b.id,b.batch_number,b.status,b.total_amount,b.approved_at,b.paid_at,
              b.payment_reference,b.created_at,
              bi.amount,
              bi.settlement_id
            FROM vendor_payout_batch_items bi
            JOIN vendor_payout_batches b ON b.id=bi.batch_id
            WHERE bi.vendor_profile_id=$1
            ORDER BY b.created_at DESC,b.id DESC
            LIMIT 150
          `,[vendorId])).rows;
        }
      }

      const universalTotals=(await pool.query(`
        SELECT
          COALESCE(SUM(gross_amount),0)::numeric AS gross,
          COALESCE(SUM(howdi_fee_amount),0)::numeric AS howdi_fee,
          COALESCE(SUM(incentive_amount),0)::numeric AS incentive,
          COALESCE(SUM(other_deduction_amount),0)::numeric AS deductions,
          COALESCE(SUM(net_payable_amount),0)::numeric AS net,
          COALESCE(SUM(net_payable_amount) FILTER(WHERE status='PAID'),0)::numeric AS paid,
          COALESCE(SUM(net_payable_amount) FILTER(WHERE status<>'PAID'),0)::numeric AS outstanding
        FROM hpay_universal_settlements
        WHERE hpay_account_id=$1
      `,[account.id])).rows[0];

      let vendorTotals={gross:0,howdi_fee:0,deductions:0,net:0,paid:0,outstanding:0};
      if(account.owner_type==='VENDOR'){
        const vendorId=Number(account.owner_reference);
        if(Number.isFinite(vendorId)&&vendorId>0){
          const row=(await pool.query(`
            SELECT
              COALESCE(SUM(gross_amount),0)::numeric AS gross,
              COALESCE(SUM(commission_amount),0)::numeric AS howdi_fee,
              COALESCE(SUM(gateway_fee_amount+delivery_deduction_amount+tax_withholding_amount-adjustment_amount),0)::numeric AS deductions,
              COALESCE(SUM(net_payable_amount),0)::numeric AS net,
              COALESCE(SUM(net_payable_amount) FILTER(WHERE status='PAID'),0)::numeric AS paid,
              COALESCE(SUM(net_payable_amount) FILTER(WHERE status<>'PAID'),0)::numeric AS outstanding
            FROM vendor_settlements
            WHERE vendor_profile_id=$1
          `,[vendorId])).rows[0];
          vendorTotals={
            gross:Number(row.gross||0),
            howdi_fee:Number(row.howdi_fee||0),
            deductions:Number(row.deductions||0),
            net:Number(row.net||0),
            paid:Number(row.paid||0),
            outstanding:Number(row.outstanding||0)
          };
        }
      }

      const totals={
        gross:Number(universalTotals.gross||0)+vendorTotals.gross,
        howdi_fee:Number(universalTotals.howdi_fee||0)+vendorTotals.howdi_fee,
        incentive:Number(universalTotals.incentive||0),
        deductions:Number(universalTotals.deductions||0)+vendorTotals.deductions,
        net:Number(universalTotals.net||0)+vendorTotals.net,
        paid:Number(universalTotals.paid||0)+vendorTotals.paid,
        outstanding:Number(universalTotals.outstanding||0)+vendorTotals.outstanding
      };

      return {
        account,
        memberships,
        agreements,
        earnings,
        settlements,
        ledger,
        vendorSettlements,
        vendorPayouts,
        totals
      };
    }

    async function getFinanceStatementPack(closeId=null){
      let close=null;

      if(closeId){
        close=(await pool.query(`
          SELECT
            fc.*,
            rr.run_number AS reconciliation_run_number,
            rr.status AS reconciliation_status,
            rr.summary AS reconciliation_summary
          FROM hpay_finance_closes fc
          LEFT JOIN hpay_reconciliation_runs rr ON rr.id=fc.reconciliation_run_id
          WHERE fc.id=$1
          LIMIT 1
        `,[Number(closeId)])).rows[0]||null;
      }else{
        close=(await pool.query(`
          SELECT
            fc.*,
            rr.run_number AS reconciliation_run_number,
            rr.status AS reconciliation_status,
            rr.summary AS reconciliation_summary
          FROM hpay_finance_closes fc
          LEFT JOIN hpay_reconciliation_runs rr ON rr.id=fc.reconciliation_run_id
          ORDER BY
            CASE fc.status WHEN 'CLOSED' THEN 1 WHEN 'APPROVED' THEN 2 WHEN 'REVIEWED' THEN 3 WHEN 'PREPARED' THEN 4 ELSE 5 END,
            fc.period_end DESC,
            fc.id DESC
          LIMIT 1
        `)).rows[0]||null;
      }

      const periods=(await pool.query(`
        SELECT
          id,close_number,period_start,period_end,status,total_finance_value,
          vendor_total,worker_total,learn_earn_total,closed_at,created_at
        FROM hpay_finance_closes
        ORDER BY period_end DESC,id DESC
        LIMIT 60
      `)).rows;

      if(!close){
        return {
          close:null,
          periods,
          programSummary:[],
          settlementSummary:[],
          payoutSummary:[],
          adjustmentsPosted:[],
          adjustmentsReferencing:[],
          closeEvents:[],
          reconciliationIssues:[],
          statementRows:[],
          controls:{
            periodLocked:false,
            reconciliationComplete:false,
            signoffComplete:false
          }
        };
      }

      const start=close.period_start;
      const end=close.period_end;

      const vendorSettlement=(await pool.query(`
        SELECT
          COUNT(*)::int AS settlement_count,
          COALESCE(SUM(gross_amount),0)::numeric AS gross_amount,
          COALESCE(SUM(commission_amount),0)::numeric AS howdi_fee_amount,
          COALESCE(SUM(gateway_fee_amount),0)::numeric AS gateway_fee_amount,
          COALESCE(SUM(delivery_deduction_amount),0)::numeric AS delivery_deduction_amount,
          COALESCE(SUM(tax_withholding_amount),0)::numeric AS tax_withholding_amount,
          COALESCE(SUM(adjustment_amount),0)::numeric AS settlement_adjustment_amount,
          COALESCE(SUM(net_payable_amount),0)::numeric AS net_payable_amount,
          COALESCE(SUM(net_payable_amount) FILTER(WHERE status='PAID'),0)::numeric AS paid_amount,
          COALESCE(SUM(net_payable_amount) FILTER(WHERE status<>'PAID'),0)::numeric AS unpaid_amount
        FROM vendor_settlements
        WHERE created_at::date BETWEEN $1::date AND $2::date
      `,[start,end])).rows[0];

      const universalSettlements=(await pool.query(`
        SELECT
          hp.program_key,hp.program_name,
          COUNT(s.id)::int AS settlement_count,
          COALESCE(SUM(s.gross_amount),0)::numeric AS gross_amount,
          COALESCE(SUM(s.howdi_fee_amount),0)::numeric AS howdi_fee_amount,
          COALESCE(SUM(s.incentive_amount),0)::numeric AS incentive_amount,
          COALESCE(SUM(s.other_deduction_amount),0)::numeric AS deduction_amount,
          COALESCE(SUM(s.net_payable_amount),0)::numeric AS net_payable_amount,
          COALESCE(SUM(s.net_payable_amount) FILTER(WHERE s.status='PAID'),0)::numeric AS paid_amount,
          COALESCE(SUM(s.net_payable_amount) FILTER(WHERE s.status<>'PAID'),0)::numeric AS unpaid_amount
        FROM hpay_universal_settlements s
        JOIN hpay_programs hp ON hp.id=s.program_id
        WHERE s.created_at::date BETWEEN $1::date AND $2::date
          AND hp.program_key IN ('worker_services','learn_earn')
        GROUP BY hp.program_key,hp.program_name
        ORDER BY hp.program_name
      `,[start,end])).rows;

      const universalPayouts=(await pool.query(`
        SELECT
          hp.program_key,hp.program_name,
          COUNT(b.id)::int AS batch_count,
          COALESCE(SUM(b.total_amount),0)::numeric AS batch_amount,
          COALESCE(SUM(b.total_amount) FILTER(WHERE b.status='PAID'),0)::numeric AS paid_amount,
          COALESCE(SUM(b.total_amount) FILTER(WHERE b.status<>'PAID'),0)::numeric AS pending_amount
        FROM hpay_universal_payout_batches b
        JOIN hpay_programs hp ON hp.id=b.program_id
        WHERE b.created_at::date BETWEEN $1::date AND $2::date
          AND hp.program_key IN ('worker_services','learn_earn')
        GROUP BY hp.program_key,hp.program_name
        ORDER BY hp.program_name
      `,[start,end])).rows;

      const adjustmentsPosted=(await pool.query(`
        SELECT
          id,adjustment_number,program_key,adjustment_type,amount,reason,
          source_reference,status,posted_at,posting_period_start,posting_period_end
        FROM hpay_finance_adjustments
        WHERE status='POSTED'
          AND posted_at::date BETWEEN $1::date AND $2::date
        ORDER BY posted_at,id
      `,[start,end])).rows;

      const adjustmentsReferencing=(await pool.query(`
        SELECT
          id,adjustment_number,program_key,adjustment_type,amount,reason,
          source_reference,status,posted_at,posting_period_start,posting_period_end
        FROM hpay_finance_adjustments
        WHERE original_close_id=$1
        ORDER BY created_at,id
      `,[close.id])).rows;

      const closeEvents=(await pool.query(`
        SELECT id,event_type,from_status,to_status,actor,note,created_at
        FROM hpay_finance_close_events
        WHERE close_id=$1
        ORDER BY created_at,id
      `,[close.id])).rows;

      const reconciliationIssues=close.reconciliation_run_id?(await pool.query(`
        SELECT
          id,program_key,issue_type,severity,entity_type,entity_reference,
          expected_amount,actual_amount,status,assigned_to,resolution_note,created_at,updated_at
        FROM hpay_reconciliation_issues
        WHERE run_id=$1
        ORDER BY
          CASE severity WHEN 'CRITICAL' THEN 1 WHEN 'WARNING' THEN 2 ELSE 3 END,
          id
      `,[close.reconciliation_run_id])).rows:[];

      const postedAdjustmentTotals=(await pool.query(`
        SELECT program_key,COALESCE(SUM(amount),0)::numeric AS amount
        FROM hpay_finance_adjustments
        WHERE status='POSTED'
          AND posted_at::date BETWEEN $1::date AND $2::date
        GROUP BY program_key
      `,[start,end])).rows;

      const adj=(key)=>Number(postedAdjustmentTotals.find(r=>r.program_key===key)?.amount||0);
      const worker=universalSettlements.find(r=>r.program_key==='worker_services')||{};
      const learn=universalSettlements.find(r=>r.program_key==='learn_earn')||{};

      const programSummary=[
        {
          program_key:'vendor_commerce',
          program_name:'Vendor Commerce',
          gross:Number(vendorSettlement.gross_amount||0),
          howdi_fee:Number(vendorSettlement.howdi_fee_amount||0),
          other_deductions:
            Number(vendorSettlement.gateway_fee_amount||0)+
            Number(vendorSettlement.delivery_deduction_amount||0)+
            Number(vendorSettlement.tax_withholding_amount||0),
          settlement_adjustment:Number(vendorSettlement.settlement_adjustment_amount||0),
          posted_adjustment:adj('vendor_commerce'),
          net:Number(vendorSettlement.net_payable_amount||0)+adj('vendor_commerce'),
          paid:Number(vendorSettlement.paid_amount||0),
          unpaid:Number(vendorSettlement.unpaid_amount||0)
        },
        {
          program_key:'worker_services',
          program_name:'Worker Services',
          gross:Number(worker.gross_amount||0),
          howdi_fee:Number(worker.howdi_fee_amount||0),
          other_deductions:Number(worker.deduction_amount||0)-Number(worker.incentive_amount||0),
          settlement_adjustment:0,
          posted_adjustment:adj('worker_services'),
          net:Number(worker.net_payable_amount||0)+adj('worker_services'),
          paid:Number(worker.paid_amount||0),
          unpaid:Number(worker.unpaid_amount||0)
        },
        {
          program_key:'learn_earn',
          program_name:'Learn & Earn',
          gross:Number(learn.gross_amount||0),
          howdi_fee:Number(learn.howdi_fee_amount||0),
          other_deductions:Number(learn.deduction_amount||0)-Number(learn.incentive_amount||0),
          settlement_adjustment:0,
          posted_adjustment:adj('learn_earn'),
          net:Number(learn.net_payable_amount||0)+adj('learn_earn'),
          paid:Number(learn.paid_amount||0),
          unpaid:Number(learn.unpaid_amount||0)
        }
      ];

      const statementRows=[
        ...programSummary.map(p=>({
          category:'PROGRAM_TOTAL',
          reference:p.program_name,
          program_key:p.program_key,
          gross:p.gross,
          howdi_fee:p.howdi_fee,
          deductions:p.other_deductions,
          adjustments:p.posted_adjustment+p.settlement_adjustment,
          net:p.net,
          status:close.status
        })),
        ...adjustmentsPosted.map(a=>({
          category:'POSTED_ADJUSTMENT',
          reference:a.adjustment_number,
          program_key:a.program_key,
          gross:0,
          howdi_fee:0,
          deductions:0,
          adjustments:Number(a.amount||0),
          net:Number(a.amount||0),
          status:a.status
        }))
      ];

      return {
        close,
        periods,
        programSummary,
        settlementSummary:[
          {program_key:'vendor_commerce',program_name:'Vendor Commerce',...vendorSettlement},
          ...universalSettlements
        ],
        payoutSummary:universalPayouts,
        adjustmentsPosted,
        adjustmentsReferencing,
        closeEvents,
        reconciliationIssues,
        statementRows,
        controls:{
          periodLocked:close.status==='CLOSED',
          reconciliationComplete:['COMPLETED','ATTENTION'].includes(String(close.reconciliation_status||'')),
          signoffComplete:close.status==='CLOSED',
          criticalIssueCount:Number(close.critical_issue_count||0),
          warningIssueCount:Number(close.warning_issue_count||0)
        }
      };
    }

    async function isDateInClosedFinancePeriod(dateValue){
      if(!dateValue)return null;
      const row=(await pool.query(`
        SELECT id,close_number,period_start,period_end,status
        FROM hpay_finance_closes
        WHERE status='CLOSED'
          AND $1::date BETWEEN period_start AND period_end
        ORDER BY period_end DESC,id DESC
        LIMIT 1
      `,[dateValue])).rows[0];
      return row||null;
    }




    async function getTeacherStatementClosureChecklist(caseId){
      const item=(await pool.query(`
        SELECT c.*,
          EXISTS(SELECT 1 FROM learning_teacher_statement_case_events e WHERE e.case_id=c.id) AS has_timeline
        FROM learning_teacher_statement_cases c WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!item)return null;
      const checks={
        status_resolved:['RESOLVED','CLOSED'].includes(item.status),
        resolution_present:!!clean(item.resolution),
        category_present:!!clean(item.category),
        root_cause_present:!!clean(item.root_cause),
        owner_present:!!clean(item.assigned_to),
        timeline_present:item.has_timeline===true
      };
      return {item,checks,ready:Object.values(checks).every(Boolean)};
    }







    async function scoreTeacherCaseExperience(caseId){
      const row=(await pool.query(`
        SELECT c.*,
          (SELECT rating FROM learning_teacher_statement_case_feedback f WHERE f.case_id=c.id LIMIT 1) AS feedback_rating,
          (SELECT COUNT(*)::int FROM learning_teacher_statement_case_reopen_requests r WHERE r.case_id=c.id AND r.status='APPROVED') AS reopen_count,
          (SELECT COUNT(*)::int FROM learning_teacher_statement_case_messages m WHERE m.case_id=c.id AND m.is_internal=FALSE) AS visible_messages
        FROM learning_teacher_statement_cases c WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!row)return null;
      let score=70;
      if(row.teacher_resolution_confirmation==='ACCEPTED')score+=15;
      if(row.teacher_resolution_confirmation==='NOT_ACCEPTED')score-=25;
      const rating=Number(row.feedback_rating||0);
      if(rating>=4)score+=10; else if(rating>0&&rating<=2)score-=15;
      if(Number(row.reopen_count||0)>0)score-=15;
      if(row.due_at && row.resolved_at && new Date(row.resolved_at)>new Date(row.due_at))score-=10;
      if(Number(row.visible_messages||0)>=3)score+=5;
      score=Math.max(0,Math.min(100,score));
      const level=score>=85?'EXCELLENT':score>=70?'GOOD':score>=50?'FAIR':'POOR';
      await pool.query(`UPDATE learning_teacher_statement_cases SET experience_score=$2,experience_level=$3,experience_scored_at=NOW() WHERE id=$1`,[caseId,score,level]);
      return {case_id:caseId,score,level};
    }

    async function scanTeacherRepeatCases(){
      const rows=(await pool.query(`SELECT id,teacher_profile_id,statement_month,category,root_cause_code,created_at FROM learning_teacher_statement_cases ORDER BY teacher_profile_id,created_at`)).rows;
      const updates=[];
      for(const c of rows){
        const prev=(await pool.query(`
          SELECT id,category,root_cause_code,created_at FROM learning_teacher_statement_cases
          WHERE teacher_profile_id=$1 AND id<>$2 AND created_at<$3
          ORDER BY created_at DESC LIMIT 20
        `,[c.teacher_profile_id,c.id,c.created_at])).rows;
        let best=null,bestScore=0;
        for(const p of prev){
          let s=0;
          if(c.root_cause_code && p.root_cause_code===c.root_cause_code)s+=60;
          if(c.category && p.category===c.category)s+=30;
          const days=Math.abs((new Date(c.created_at)-new Date(p.created_at))/86400000);
          if(days<=90)s+=10;
          if(s>bestScore){bestScore=s;best=p;}
        }
        if(best && bestScore>=60){
          await pool.query(`UPDATE learning_teacher_statement_cases SET repeat_case_score=$2,repeat_case_reference_id=$3,repeat_case_scanned_at=NOW() WHERE id=$1`,
            [c.id,bestScore,best.id]);
          updates.push({case_id:c.id,reference_case_id:best.id,score:bestScore});
        }else{
          await pool.query(`UPDATE learning_teacher_statement_cases SET repeat_case_score=0,repeat_case_reference_id=NULL,repeat_case_scanned_at=NOW() WHERE id=$1`,[c.id]);
        }
      }
      return updates.sort((x,y)=>y.score-x.score);
    }

    async function runTeacherCaseGovernanceHealth(actor){
      const cases=(await pool.query(`SELECT * FROM learning_teacher_statement_cases`)).rows;
      const issues=[];
      for(const c of cases){
        if(['RESOLVED','CLOSED'].includes(c.status) && !c.resolution)issues.push({case_id:c.id,type:'RESOLUTION_MISSING'});
        if(c.status==='CLOSED' && !c.closure_verified_at)issues.push({case_id:c.id,type:'CLOSURE_NOT_VERIFIED'});
        if(c.finance_adjustment_id && c.closure_approval_status!=='APPROVED' && c.status==='CLOSED')issues.push({case_id:c.id,type:'FINANCE_CASE_CLOSED_WITHOUT_APPROVAL'});
        if(c.teacher_resolution_confirmation==='NOT_ACCEPTED' && c.status==='CLOSED')issues.push({case_id:c.id,type:'CLOSED_AFTER_NOT_ACCEPTED'});
        if(c.archive_status==='ARCHIVED' && c.status!=='CLOSED')issues.push({case_id:c.id,type:'NON_CLOSED_CASE_ARCHIVED'});
      }
      const total=cases.length,score=total?Math.max(0,Math.round(100-(issues.length/total)*100)):100;
      const ref=`GH-${Date.now()}`;
      const row=(await pool.query(`INSERT INTO learning_teacher_statement_governance_health(run_reference,total_cases,integrity_score,issue_count,issues,created_by) VALUES($1,$2,$3,$4,$5::jsonb,$6) RETURNING *`,
        [ref,total,score,issues.length,JSON.stringify(issues),actor])).rows[0];
      return row;
    }


    async function getTeacherTrustIndex(){
      const rows=(await pool.query(`SELECT tp.id AS teacher_profile_id,u.full_name,u.howdi_id,
        COUNT(c.id)::int AS total_cases,
        COUNT(c.id) FILTER(WHERE c.teacher_resolution_confirmation='ACCEPTED')::int AS accepted,
        COUNT(c.id) FILTER(WHERE c.teacher_resolution_confirmation='NOT_ACCEPTED')::int AS not_accepted,
        ROUND(AVG(c.experience_score)::numeric,2) AS avg_experience,
        ROUND(AVG(c.resolution_effectiveness_score)::numeric,2) AS avg_effectiveness
        FROM learning_teacher_profiles tp JOIN users u ON u.id=tp.user_id
        LEFT JOIN learning_teacher_statement_cases c ON c.teacher_profile_id=tp.id
        GROUP BY tp.id,u.full_name,u.howdi_id ORDER BY u.full_name`)).rows;
      return rows.map(x=>{let s=70+Math.min(20,Number(x.accepted||0)*2)-Math.min(30,Number(x.not_accepted||0)*5);
        if(x.avg_experience!=null)s+=(Number(x.avg_experience)-70)*.2;if(x.avg_effectiveness!=null)s+=(Number(x.avg_effectiveness)-60)*.15;
        s=Math.max(0,Math.min(100,Math.round(s)));return {...x,trust_score:s,trust_level:s>=85?'EXCELLENT':s>=70?'STRONG':s>=50?'WATCH':'RISK'};}).sort((x,y)=>y.trust_score-x.trust_score);
    }
    async function buildEarningsIntegritySummary(){
      const out={};
      try{out.teacher_earnings=(await pool.query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='SETTLED')::int settled,COUNT(*) FILTER(WHERE status='ELIGIBLE')::int eligible,COUNT(*) FILTER(WHERE status='HOLD')::int hold FROM hpay_universal_earnings`)).rows[0];}
      catch(e){out.teacher_earnings={total:0,settled:0,eligible:0,hold:0,warning:e.message};}
      try{out.settlements=(await pool.query(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status ILIKE '%FAILED%')::int failed FROM hpay_universal_settlements`)).rows[0];}
      catch(e){out.settlements={total:0,failed:0,warning:e.message};}
      return out;
    }
    async function buildLearnerOutcomeIntegrity(){
      const checks=[],tests=[
        ['enrollments','learning_enrollments'],['assessments','learning_assessment_submissions'],
        ['certificates','learning_certificates'],['skill_passports','learning_skill_passports'],['practice','learning_practice_submissions']
      ];
      for(const [key,table] of tests){try{const r=(await pool.query(`SELECT COUNT(*)::int AS count FROM ${table}`)).rows[0];checks.push({key,status:'PASS',count:r.count});}catch(e){checks.push({key,status:'WARN',detail:e.message});}}
      return checks;
    }

    async function snapshotTeacherTrust(){
      const rows=await getTeacherTrustIndex();
      for(const x of rows){
        await pool.query(`INSERT INTO learning_teacher_trust_snapshots(teacher_profile_id,trust_score,trust_level,total_cases,accepted,not_accepted)
          VALUES($1,$2,$3,$4,$5,$6)`,
          [x.teacher_profile_id,x.trust_score,x.trust_level,Number(x.total_cases||0),Number(x.accepted||0),Number(x.not_accepted||0)]);
      }
      return rows;
    }

    async function buildLearnEarnRiskHeatmap(){
      const cells=[];
      const add=(area,risk,count,detail)=>cells.push({area,risk,count:Number(count||0),detail});
      const q=async(sql)=>Number((await pool.query(sql)).rows[0]?.n||0);
      try{add('Readiness Gaps','CRITICAL',await q(`SELECT COUNT(*)::int n FROM learning_earn_readiness_gaps WHERE status IN('OPEN','IN_PROGRESS') AND severity='CRITICAL'`),'Critical readiness gaps');}catch{}
      try{add('Launch Blockers','HIGH',await q(`SELECT COUNT(*)::int n FROM learning_earn_launch_blockers WHERE status IN('OPEN','MITIGATING') AND severity IN('HIGH','CRITICAL')`),'High/critical launch blockers');}catch{}
      try{add('Teacher Cases','HIGH',await q(`SELECT COUNT(*)::int n FROM learning_teacher_statement_cases WHERE status NOT IN('RESOLVED','CLOSED') AND (priority='CRITICAL' OR risk_level='CRITICAL')`),'Critical unresolved teacher cases');}catch{}
      try{add('Settlement Exceptions','HIGH',await q(`SELECT COUNT(*)::int n FROM learning_teacher_settlement_exceptions WHERE status IN('OPEN','UNDER_REVIEW') AND severity IN('HIGH','CRITICAL')`),'Open high-impact settlement exceptions');}catch{}
      try{add('Policy Exceptions','MEDIUM',await q(`SELECT COUNT(*)::int n FROM learning_earn_policy_exceptions WHERE status='PENDING'`),'Pending policy exceptions');}catch{}
      try{add('Dual Control','MEDIUM',await q(`SELECT COUNT(*)::int n FROM learning_earn_dual_control_requests WHERE status='PENDING'`),'Pending sensitive approvals');}catch{}
      return cells;
    }


    async function buildLearnEarnFinalScorecard(){
      const latestGate=(await pool.query(`SELECT * FROM learning_earn_completion_gate_runs ORDER BY created_at DESC LIMIT 1`)).rows[0]||null;
      const latestRecap=(await pool.query(`SELECT * FROM learning_earn_recap_packs ORDER BY created_at DESC LIMIT 1`)).rows[0]||null;
      const latestFreeze=(await pool.query(`SELECT * FROM learning_earn_freeze_markers ORDER BY created_at DESC LIMIT 1`)).rows[0]||null;
      const openItems=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_final_open_items WHERE status<>'CLOSED'`)).rows[0].n;
      const gaps=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_readiness_gaps WHERE status IN('OPEN','IN_PROGRESS')`)).rows[0].n;
      const blockers=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_launch_blockers WHERE status IN('OPEN','MITIGATING')`)).rows[0].n;
      const disputes=(await pool.query(`SELECT COUNT(*)::int n FROM learning_teacher_statement_cases WHERE status NOT IN('RESOLVED','CLOSED')`)).rows[0].n;
      const trust=await getTeacherTrustIndex();
      return {
        completion_score:Number(latestGate?.completion_score||0),
        gate_status:latestGate?.gate_status||'NOT_RUN',
        recap_ready:!!latestRecap,
        frozen:!!latestFreeze,
        final_open_items:Number(openItems||0),
        readiness_gaps:Number(gaps||0),
        launch_blockers:Number(blockers||0),
        open_teacher_cases:Number(disputes||0),
        teacher_trust_avg:trust.length?Math.round(trust.reduce((s,x)=>s+x.trust_score,0)/trust.length):0
      };
    }

    async function runLearnEarnDataIntegrityCheck(){
      const checks=[];
      const safe=async(key,sql)=>{
        try{const r=(await pool.query(sql)).rows[0];checks.push({key,status:'PASS',...r});}
        catch(e){checks.push({key,status:'FAIL',detail:e.message});}
      };
      await safe('teacher_profiles',`SELECT COUNT(*)::int AS count FROM learning_teacher_profiles`);
      await safe('statement_cases',`SELECT COUNT(*)::int AS count FROM learning_teacher_statement_cases`);
      await safe('case_events',`SELECT COUNT(*)::int AS count FROM learning_teacher_statement_case_events`);
      await safe('preventive_actions',`SELECT COUNT(*)::int AS count FROM learning_teacher_statement_preventive_actions`);
      await safe('recap_packs',`SELECT COUNT(*)::int AS count FROM learning_earn_recap_packs`);
      await safe('freeze_markers',`SELECT COUNT(*)::int AS count FROM learning_earn_freeze_markers`);
      await safe('completion_gate_runs',`SELECT COUNT(*)::int AS count FROM learning_earn_completion_gate_runs`);
      return checks;
    }

