    async function ensureLearnEarnQaSeed(){
      const rows=[
        ['TEACHER_LOGIN','TEACHER','Teacher login/session works'],
        ['TEACHER_SCHEDULE','TEACHER','Teacher schedule and availability work'],
        ['TEACHER_CLASS','TEACHER','Direct/group class journey works'],
        ['LEARNER_DISCOVERY','LEARNER','Learner can discover published courses'],
        ['LEARNER_ACCESS','LEARNER','Purchase/access entitlement works'],
        ['PRACTICE_ASSESS','LEARNER','Practice, assessment and proof work'],
        ['TEACHER_EARNING','HPAY','Validated delivery creates governed earning'],
        ['SETTLEMENT','HPAY','Eligible earning can enter governed settlement'],
        ['STATEMENT','FINANCE','Teacher monthly statement loads'],
        ['DISPUTE','FINANCE','Teacher dispute and Admin workflow operate'],
        ['FINANCE_CORRECTION','FINANCE','Governed finance correction bridge works'],
        ['ROOT_CAUSE_CAPA','QUALITY','Root cause and CAPA workflow operate'],
        ['READINESS_GATE','GOVERNANCE','Readiness gate and recap pack operate'],
        ['SECURITY_SESSION','SECURITY','Admin and teacher session protections verified']
      ];
      for(const [key,area,title] of rows){
        await pool.query(`INSERT INTO learning_earn_manual_qa_checks(check_key,area,title) VALUES($1,$2,$3) ON CONFLICT(check_key) DO NOTHING`,[key,area,title]);
      }
    }

    async function decideLearnEarnProductionReadiness(actor,note){
      await ensureLearnEarnQaSeed();
      const scorecard=await buildLearnEarnFinalScorecard();
      const qa=(await pool.query(`SELECT * FROM learning_earn_manual_qa_checks ORDER BY area,title`)).rows;
      const blockers=[];
      if(scorecard.completion_score<90)blockers.push('COMPLETION_SCORE_BELOW_90');
      if(scorecard.readiness_gaps>0)blockers.push('READINESS_GAPS_OPEN');
      if(scorecard.launch_blockers>0)blockers.push('LAUNCH_BLOCKERS_OPEN');
      if(scorecard.final_open_items>0)blockers.push('FINAL_OPEN_ITEMS_REMAIN');
      if(qa.some(x=>x.status==='FAILED'))blockers.push('MANUAL_QA_FAILED');
      if(qa.some(x=>x.status==='PENDING'))blockers.push('MANUAL_QA_PENDING');
      const decision=blockers.length===0?'READY_FOR_RECAP_PATCH':'REVIEW_REQUIRED';
      const score=Math.max(0,Math.min(100,scorecard.completion_score - blockers.length*3));
      return (await pool.query(`INSERT INTO learning_earn_production_readiness(decision_reference,decision,score,blockers,note,decided_by) VALUES($1,$2,$3,$4::jsonb,NULLIF($5,''),$6) RETURNING *`,
        [`LEPR-${Date.now()}`,decision,score,JSON.stringify(blockers),note||'',actor])).rows[0];
    }

    async function buildLearnEarnRecapPack(actor){
      const latest=(await pool.query(`SELECT * FROM learning_earn_completion_gate_runs ORDER BY created_at DESC LIMIT 1`)).rows[0] || await runLearnEarnCompletionGate(actor);
      const heatmap=await buildLearnEarnRiskHeatmap();
      const trust=await getTeacherTrustIndex();
      const earnings=await buildEarningsIntegritySummary();
      const learner=await buildLearnerOutcomeIntegrity();
      const gaps=(await pool.query(`SELECT id,gap_key,title,severity,status,owner_reference,due_at FROM learning_earn_readiness_gaps WHERE status IN('OPEN','IN_PROGRESS') ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END,created_at DESC LIMIT 100`)).rows;
      const blockers=(await pool.query(`SELECT id,blocker_key,title,area,severity,status,owner_reference FROM learning_earn_launch_blockers WHERE status IN('OPEN','MITIGATING') ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END,created_at DESC LIMIT 100`)).rows;
      const executive={
        completion_score:Number(latest.completion_score||0),
        gate_status:latest.gate_status,
        teacher_count:trust.length,
        avg_teacher_trust:trust.length?Math.round(trust.reduce((s,x)=>s+x.trust_score,0)/trust.length):0,
        learner_integrity_pass:learner.filter(x=>x.status==='PASS').length,
        earnings,
        risk_heatmap:heatmap
      };
      const openItems=[...gaps.map(x=>({type:'READINESS_GAP',...x})),...blockers.map(x=>({type:'LAUNCH_BLOCKER',...x}))];
      return (await pool.query(`INSERT INTO learning_earn_recap_packs(pack_reference,completion_score,gate_status,executive_summary,open_items,created_by)
        VALUES($1,$2,$3,$4::jsonb,$5::jsonb,$6) RETURNING *`,
        [`LER-${Date.now()}`,latest.completion_score,latest.gate_status,JSON.stringify(executive),JSON.stringify(openItems),actor])).rows[0];
    }

    async function runLearnEarnCompletionGate(actor){
      const checks=[],add=(key,status,detail,value)=>checks.push({key,status,detail,value:value??null});
      try{const n=(await pool.query(`SELECT COUNT(*)::int n FROM learning_teacher_profiles WHERE application_status='APPROVED'`)).rows[0].n;add('approved_teachers',n>0?'PASS':'WARN','Approved teacher availability',n);}catch(e){add('approved_teachers','FAIL',e.message);}
      try{const n=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_readiness_gaps WHERE status IN('OPEN','IN_PROGRESS') AND severity IN('HIGH','CRITICAL')`)).rows[0].n;add('high_readiness_gaps',n===0?'PASS':'FAIL','No high/critical readiness gaps',n);}catch(e){add('high_readiness_gaps','FAIL',e.message);}
      try{const n=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_launch_blockers WHERE status IN('OPEN','MITIGATING') AND severity IN('HIGH','CRITICAL')`)).rows[0].n;add('launch_blockers',n===0?'PASS':'FAIL','No high/critical launch blockers',n);}catch(e){add('launch_blockers','FAIL',e.message);}
      try{const n=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_policy_exceptions WHERE status='PENDING'`)).rows[0].n;add('pending_policy_exceptions',n===0?'PASS':'WARN','No pending policy exceptions',n);}catch(e){add('pending_policy_exceptions','WARN',e.message);}
      try{const n=(await pool.query(`SELECT COUNT(*)::int n FROM learning_earn_dual_control_requests WHERE status='PENDING'`)).rows[0].n;add('pending_dual_control',n===0?'PASS':'WARN','No pending sensitive approvals',n);}catch(e){add('pending_dual_control','WARN',e.message);}
      const integrity=await buildEarningsIntegritySummary();add('earnings_visibility','PASS','Earnings integrity visibility',integrity.teacher_earnings.total||0);
      const learner=await buildLearnerOutcomeIntegrity();add('learner_outcomes',learner.some(x=>x.status==='PASS')?'PASS':'WARN','Learner outcome primitives',learner.filter(x=>x.status==='PASS').length);
      const pass=checks.filter(x=>x.status==='PASS').length,warn=checks.filter(x=>x.status==='WARN').length,fail=checks.filter(x=>x.status==='FAIL').length;
      const score=Math.max(0,Math.min(100,Math.round(pass/checks.length*100-fail*8-warn*2)));
      const gate=score>=90&&fail===0?'NINETY_PERCENT_COMPLETE':score>=80&&fail===0?'READY_FOR_RECAP':fail>=2?'BLOCKED':'REVIEW';
      return (await pool.query(`INSERT INTO learning_earn_completion_gate_runs(run_reference,completion_score,gate_status,checks,created_by) VALUES($1,$2,$3,$4::jsonb,$5) RETURNING *`,
        [`LEC-${Date.now()}`,score,gate,JSON.stringify(checks),actor])).rows[0];
    }

    async function buildLearnEarnReadinessAudit(actor){
      const checks=[];
      const tableChecks=[
        ['teacher_cases','learning_teacher_statement_cases'],
        ['case_events','learning_teacher_statement_case_events'],
        ['case_messages','learning_teacher_statement_case_messages'],
        ['case_feedback','learning_teacher_statement_case_feedback'],
        ['preventive_actions','learning_teacher_statement_preventive_actions'],
        ['prevention_playbooks','learning_teacher_statement_prevention_playbooks']
      ];
      for(const [name,table] of tableChecks){
        try{await pool.query(`SELECT 1 FROM ${table} LIMIT 1`);checks.push({key:name,status:'PASS'});}
        catch(e){checks.push({key:name,status:'FAIL',detail:e.message});}
      }
      try{
        const open=(await pool.query(`SELECT COUNT(*)::int AS n FROM learning_teacher_statement_cases WHERE status NOT IN('RESOLVED','CLOSED')`)).rows[0].n;
        checks.push({key:'open_case_visibility',status:'PASS',value:open});
      }catch(e){checks.push({key:'open_case_visibility',status:'FAIL'});}
      try{
        const eligible=(await pool.query(`SELECT COUNT(*)::int AS n FROM hpay_universal_earnings WHERE status='ELIGIBLE'`)).rows[0].n;
        checks.push({key:'hpay_eligible_visibility',status:'PASS',value:eligible});
      }catch(e){checks.push({key:'hpay_eligible_visibility',status:'WARN',detail:'HPay universal earnings unavailable'});}
      const pass=checks.filter(x=>x.status==='PASS').length,warn=checks.filter(x=>x.status==='WARN').length,fail=checks.filter(x=>x.status==='FAIL').length;
      const score=Math.max(0,Math.round((pass/(checks.length||1))*100 - fail*5));
      const status=fail===0 && score>=85?'READY':fail<=1?'REVIEW':'BLOCKED';
      const ref=`LEA-${Date.now()}`;
      const row=(await pool.query(`INSERT INTO learning_earn_readiness_audits(audit_reference,readiness_score,status,checks,created_by) VALUES($1,$2,$3,$4::jsonb,$5) RETURNING *`,
        [ref,score,status,JSON.stringify(checks),actor])).rows[0];
      return row;
    }


    function normalizeTeacherCaseRootCause(value){
      return String(value||'').trim().toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,80);
    }
    async function buildTeacherCaseRootCauseIntelligence(){
      return (await pool.query(`SELECT COALESCE(NULLIF(root_cause_code,''),'UNCLASSIFIED') AS root_cause_code,
        COALESCE(NULLIF(root_cause,''),'Unclassified') AS root_cause, COUNT(*)::int AS total_cases,
        COUNT(*) FILTER(WHERE status NOT IN('RESOLVED','CLOSED'))::int AS active_cases,
        COUNT(*) FILTER(WHERE teacher_resolution_confirmation='NOT_ACCEPTED')::int AS not_accepted,
        ROUND(AVG(resolution_effectiveness_score)::numeric,2) AS avg_effectiveness
        FROM learning_teacher_statement_cases
        GROUP BY COALESCE(NULLIF(root_cause_code,''),'UNCLASSIFIED'),COALESCE(NULLIF(root_cause,''),'Unclassified')
        ORDER BY total_cases DESC,active_cases DESC LIMIT 100`)).rows;
    }
    async function refreshTeacherCaseRecurrence(){
      const roots=(await pool.query(`SELECT DISTINCT root_cause_code FROM learning_teacher_statement_cases WHERE NULLIF(root_cause_code,'') IS NOT NULL`)).rows;
      const out=[];
      for(const r of roots){
        const c=(await pool.query(`SELECT COUNT(*) FILTER(WHERE created_at>=NOW()-INTERVAL '30 days')::int AS current_count,
          COUNT(*) FILTER(WHERE created_at>=NOW()-INTERVAL '60 days' AND created_at<NOW()-INTERVAL '30 days')::int AS previous_count
          FROM learning_teacher_statement_cases WHERE root_cause_code=$1`,[r.root_cause_code])).rows[0];
        const cur=Number(c.current_count||0),prev=Number(c.previous_count||0),rate=prev?Math.round(((cur-prev)/prev)*10000)/100:(cur>0?100:0);
        const trend=cur>prev?'RISING':cur<prev?'FALLING':'STABLE';
        out.push((await pool.query(`INSERT INTO learning_teacher_statement_recurrence_snapshots(root_cause_code,period_start,period_end,case_count,previous_case_count,recurrence_rate,trend)
          VALUES($1,(CURRENT_DATE-INTERVAL '29 days')::date,CURRENT_DATE,$2,$3,$4,$5)
          ON CONFLICT(root_cause_code,period_start,period_end) DO UPDATE SET case_count=EXCLUDED.case_count,previous_case_count=EXCLUDED.previous_case_count,recurrence_rate=EXCLUDED.recurrence_rate,trend=EXCLUDED.trend,created_at=NOW()
          RETURNING *`,[r.root_cause_code,cur,prev,rate,trend])).rows[0]);
      }
      return out.sort((x,y)=>Number(y.case_count)-Number(x.case_count));
    }

    async function scoreTeacherResolutionEffectiveness(caseId){
      const row=(await pool.query(`
        SELECT c.*,
          (SELECT COUNT(*)::int FROM learning_teacher_statement_case_reopen_requests r WHERE r.case_id=c.id) AS reopen_count,
          (SELECT rating FROM learning_teacher_statement_case_feedback f WHERE f.case_id=c.id LIMIT 1) AS feedback_rating
        FROM learning_teacher_statement_cases c WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!row)return null;
      let score=50; const reasons=[];
      if(row.teacher_resolution_confirmation==='ACCEPTED'){score+=30;reasons.push('TEACHER_ACCEPTED');}
      if(row.teacher_resolution_confirmation==='NOT_ACCEPTED'){score-=30;reasons.push('TEACHER_NOT_ACCEPTED');}
      const rating=Number(row.feedback_rating||0);
      if(rating>=4){score+=15;reasons.push('POSITIVE_FEEDBACK');}
      else if(rating>0&&rating<=2){score-=15;reasons.push('LOW_FEEDBACK');}
      if(Number(row.reopen_count||0)>0){score-=20;reasons.push('REOPENED_OR_REOPEN_REQUESTED');}
      if(row.status==='CLOSED'){score+=5;reasons.push('CLOSED');}
      score=Math.max(0,Math.min(100,score));
      const level=score>=80?'EXCELLENT':score>=60?'GOOD':score>=40?'MIXED':'POOR';
      await pool.query(`UPDATE learning_teacher_statement_cases SET resolution_effectiveness_score=$2,resolution_effectiveness_level=$3,resolution_effectiveness_scored_at=NOW() WHERE id=$1`,
        [caseId,score,level]);
      return {case_id:caseId,score,level,reasons};
    }

    async function scoreTeacherStatementCaseRisk(caseId){
      const row=(await pool.query(`
        SELECT c.*,
          EXISTS(SELECT 1 FROM learning_teacher_statement_case_reopen_requests r WHERE r.case_id=c.id AND r.status='PENDING') AS pending_reopen,
          EXISTS(SELECT 1 FROM learning_teacher_statement_case_followups f WHERE f.case_id=c.id AND f.status='PENDING' AND f.due_at<NOW()) AS overdue_followup
        FROM learning_teacher_statement_cases c WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!row)return null;
      let score=0; const reasons=[];
      const impact=String(row.impact_level||'NORMAL').toUpperCase();
      if(impact==='CRITICAL'){score+=40;reasons.push('CRITICAL_IMPACT');}
      else if(impact==='HIGH'){score+=25;reasons.push('HIGH_IMPACT');}
      if(row.finance_adjustment_id){score+=20;reasons.push('FINANCE_LINKED');}
      if(row.escalation_level>=3){score+=20;reasons.push('L3_ESCALATION');}
      else if(row.escalation_level>=1){score+=10;reasons.push('ESCALATED');}
      if(row.due_at && new Date(row.due_at)<new Date() && !['RESOLVED','CLOSED'].includes(row.status)){score+=15;reasons.push('SLA_OVERDUE');}
      if(row.pending_reopen){score+=10;reasons.push('PENDING_REOPEN');}
      if(row.overdue_followup){score+=10;reasons.push('OVERDUE_FOLLOWUP');}
      if(row.duplicate_of_case_id){score+=5;reasons.push('DUPLICATE_CANDIDATE');}
      score=Math.min(100,score);
      const level=score>=70?'CRITICAL':score>=45?'HIGH':score>=20?'MEDIUM':'LOW';
      await pool.query(`UPDATE learning_teacher_statement_cases SET risk_score=$2,risk_level=$3,risk_reasons=$4::jsonb,risk_scored_at=NOW() WHERE id=$1`,
        [caseId,score,level,JSON.stringify(reasons)]);
      return {case_id:caseId,score,level,reasons};
    }

    async function getTeacherCaseClosureApprovalRequirement(caseId){
      const row=(await pool.query(`
        SELECT c.id,c.status,c.impact_level,c.finance_adjustment_id,c.closure_approval_status,
               a.status AS adjustment_status,a.amount AS adjustment_amount
        FROM learning_teacher_statement_cases c
        LEFT JOIN hpay_finance_adjustments a ON a.id=c.finance_adjustment_id
        WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!row)return null;
      const impact=String(row.impact_level||'NORMAL').toUpperCase();
      const financeLinked=!!row.finance_adjustment_id;
      const required=impact==='HIGH'||impact==='CRITICAL'||financeLinked;
      return {
        required,
        reason: impact==='CRITICAL'?'CRITICAL_IMPACT':impact==='HIGH'?'HIGH_IMPACT':financeLinked?'FINANCE_ADJUSTMENT_LINKED':'STANDARD_CASE',
        approval_status:row.closure_approval_status||'NOT_REQUIRED',
        finance_linked:financeLinked,
        adjustment_status:row.adjustment_status||null,
        adjustment_amount:Number(row.adjustment_amount||0)
      };
    }

    async function getTeacherCaseFinanceImpactPreview(caseId){
      const item=(await pool.query(`
        SELECT c.id,c.case_number,c.statement_month,c.finance_adjustment_id,c.resolution,
               a.id AS adjustment_id,a.adjustment_number,a.adjustment_type,a.amount,
               a.status AS adjustment_status,a.posted_at,a.posting_period_start,a.posting_period_end,
               fc.close_number AS original_close_number,fc.period_start AS original_period_start,fc.period_end AS original_period_end
        FROM learning_teacher_statement_cases c
        LEFT JOIN hpay_finance_adjustments a ON a.id=c.finance_adjustment_id
        LEFT JOIN hpay_finance_closes fc ON fc.id=a.original_close_id
        WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!item)return null;

      const amount=Number(item.amount||0);
      return {
        case_id:item.id,
        case_number:item.case_number,
        statement_month:item.statement_month,
        linked_adjustment: item.adjustment_id ? {
          id:item.adjustment_id,
          adjustment_number:item.adjustment_number,
          adjustment_type:item.adjustment_type,
          amount,
          status:item.adjustment_status,
          original_close_number:item.original_close_number,
          original_period_start:item.original_period_start,
          original_period_end:item.original_period_end,
          posting_period_start:item.posting_period_start,
          posting_period_end:item.posting_period_end,
          posted_at:item.posted_at
        } : null,
        impact:{
          direction: amount>0?'CREDIT':amount<0?'DEBIT':'NONE',
          absolute_amount:Math.abs(amount),
          historical_statement_mutated:false,
          current_period_journal_effect:amount,
          bank_transfer_performed:false
        },
        policy:{
          preview_only:true,
          no_balance_change:true,
          no_payment_action:true,
          closed_period_immutable:true
        }
      };
    }

    async function buildTeacherStatementCaseAuditPack(caseId){
      const item=(await pool.query(`
        SELECT c.*,u.full_name,u.howdi_id,u.email,
          a.adjustment_number,a.adjustment_type,a.amount AS adjustment_amount,a.status AS adjustment_status
        FROM learning_teacher_statement_cases c
        JOIN learning_teacher_profiles tp ON tp.id=c.teacher_profile_id
        JOIN users u ON u.id=tp.user_id
        LEFT JOIN hpay_finance_adjustments a ON a.id=c.finance_adjustment_id
        WHERE c.id=$1 LIMIT 1
      `,[caseId])).rows[0];
      if(!item)return null;
      const [timeline,messages,evidence,feedback,closure]=await Promise.all([
        pool.query(`SELECT * FROM learning_teacher_statement_case_events WHERE case_id=$1 ORDER BY created_at,id`,[caseId]),
        pool.query(`SELECT * FROM learning_teacher_statement_case_messages WHERE case_id=$1 ORDER BY created_at,id`,[caseId]),
        pool.query(`SELECT * FROM learning_teacher_statement_case_evidence WHERE case_id=$1 ORDER BY created_at,id`,[caseId]),
        pool.query(`SELECT * FROM learning_teacher_statement_case_feedback WHERE case_id=$1 LIMIT 1`,[caseId]),
        getTeacherStatementClosureChecklist(caseId)
      ]);
      return {generated_at:new Date().toISOString(),release:'V19.36',case:item,closure,evidence:evidence.rows,timeline:timeline.rows,messages:messages.rows,feedback:feedback.rows[0]||null};
    }

    async function getTeacherStatementCaseAnalytics(){
      const summary=(await pool.query(`
        SELECT
          COUNT(*) FILTER(WHERE case_type='DISPUTE')::int AS total_disputes,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND status='OPEN')::int AS open,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND status='UNDER_REVIEW')::int AS under_review,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND status='RESOLVED')::int AS resolved,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND status='CLOSED')::int AS closed,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND status IN('OPEN','UNDER_REVIEW') AND due_at<NOW())::int AS overdue,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND priority='CRITICAL' AND status IN('OPEN','UNDER_REVIEW'))::int AS critical_open,
          COUNT(*) FILTER(WHERE case_type='DISPUTE' AND assigned_to IS NULL AND status IN('OPEN','UNDER_REVIEW'))::int AS unassigned,
          COALESCE(AVG(EXTRACT(EPOCH FROM (resolved_at-created_at))/3600.0) FILTER(WHERE case_type='DISPUTE' AND resolved_at IS NOT NULL),0)::numeric AS avg_resolution_hours,
          COALESCE(PERCENTILE_CONT(0.5) WITHIN GROUP(ORDER BY EXTRACT(EPOCH FROM (resolved_at-created_at))/3600.0) FILTER(WHERE case_type='DISPUTE' AND resolved_at IS NOT NULL),0)::numeric AS median_resolution_hours
        FROM learning_teacher_statement_cases
      `)).rows[0];

      const aging=(await pool.query(`
        SELECT
          COUNT(*) FILTER(WHERE age_hours<24)::int AS under_24h,
          COUNT(*) FILTER(WHERE age_hours>=24 AND age_hours<48)::int AS h24_48,
          COUNT(*) FILTER(WHERE age_hours>=48 AND age_hours<72)::int AS h48_72,
          COUNT(*) FILTER(WHERE age_hours>=72)::int AS over_72h
        FROM (
          SELECT EXTRACT(EPOCH FROM (NOW()-created_at))/3600.0 AS age_hours
          FROM learning_teacher_statement_cases
          WHERE case_type='DISPUTE' AND status IN('OPEN','UNDER_REVIEW')
        ) q
      `)).rows[0];

      const ownerLoad=(await pool.query(`
        SELECT COALESCE(NULLIF(assigned_to,''),'UNASSIGNED') AS owner,
               COUNT(*)::int AS active_cases,
               COUNT(*) FILTER(WHERE due_at<NOW())::int AS overdue_cases,
               COUNT(*) FILTER(WHERE priority='CRITICAL')::int AS critical_cases
        FROM learning_teacher_statement_cases
        WHERE case_type='DISPUTE' AND status IN('OPEN','UNDER_REVIEW')
        GROUP BY COALESCE(NULLIF(assigned_to,''),'UNASSIGNED')
        ORDER BY active_cases DESC,owner
        LIMIT 30
      `)).rows;

      const priority=(await pool.query(`
        SELECT priority,COUNT(*)::int AS cases
        FROM learning_teacher_statement_cases
        WHERE case_type='DISPUTE' AND status IN('OPEN','UNDER_REVIEW')
        GROUP BY priority ORDER BY cases DESC
      `)).rows;

      const trend=(await pool.query(`
        SELECT TO_CHAR(date_trunc('day',created_at),'YYYY-MM-DD') AS day,
               COUNT(*) FILTER(WHERE case_type='DISPUTE')::int AS created,
               COUNT(*) FILTER(WHERE case_type='DISPUTE' AND resolved_at IS NOT NULL AND date_trunc('day',resolved_at)=date_trunc('day',created_at))::int AS same_day_resolved
        FROM learning_teacher_statement_cases
        WHERE created_at>=NOW()-INTERVAL '14 days'
        GROUP BY date_trunc('day',created_at)
        ORDER BY date_trunc('day',created_at)
      `)).rows;

      return {summary,aging,owner_load:ownerLoad,priority,trend,generated_at:new Date().toISOString()};
    }

