    function saveVendorProductMedia(vendorCode,file){
      if(!file||!file.dataUrl)throw new Error("Product image is required");
      const match=String(file.dataUrl).match(/^data:([^;]+);base64,(.+)$/);
      if(!match)throw new Error("Invalid product image");
      const mime=match[1].toLowerCase();
      const allowed=["image/jpeg","image/png","image/webp"];
      if(!allowed.includes(mime))throw new Error("Product image must be JPG, PNG or WEBP");
      const raw=Buffer.from(match[2],"base64");
      if(raw.length>5*1024*1024)throw new Error("Each product image must be under 5 MB");
      const safeVendor=String(vendorCode||"vendor").replace(/[^a-zA-Z0-9_-]/g,"_");
      const dir=path.join(VENDOR_PRODUCT_MEDIA_DIR,safeVendor);
      if(!fs.existsSync(dir))fs.mkdirSync(dir,{recursive:true});
      const ext=mime==="image/png"?".png":mime==="image/webp"?".webp":".jpg";
      const original=safeUploadName(file.name||"product").replace(/\.[^.]+$/g,"").slice(0,60)||"product";
      const fileName=`${Date.now()}_${crypto.randomBytes(5).toString("hex")}_${original}${ext}`;
      fs.writeFileSync(path.join(dir,fileName),raw);
      return {vendorFolder:safeVendor,fileName,mime,size:raw.length};
    }

    function serveVendorProductMedia(pathname,res){
      const prefix="/media/vendor-products/";
      if(!pathname.startsWith(prefix))return false;
      let relative="";
      try{relative=decodeURIComponent(pathname.slice(prefix.length));}catch{return false;}
      const parts=relative.split("/").filter(Boolean);
      if(parts.length!==2)return false;
      const vendor=parts[0].replace(/[^a-zA-Z0-9_-]/g,"");
      const file=parts[1].replace(/[^a-zA-Z0-9._-]/g,"");
      if(!vendor||!file)return false;
      const full=path.join(VENDOR_PRODUCT_MEDIA_DIR,vendor,file);
      const root=path.resolve(VENDOR_PRODUCT_MEDIA_DIR)+path.sep;
      if(!path.resolve(full).startsWith(root)||!fs.existsSync(full)||!fs.statSync(full).isFile())return false;
      const ext=path.extname(full).toLowerCase();
      const type=ext===".png"?"image/png":ext===".webp"?"image/webp":"image/jpeg";
      res.writeHead(200,{
        "Content-Type":type,
        "Cache-Control":"public, max-age=31536000, immutable",
        "Access-Control-Allow-Origin":"*",
        "X-Content-Type-Options":"nosniff"
      });
      fs.createReadStream(full).pipe(res);
      return true;
    }

