    cleanupStaleWorksTriggers().catch(()=>{});

    // HOWDI R9 — WORKER AVAILABILITY RECONCILIATION
    // Historical/stale offers must never permanently lock a worker.
    // A journey blocks while it is genuinely active. A plain unanswered offer
    // blocks only during its live offer window; terminal work states never block.
    async function getWorkerBlockingWork(workerId, excludeWorkId=null, db=pool){
      const q=await db.query(`
        SELECT wo.id,wo.work_code,wo.status,wo.updated_at,
          COALESCE(j.stage,'') AS journey_stage,
          COALESCE(o.status,'') AS offer_status,
          j.accepted_at AS journey_accepted_at,
          j.updated_at AS journey_updated_at,
          o.offered_at AS offer_offered_at,
          o.updated_at AS offer_updated_at
        FROM works_work_orders wo
        LEFT JOIN works_work_offers o
          ON o.work_order_id=wo.id AND o.worker_id=$1
        LEFT JOIN works_job_journeys j
          ON j.work_order_id=wo.id AND j.worker_id=$1
        WHERE
          ($2::bigint IS NULL OR wo.id<>$2::bigint)
          AND COALESCE(wo.active,TRUE)=TRUE
          AND LOWER(COALESCE(wo.status,'')) NOT IN
              ('completed','closed','cancelled','canceled','rejected','refunded','failed')
          AND (
            LOWER(COALESCE(j.stage,'')) IN
              ('accepted','en_route','arrived','pin_verified','in_progress','work_started')
            OR (
              LOWER(COALESCE(o.status,'')) IN ('accepted','assigned')
              AND LOWER(COALESCE(wo.status,'')) IN
                  ('assigned','accepted','en_route','arrived','pin_verified','in_progress','work_started')
            )
            OR (
              LOWER(COALESCE(o.status,''))='offered'
              AND COALESCE(o.offered_at,o.updated_at,wo.updated_at) >= NOW()-INTERVAL '30 minutes'
              AND LOWER(COALESCE(wo.status,'')) IN ('open','offered')
            )
          )
        ORDER BY COALESCE(j.updated_at,o.updated_at,wo.updated_at) DESC
        LIMIT 1
      `,[workerId,excludeWorkId||null]);
      return q.rows[0]||null;
    }
    async function assertWorkerAvailableForWork(workerId, excludeWorkId=null, db=pool){
      const worker=await db.query(`SELECT id,full_name,availability_status,availability_until FROM works_workers WHERE id=$1 LIMIT 1`,[workerId]);
      if(!worker.rows[0]) return {ok:false,code:'WORKER_NOT_FOUND',message:'Worker not found'};

      const row=worker.rows[0];
      const availability=String(row.availability_status||'online').toLowerCase();
      if(availability==='offline') return {ok:false,code:'WORKER_OFFLINE',message:'This worker is currently offline. Please choose another available worker.'};

      const blocking=await getWorkerBlockingWork(workerId,excludeWorkId,db);
      if(blocking) return {
        ok:false,code:'WORKER_BUSY',
        message:'This worker already has an active HOWDI Works offer/job. Please choose another available worker.',
        blockingWorkCode:blocking.work_code||null
      };

      // A stale BUSY flag without a live job/offer must not permanently lock the worker.
      // availability_until is honored only while it is still in the future.
      if(availability==='busy' && row.availability_until && new Date(row.availability_until).getTime()>Date.now()){
        return {ok:false,code:'WORKER_BUSY',message:'This worker is currently busy. Please choose another available worker.'};
      }

      return {ok:true,worker:row};
    }

