    // =====================================================
    // HOWDI V19.3J — RAZORPAY CHECKOUT HELPERS
    // =====================================================
    function howdiRazorpayConfigured(){
      return Boolean(String(process.env.RAZORPAY_KEY_ID||'').trim() && String(process.env.RAZORPAY_KEY_SECRET||'').trim());
    }
    function howdiRazorpayRequest(method,apiPath,payload=null){
      return new Promise((resolve,reject)=>{
        const key=String(process.env.RAZORPAY_KEY_ID||'').trim();
        const secret=String(process.env.RAZORPAY_KEY_SECRET||'').trim();
        if(!key||!secret)return reject(new Error('Razorpay is not configured'));
        const body=payload?JSON.stringify(payload):'';
        const req=https.request({hostname:'api.razorpay.com',port:443,path:'/v1'+apiPath,method,headers:{Authorization:'Basic '+Buffer.from(key+':'+secret).toString('base64'),'Content-Type':'application/json',...(body?{'Content-Length':Buffer.byteLength(body)}:{})}},r=>{
          let raw=''; r.on('data',c=>raw+=c); r.on('end',()=>{let data={};try{data=raw?JSON.parse(raw):{}}catch{data={raw}};if(r.statusCode>=200&&r.statusCode<300)return resolve(data);reject(new Error(data?.error?.description||data?.error?.reason||`Razorpay API ${r.statusCode}`));});
        });
        req.on('error',reject); if(body)req.write(body); req.end();
      });
    }
    function howdiVerifyRazorpayPaymentSignature(orderId,paymentId,signature){
      const secret=String(process.env.RAZORPAY_KEY_SECRET||'').trim();
      if(!secret||!orderId||!paymentId||!signature)return false;
      const expected=crypto.createHmac('sha256',secret).update(String(orderId)+'|'+String(paymentId)).digest('hex');
      return howdiSafeEqualHex(expected,String(signature));
    }

    // =====================================================
    // HOWDI V19.3I — PAYMENT ADAPTER HELPERS
    // =====================================================
    function howdiPaymentProviderName(){
      return String(process.env.HOWDI_PAYMENT_PROVIDER||'').trim().toUpperCase();
    }
    function howdiPaymentAdapterEnabled(){
      return Boolean(howdiPaymentProviderName() && String(process.env.HOWDI_PAYMENT_ADAPTER_SECRET||'').trim());
    }
    function howdiSafeEqualHex(a,b){
      try{
        const aa=Buffer.from(String(a||''),'hex');
        const bb=Buffer.from(String(b||''),'hex');
        return aa.length>0 && aa.length===bb.length && crypto.timingSafeEqual(aa,bb);
      }catch{return false;}
    }
    function howdiPaymentCanonicalEvent(provider,body={}){
      return [
        String(provider||'').toUpperCase(),
        String(body.event_id||''),
        String(body.checkout_id||''),
        String(body.provider_payment_id||''),
        String(body.payment_status||'').toUpperCase(),
        Number(body.amount||0).toFixed(2),
        String(body.currency||'INR').toUpperCase()
      ].join('|');
    }
    function howdiVerifyPaymentAdapterSignature(provider,body,signature){
      const secret=String(process.env.HOWDI_PAYMENT_ADAPTER_SECRET||'').trim();
      if(!secret||!signature)return false;
      const expected=crypto.createHmac('sha256',secret).update(howdiPaymentCanonicalEvent(provider,body)).digest('hex');
      return howdiSafeEqualHex(expected,String(signature).replace(/^sha256=/i,''));
    }

    async function howdiActivateLearningPurchase(client,purchase,providerMeta={}){
      const course=(await client.query(`SELECT id,title,access_days FROM learning_courses WHERE id=$1::uuid LIMIT 1`,[purchase.course_id])).rows[0];
      if(!course)throw new Error('Learning course not found for purchase');
      const providerReference=String(providerMeta.provider_reference||providerMeta.provider_payment_id||purchase.provider_reference||'').trim()||null;
      const providerPaymentId=String(providerMeta.provider_payment_id||'').trim()||null;
      const providerName=String(providerMeta.provider||purchase.provider_name||'').trim().toUpperCase()||null;

      if(purchase.payment_transaction_id){
        await client.query(`
          UPDATE payment_transactions
          SET status='PAID',paid_at=COALESCE(paid_at,NOW()),provider=COALESCE($1::varchar,provider),
              provider_payment_id=COALESCE($2::varchar,provider_payment_id),reference=COALESCE($3::varchar,reference),updated_at=NOW()
          WHERE id=$4::bigint
        `,[providerName,providerPaymentId,providerReference,purchase.payment_transaction_id]);
      }

      const updated=(await client.query(`
        UPDATE learning_course_purchases
        SET payment_status='PAID',purchase_status='ACTIVE',provider_name=COALESCE($1::varchar,provider_name),
            provider_payment_id=COALESCE($2::varchar,provider_payment_id),provider_reference=COALESCE($3::varchar,provider_reference),
            paid_at=COALESCE(paid_at,NOW()),updated_at=NOW()
        WHERE id=$4::uuid
        RETURNING *
      `,[providerName,providerPaymentId,providerReference,purchase.id])).rows[0];

      const entitlement=(await client.query(`
        INSERT INTO learning_course_entitlements(user_id,course_id,purchase_id,entitlement_status,source,starts_at,ends_at)
        VALUES($1,$2::uuid,$3::uuid,'ACTIVE','PURCHASE',NOW(),CASE WHEN $4::int IS NULL THEN NULL ELSE NOW()+($4::int*INTERVAL '1 day') END)
        ON CONFLICT(user_id,course_id) DO UPDATE SET
          entitlement_status='ACTIVE',purchase_id=EXCLUDED.purchase_id,starts_at=NOW(),ends_at=EXCLUDED.ends_at,
          revoked_at=NULL,updated_at=NOW()
        RETURNING *
      `,[purchase.user_id,purchase.course_id,purchase.id,course.access_days||null])).rows[0];

      const enrollment=(await client.query(`
        INSERT INTO user_course_enrollments(user_id,course_id)
        VALUES($1,$2::uuid)
        ON CONFLICT(user_id,course_id) DO UPDATE SET updated_at=NOW()
        RETURNING *
      `,[purchase.user_id,purchase.course_id])).rows[0];

      await client.query(`
        INSERT INTO learning_course_entitlement_events(purchase_id,entitlement_id,user_id,course_id,event_type,actor,note,metadata)
        VALUES($1::uuid,$2::uuid,$3::bigint,$4::uuid,'PAYMENT_VERIFIED','PAYMENT_ADAPTER',$5::text,$6::jsonb)
      `,[purchase.id,entitlement.id,purchase.user_id,purchase.course_id,'Verified payment activated learner access',JSON.stringify({provider:providerName,provider_payment_id:providerPaymentId,provider_reference:providerReference})]);

      return {purchase:updated,entitlement,enrollment};
    }

    // =========================================================
    // HOWDI V14.0C — VIBE CREATOR STUDIO MEDIA STORAGE
    // Public local-development media storage. Production can later
    // swap this implementation for object storage/CDN without changing
    // the Vibe API response contract.
    // =========================================================
    const VIBE_MEDIA_DIR=path.join(DATA_DIR,"vibe_media_public");
    if(!fs.existsSync(VIBE_MEDIA_DIR))fs.mkdirSync(VIBE_MEDIA_DIR,{recursive:true});

    function saveVibeStudioMedia(userId,file,kind="media"){
      if(!file||!file.dataUrl)throw new Error("Choose a photo or video first");
      const match=String(file.dataUrl).match(/^data:([^;]+);base64,(.+)$/);
      if(!match)throw new Error("Invalid Vibe media file");
      const mime=String(match[1]||"").toLowerCase();
      const allowed=["image/jpeg","image/png","image/webp","video/mp4","video/webm","video/quicktime"];
      if(!allowed.includes(mime))throw new Error("Vibe media must be JPG, PNG, WEBP, MP4, WEBM or MOV");
      const raw=Buffer.from(match[2],"base64");
      const max=kind==="cover"?4*1024*1024:8*1024*1024;
      if(raw.length>max)throw new Error(kind==="cover"?"Vibe cover must be 4 MB or smaller":"Vibe media must be 8 MB or smaller in this build");
      const ext=mime==="image/png"?".png":mime==="image/webp"?".webp":mime==="video/webm"?".webm":mime==="video/quicktime"?".mov":mime==="video/mp4"?".mp4":".jpg";
      const safeUser=String(userId||"creator").replace(/[^a-zA-Z0-9_-]/g,"_").slice(0,60)||"creator";
      const userDir=path.join(VIBE_MEDIA_DIR,safeUser);
      if(!fs.existsSync(userDir))fs.mkdirSync(userDir,{recursive:true});
      const base=String(file.name||kind).replace(/\.[^.]+$/g,"").replace(/[^a-zA-Z0-9_-]/g,"_").slice(0,60)||kind;
      const fileName=`${Date.now()}_${crypto.randomBytes(6).toString("hex")}_${base}${ext}`;
      fs.writeFileSync(path.join(userDir,fileName),raw);
      return {folder:safeUser,fileName,mime,size:raw.length,type:mime.startsWith("image/")?"image":"video"};
    }

    function serveVibeStudioMedia(req,pathname,res){
      const prefix="/media/vibes/";
      if(!pathname.startsWith(prefix))return false;
      let relative="";
      try{relative=decodeURIComponent(pathname.slice(prefix.length));}catch{return false;}
      const parts=relative.split("/").filter(Boolean);
      if(parts.length!==2)return false;
      const folder=parts[0].replace(/[^a-zA-Z0-9_-]/g,"");
      const file=parts[1].replace(/[^a-zA-Z0-9._-]/g,"");
      if(!folder||!file)return false;
      const full=path.join(VIBE_MEDIA_DIR,folder,file);
      const root=path.resolve(VIBE_MEDIA_DIR)+path.sep;
      if(!path.resolve(full).startsWith(root)||!fs.existsSync(full)||!fs.statSync(full).isFile())return false;
      const stat=fs.statSync(full),ext=path.extname(full).toLowerCase();
      const type=ext===".png"?"image/png":ext===".webp"?"image/webp":ext===".mp4"?"video/mp4":ext===".webm"?"video/webm":ext===".mov"?"video/quicktime":"image/jpeg";
      const range=String(req.headers.range||"");
      const common={"Content-Type":type,"Accept-Ranges":"bytes","Cache-Control":"public, max-age=31536000, immutable","Access-Control-Allow-Origin":"*","X-Content-Type-Options":"nosniff"};
      if(range&&type.startsWith("video/")){
        const m=range.match(/bytes=(\d*)-(\d*)/);
        if(m){
          const start=m[1]?Math.max(0,Number(m[1])):0;
          const end=m[2]?Math.min(stat.size-1,Number(m[2])):Math.min(stat.size-1,start+1024*1024-1);
          if(Number.isFinite(start)&&Number.isFinite(end)&&start<=end&&start<stat.size){
            res.writeHead(206,{...common,"Content-Range":`bytes ${start}-${end}/${stat.size}`,"Content-Length":end-start+1});
            fs.createReadStream(full,{start,end}).pipe(res); return true;
          }
        }
      }
      res.writeHead(200,{...common,"Content-Length":stat.size});
      fs.createReadStream(full).pipe(res); return true;
    }

