    function vibeCursorEncode(row){
      if(!row?.published_at||!row?.id)return null;
      return Buffer.from(`${new Date(row.published_at).toISOString()}|${row.id}`).toString('base64url');
    }
    function vibeCursorDecode(value){
      try{
        if(!value)return null;
        const decoded=Buffer.from(String(value),'base64url').toString('utf8');
        const at=decoded.indexOf('|');
        if(at<1)return null;
        return {publishedAt:decoded.slice(0,at),id:decoded.slice(at+1)};
      }catch{return null;}
    }
    async function getVibeViewer(req){
      try{return await getSessionUserFromRequest(req);}catch{return null;}
    }

    async function createVibeEngagementNotification({recipientUserId,actorUserId,type,vibeId=null,commentId=null,message=null}){
      try{
        if(!recipientUserId||String(recipientUserId)===String(actorUserId||''))return;
        await pool.query(`INSERT INTO vibe_engagement_notifications(recipient_user_id,actor_user_id,notification_type,vibe_id,comment_id,message) VALUES($1,$2,$3,$4,$5,$6)`,[
          String(recipientUserId),actorUserId?String(actorUserId):null,String(type||'engagement').slice(0,50),vibeId||null,commentId||null,message?String(message).slice(0,500):null
        ]);
      }catch(error){console.warn('⚠️ Vibe notification skipped:',error.message);}
    }
    async function getVibeCommentIdentity(userId,viewerId){
      const q=await pool.query(`SELECT COALESCE(NULLIF(p.display_name,''),NULLIF(u.full_name,''),'HOWDI Creator') AS name,p.public_username AS username,NULLIF(p.avatar_url,'') AS avatar,p.verified_status,p.verified_label FROM users u LEFT JOIN vibe_creator_profiles p ON p.user_id=u.id::text WHERE u.id::text=$1 LIMIT 1`,[String(userId)]).catch(()=>({rows:[]}));
      const r=q.rows[0]||{};
      return {userId:String(userId),name:r.name||'HOWDI Creator',username:r.username||'',avatar:r.avatar||'',verified:['verified','official','trusted'].includes(String(r.verified_status||'').toLowerCase()),verifiedLabel:r.verified_label||null,isSelf:Boolean(viewerId&&String(viewerId)===String(userId))};
    }

    async function nextVibeCode(){
      const q=await pool.query(`SELECT COALESCE(MAX(NULLIF(regexp_replace(vibe_code,'\\D','','g'),'' )::bigint),0)+1 AS n FROM vibes`);
      return `VIBE-${String(q.rows[0]?.n||1).padStart(6,'0')}`;
    }
    const VIBE_RESERVED_USERNAMES=new Set(['howdi','admin','administrator','support','help','system','official','security','payments','hpay','shop','works','learn','vibe','creator','moderator','root','api']);
    function normalizeVibePublicUsername(value){
      return String(value||'').trim().toLowerCase().replace(/^@+/,'').replace(/[^a-z0-9._]/g,'').replace(/^[._]+|[._]+$/g,'').slice(0,30);
    }
    function validVibePublicUsername(value){
      const v=normalizeVibePublicUsername(value);
      return v.length>=3&&v.length<=30&&/^[a-z0-9][a-z0-9._]*[a-z0-9]$/.test(v)&&!VIBE_RESERVED_USERNAMES.has(v);
    }
    async function resolveVibeCreatorIdentifier(identifier){
      const raw=String(identifier||'').trim().replace(/^@+/,'');
      if(!raw)return null;
      const byUsername=(await pool.query(`SELECT user_id FROM vibe_creator_profiles WHERE LOWER(public_username)=LOWER($1) LIMIT 1`,[raw])).rows[0];
      if(byUsername?.user_id)return String(byUsername.user_id);
      // Backward-compatible internal fallback only. Public APIs/UI should send @username.
      if(/^\d+$/.test(raw)){
        const byId=(await pool.query(`SELECT user_id FROM vibe_creator_profiles WHERE user_id=$1 LIMIT 1`,[raw])).rows[0];
        if(byId?.user_id)return String(byId.user_id);
      }
      return null;
    }
    function publicVibeCreator(summary){
      if(!summary)return null;
      const {userId,...safe}=summary;
      return safe;
    }

    async function ensureUniqueVibePublicUsername(preferred,userId){
      let base=normalizeVibePublicUsername(preferred);
      if(!validVibePublicUsername(base)) base=`creator${String(userId||'user').replace(/\D/g,'').slice(-8)||Math.random().toString(36).slice(2,8)}`.slice(0,30);
      let candidate=base;
      for(let i=0;i<50;i++){
        const existing=(await pool.query(`SELECT user_id FROM vibe_creator_profiles WHERE LOWER(public_username)=LOWER($1) AND user_id<>$2 LIMIT 1`,[candidate,String(userId)])).rows[0];
        if(!existing)return candidate;
        const suffix=String(userId||i).replace(/\D/g,'').slice(-5)||String(i+1);
        candidate=`${base.slice(0,Math.max(3,29-suffix.length))}_${suffix}`.slice(0,30);
      }
      return `creator_${Date.now().toString(36).slice(-8)}`;
    }

    async function ensureVibeCreatorProfile(user){
      if(!user?.id)return null;
      const uid=String(user.id);
      const existing=(await pool.query(`SELECT * FROM vibe_creator_profiles WHERE user_id=$1 LIMIT 1`,[uid])).rows[0]||null;
      const fallbackSource=user.username||user.login_id||user.email?.split('@')?.[0]||user.full_name||user.name||`creator${uid}`;
      const publicUsername=existing?.public_username||await ensureUniqueVibePublicUsername(fallbackSource,uid);
      await pool.query(`INSERT INTO vibe_creator_profiles(user_id,display_name,howdi_id,public_username,avatar_url)
        VALUES($1,$2,$3,$4,$5)
        ON CONFLICT(user_id) DO UPDATE SET
          display_name=COALESCE(NULLIF(vibe_creator_profiles.display_name,''),EXCLUDED.display_name),
          howdi_id=COALESCE(vibe_creator_profiles.howdi_id,EXCLUDED.howdi_id),
          public_username=COALESCE(NULLIF(vibe_creator_profiles.public_username,''),EXCLUDED.public_username),
          avatar_url=COALESCE(vibe_creator_profiles.avatar_url,EXCLUDED.avatar_url),updated_at=NOW()`,[
        uid,user.full_name||user.name||'HOWDI Creator',user.howdi_id||null,publicUsername,user.profile_image||user.avatar||null
      ]);
      return (await pool.query(`SELECT * FROM vibe_creator_profiles WHERE user_id=$1 LIMIT 1`,[uid])).rows[0]||null;
    }

    async function getVibeCreatorSummary(creatorId,viewerId=null){
      const uid=String(creatorId||'').trim();
      if(!uid)return null;
      let user=null;
      if(/^\d+$/.test(uid)){
        user=(await pool.query(`SELECT id,full_name FROM users WHERE id=$1::bigint LIMIT 1`,[uid])).rows[0]||null;
      }
      const snapshot=(await pool.query(`SELECT creator_name,creator_avatar FROM vibes WHERE creator_user_id=$1 ORDER BY created_at DESC LIMIT 1`,[uid])).rows[0]||{};
      const profile=(await pool.query(`SELECT * FROM vibe_creator_profiles WHERE user_id=$1 LIMIT 1`,[uid])).rows[0]||{};
      const counts=(await pool.query(`SELECT
          (SELECT COUNT(*)::bigint FROM vibe_follows WHERE creator_user_id=$1) followers,
          (SELECT COUNT(*)::bigint FROM vibe_follows WHERE follower_user_id=$1) following,
          (SELECT COUNT(*)::bigint FROM vibes WHERE creator_user_id=$1 AND status='published' AND deleted_at IS NULL) published_vibes,
          (SELECT COUNT(*)::bigint FROM vibes WHERE creator_user_id=$1 AND is_learning_vibe=TRUE AND status='published' AND deleted_at IS NULL) learning_vibes,
          COALESCE((SELECT SUM(COALESCE(s.likes,0)) FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id WHERE v.creator_user_id=$1 AND v.deleted_at IS NULL),0)::bigint likes
        `,[uid])).rows[0]||{};
      const topCategories=(await pool.query(`SELECT c.id,c.name,c.slug,c.icon,c.is_learning,COUNT(*)::int AS vibe_count
          FROM vibes v JOIN vibe_category_map cm ON cm.vibe_id=v.id JOIN vibe_categories c ON c.id=cm.category_id
          WHERE v.creator_user_id=$1 AND v.status='published' AND v.deleted_at IS NULL
          GROUP BY c.id,c.name,c.slug,c.icon,c.is_learning ORDER BY COUNT(*) DESC,c.name LIMIT 6`,[uid])).rows;
      let followingCreator=false;
      if(viewerId)followingCreator=Boolean((await pool.query(`SELECT 1 FROM vibe_follows WHERE follower_user_id=$1 AND creator_user_id=$2 LIMIT 1`,[String(viewerId),uid])).rows[0]);
      let shopAvailable=Boolean(profile.shop_enabled);
      if(!shopAvailable&&/^\d+$/.test(uid)){
        try{shopAvailable=Boolean((await pool.query(`SELECT 1 FROM vendor_profiles WHERE user_id=$1::bigint AND status='active' LIMIT 1`,[uid])).rows[0]);}catch{}
      }
      const learningAvailable=Boolean(profile.learn_enabled!==false)&&(Number(counts.learning_vibes||0)>0||Boolean(profile.learn_enabled));
      return {
        userId:uid,
        name:profile.display_name||user?.full_name||snapshot.creator_name||'HOWDI Creator',
        username:profile.public_username||'',
        avatar:profile.avatar_url||snapshot.creator_avatar||null,
        coverUrl:profile.cover_url||null,
        headline:profile.headline||'',bio:profile.bio||'',creatorType:profile.creator_type||'creator',
        verified:profile.verified_status==='verified',verifiedStatus:profile.verified_status||'unverified',verifiedLabel:profile.verified_label||'',
        locationLabel:profile.location_label||'',websiteUrl:profile.website_url||'',instagramHandle:profile.instagram_handle||'',youtubeHandle:profile.youtube_handle||'',
        categories:topCategories,
        stats:{followers:Number(counts.followers||0),following:Number(counts.following||0),publishedVibes:Number(counts.published_vibes||0),learningVibes:Number(counts.learning_vibes||0),likes:Number(counts.likes||0)},
        viewerState:{followingCreator,isSelf:viewerId!=null&&String(viewerId)===uid},
        bridges:{shop:shopAvailable,learn:learningAvailable,works:Boolean(profile.works_enabled)}
      };
    }

    async function getCreatorPublishedVibes(creatorId,limit=24){
      const q=await pool.query(`SELECT v.*,
        COALESCE(s.likes,0) likes,COALESCE(s.comments,0) comments,COALESCE(s.saves,0) saves,COALESCE(s.shares,0) shares,
        COALESCE((SELECT json_agg(json_build_object('type',m.media_type,'url',m.media_url,'thumbnail',m.thumbnail_url,'durationMs',m.duration_ms) ORDER BY m.position) FROM vibe_media m WHERE m.vibe_id=v.id),'[]'::json) media
        FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
        WHERE v.creator_user_id=$1 AND v.status='published' AND v.deleted_at IS NULL
        ORDER BY v.published_at DESC NULLS LAST,v.created_at DESC LIMIT $2`,[String(creatorId),Math.min(60,Math.max(1,Number(limit)||24))]);
      return q.rows.map(v=>({id:v.id,vibeCode:v.vibe_code,type:v.vibe_type,caption:v.caption,coverUrl:v.cover_url||null,learning:Boolean(v.is_learning_vibe),publishedAt:v.published_at,media:v.media||[],stats:{likes:Number(v.likes||0),comments:Number(v.comments||0),saves:Number(v.saves||0),shares:Number(v.shares||0)}}));
    }

    async function getVibeFeedRows({mode='for-you',viewerId=null,limit=10,cursor=null}){
      const safeLimit=Math.min(30,Math.max(1,Number(limit)||10));
      const c=vibeCursorDecode(cursor);
      const params=[];
      const where=[`v.status='published'`,`v.visibility='public'`,`v.deleted_at IS NULL`];
      if(mode==='learn')where.push(`v.is_learning_vibe=TRUE`);
      if(mode==='following'){
        if(!viewerId)return [];
        params.push(String(viewerId));
        where.push(`EXISTS(SELECT 1 FROM vibe_follows vf WHERE vf.creator_user_id=v.creator_user_id AND vf.follower_user_id=$${params.length})`);
      }
      if(c){params.push(c.publishedAt,c.id);where.push(`(v.published_at,v.id)<($${params.length-1}::timestamptz,$${params.length}::uuid)`);}
      params.push(safeLimit+1);
      const order=mode==='quantum'
        ? `ORDER BY (COALESCE(s.saves,0)*3 + COALESCE(s.shares,0)*4 + COALESCE(s.completed_views,0)*2 + random()*10) DESC, v.published_at DESC`
        : `ORDER BY v.published_at DESC,v.id DESC`;
      const q=await pool.query(`
        SELECT v.*,COALESCE(s.impressions,0) impressions,COALESCE(s.plays,0) plays,
          COALESCE(s.completed_views,0) completed_views,COALESCE(s.likes,0) likes,
          COALESCE(s.comments,0) comments,COALESCE(s.saves,0) saves,
          COALESCE(s.shares,0) shares,COALESCE(s.remixes,0) remixes,
          COALESCE((SELECT json_agg(json_build_object('type',m.media_type,'url',m.media_url,'thumbnail',m.thumbnail_url,'width',m.width,'height',m.height,'durationMs',m.duration_ms) ORDER BY m.position) FROM vibe_media m WHERE m.vibe_id=v.id),'[]'::json) media,
          COALESCE((SELECT json_agg(json_build_object('name',c.name,'slug',c.slug,'learning',c.is_learning) ORDER BY cm.is_primary DESC,c.sort_order) FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id),'[]'::json) categories,
          COALESCE((SELECT json_agg(t.tag ORDER BY t.tag) FROM vibe_tag_map tm JOIN vibe_tags t ON t.id=tm.tag_id WHERE tm.vibe_id=v.id),'[]'::json) tags
        FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
        WHERE ${where.join(' AND ')} ${order} LIMIT $${params.length}` ,params);
      const hasMore=q.rows.length>safeLimit;
      const rows=q.rows.slice(0,safeLimit);
      return {rows,hasMore};
    }



