    async function serializeVibeDiscoveryRows(rows,viewer){
      const out=[]; const creatorCache=new Map();
      for(const v of rows||[]){
        const creatorKey=String(v.creator_user_id||'');
        if(!creatorCache.has(creatorKey))creatorCache.set(creatorKey,await getVibeCreatorSummary(creatorKey,viewer?.id||null));
        const creator=creatorCache.get(creatorKey)||{};
        let liked=false,saved=false;
        if(viewer?.id){
          liked=Boolean((await pool.query(`SELECT 1 FROM vibe_likes WHERE vibe_id=$1 AND user_id=$2 LIMIT 1`,[v.id,String(viewer.id)])).rows[0]);
          saved=Boolean((await pool.query(`SELECT 1 FROM vibe_saves WHERE vibe_id=$1 AND user_id=$2 LIMIT 1`,[v.id,String(viewer.id)])).rows[0]);
        }
        let remixSource=null;
        if(v.remix_source_vibe_id){
          const rq=(await pool.query(`SELECT src.id,src.caption,COALESCE(p.public_username,'creator') AS public_username FROM vibes src LEFT JOIN vibe_creator_profiles p ON p.user_id=src.creator_user_id WHERE src.id=$1 LIMIT 1`,[v.remix_source_vibe_id])).rows[0];
          if(rq)remixSource={id:rq.id,caption:rq.caption||'',username:rq.public_username||'creator'};
        }
        out.push({
          id:v.id,vibeCode:v.vibe_code,type:v.vibe_type,caption:v.caption,contentType:v.content_type,learning:Boolean(v.is_learning_vibe),publishedAt:v.published_at,coverUrl:v.cover_url||null,
          learningMeta:{subject:v.learning_subject||'',topic:v.learning_topic||'',difficulty:v.learning_difficulty||'',objective:v.learning_objective||'',estimatedMinutes:Number(v.estimated_learning_minutes||0),linkedCourseId:v.linked_course_id||null},
          bridges:{productId:v.linked_product_id||null,courseId:v.linked_course_id||null,serviceId:v.linked_service_id||null,communityId:v.linked_community_id||null},remixSource,
          creator:{username:creator.username||'',name:creator.name||v.creator_name||'HOWDI Creator',avatar:creator.avatar||v.creator_avatar||null,verified:Boolean(creator.verified),verifiedLabel:creator.verifiedLabel||'',headline:creator.headline||''},
          media:v.media||[],categories:v.categories||[],tags:v.tags||[],
          permissions:{comment:v.allow_comments,share:v.allow_share,remix:v.allow_remix,download:v.allow_download},
          stats:{impressions:Number(v.impressions||0),plays:Number(v.plays||0),likes:Number(v.likes||0),comments:Number(v.comments||0),saves:Number(v.saves||0),shares:Number(v.shares||0),remixes:Number(v.remixes||0),completedViews:Number(v.completed_views||0)},
          viewerState:{liked,saved,followingCreator:Boolean(creator.viewerState?.followingCreator)}
        });
      }
      return out;
    }

    async function getDiscoveryVibeRows(whereSql='TRUE',params=[],limit=30,orderSql='v.published_at DESC'){
      const lim=Math.max(1,Math.min(60,Number(limit)||30));
      const p=[...params,lim];
      return (await pool.query(`SELECT v.*,
        COALESCE(s.impressions,0) impressions,COALESCE(s.plays,0) plays,COALESCE(s.completed_views,0) completed_views,
        COALESCE(s.likes,0) likes,COALESCE(s.comments,0) comments,COALESCE(s.saves,0) saves,COALESCE(s.shares,0) shares,COALESCE(s.remixes,0) remixes,
        COALESCE((SELECT json_agg(json_build_object('type',m.media_type,'url',m.media_url,'thumbnail',m.thumbnail_url,'width',m.width,'height',m.height,'durationMs',m.duration_ms) ORDER BY m.position) FROM vibe_media m WHERE m.vibe_id=v.id),'[]'::json) media,
        COALESCE((SELECT json_agg(json_build_object('id',c.id,'name',c.name,'slug',c.slug,'learning',c.is_learning) ORDER BY cm.is_primary DESC,c.sort_order) FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id),'[]'::json) categories,
        COALESCE((SELECT json_agg(t.tag ORDER BY t.tag) FROM vibe_tag_map tm JOIN vibe_tags t ON t.id=tm.tag_id WHERE tm.vibe_id=v.id),'[]'::json) tags
        FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
        WHERE v.status='published' AND v.visibility='public' AND v.deleted_at IS NULL AND (${whereSql})
        ORDER BY ${orderSql} LIMIT $${p.length}` ,p)).rows;
    }


