    function clampV140H(v,min,max){return Math.max(min,Math.min(max,Number(v)||0));}
    function freshnessScoreV140H(publishedAt){
      const ageH=Math.max(0,(Date.now()-new Date(publishedAt||0).getTime())/3600000);
      if(ageH<=6)return 12;
      if(ageH<=24)return 10-(ageH-6)*0.12;
      if(ageH<=72)return 7.8-(ageH-24)*0.07;
      if(ageH<=168)return 4.5-(ageH-72)*0.025;
      return Math.max(0.5,2.1-ageH/720);
    }
    function qualityScoreV140H(row){
      const imp=Math.max(1,Number(row.impressions||0));
      const plays=Math.max(1,Number(row.plays||0));
      const completionRate=Number(row.completed_views||0)/plays;
      const saveRate=Number(row.saves||0)/plays;
      const shareRate=Number(row.shares||0)/plays;
      const likeRate=Number(row.likes||0)/plays;
      const commentRate=Number(row.comments||0)/plays;
      const confidence=Math.min(1,Math.log10(imp+10)/2.3);
      return clampV140H((completionRate*8 + saveRate*26 + shareRate*32 + likeRate*8 + commentRate*12)*confidence,0,20);
    }
    function primaryCategoryV140H(row){
      const cats=Array.isArray(row.categories)?row.categories:[];
      return cats[0]?.slug||cats[0]?.name||'general';
    }

    async function getVibeAIRankingPrefsV140H(userId){
      if(!userId)return {exploration_rate:.22,freshness_weight:1,diversity_strength:1,learning_bias:1,familiar_creator_bias:1,new_creator_boost:1,reduce_repetition:true,content_mix:'balanced'};
      await pool.query(`INSERT INTO vibe_ai_ranking_preferences(user_id) VALUES($1) ON CONFLICT DO NOTHING`,[String(userId)]).catch(()=>{});
      return (await pool.query(`SELECT * FROM vibe_ai_ranking_preferences WHERE user_id=$1`,[String(userId)])).rows[0];
    }

    async function getVibeAIRankedFeedV140H(viewer,limit=24){
      const lim=Math.max(1,Math.min(50,Number(limit)||24));
      const userId=viewer?.id?String(viewer.id):null;
      const requestId=`air-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;
      const candidateLimit=Math.max(80,Math.min(220,lim*6));
      const prefs=await getVibeAIRankingPrefsV140H(userId);

      const commonSelect=`SELECT v.*,
        COALESCE(s.impressions,0) impressions,COALESCE(s.plays,0) plays,COALESCE(s.completed_views,0) completed_views,COALESCE(s.likes,0) likes,COALESCE(s.comments,0) comments,COALESCE(s.saves,0) saves,COALESCE(s.shares,0) shares,COALESCE(s.remixes,0) remixes,
        COALESCE((SELECT json_agg(json_build_object('type',m.media_type,'url',m.media_url,'thumbnail',m.thumbnail_url,'width',m.width,'height',m.height,'durationMs',m.duration_ms) ORDER BY m.position) FROM vibe_media m WHERE m.vibe_id=v.id),'[]'::json) media,
        COALESCE((SELECT json_agg(json_build_object('id',c.id,'name',c.name,'slug',c.slug,'learning',c.is_learning) ORDER BY cm.is_primary DESC,c.sort_order) FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id),'[]'::json) categories,
        COALESCE((SELECT json_agg(t.tag ORDER BY t.tag) FROM vibe_tag_map tm JOIN vibe_tags t ON t.id=tm.tag_id WHERE tm.vibe_id=v.id),'[]'::json) tags`;

      let rows=[];
      let profile=null;
      let recentCreators=new Map(),recentCategories=new Map();
      let followedCreators=new Set();
      let languageCodes=[];
      let preferredLevel='';
      let preferLearning=false;
      let coldStart=!userId;

      if(userId){
        profile=(await pool.query(`SELECT * FROM vibe_user_feed_profile WHERE user_id=$1`,[userId])).rows[0]||{};
        const signals=await pool.query(`SELECT
          (SELECT COUNT(*) FROM vibe_watch_session_items WHERE user_id=$1) watch_items,
          (SELECT COUNT(*) FROM vibe_user_creator_affinity WHERE user_id=$1 AND ABS(affinity_score)>=2) creator_signals,
          (SELECT COUNT(*) FROM vibe_user_category_affinity WHERE user_id=$1 AND ABS(affinity_score)>=2) category_signals`,[userId]);
        coldStart=Number(signals.rows[0]?.watch_items||0)<8;
        const dp=(await pool.query(`SELECT language_codes,preferred_learning_level,prefer_learning FROM vibe_discovery_preferences WHERE user_id=$1`,[userId]).catch(()=>({rows:[]}))).rows[0]||{};
        languageCodes=Array.isArray(dp.language_codes)?dp.language_codes.map(String):[];
        preferredLevel=String(dp.preferred_learning_level||'').toLowerCase();
        preferLearning=Boolean(dp.prefer_learning);
        const recent=(await pool.query(`SELECT v.creator_user_id,
          COALESCE((SELECT c.slug FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id ORDER BY cm.is_primary DESC,c.sort_order LIMIT 1),'general') primary_category
          FROM vibe_view_history h JOIN vibes v ON v.id=h.vibe_id WHERE h.user_id=$1 ORDER BY h.last_viewed_at DESC LIMIT 30`,[userId])).rows;
        recent.forEach((r,i)=>{const c=String(r.creator_user_id||'');const k=String(r.primary_category||'general');recentCreators.set(c,(recentCreators.get(c)||0)+(30-i)/30);recentCategories.set(k,(recentCategories.get(k)||0)+(30-i)/30)});
        const follows=(await pool.query(`SELECT creator_user_id FROM vibe_follows WHERE follower_user_id=$1`,[userId])).rows;
        followedCreators=new Set(follows.map(x=>String(x.creator_user_id)));
        const q=await pool.query(`${commonSelect},
          COALESCE((SELECT affinity_score FROM vibe_user_creator_affinity a WHERE a.user_id=$1 AND a.creator_user_id=v.creator_user_id),0) creator_affinity,
          COALESCE((SELECT AVG(a.affinity_score) FROM vibe_category_map cm JOIN vibe_user_category_affinity a ON a.category_id=cm.category_id AND a.user_id=$1 WHERE cm.vibe_id=v.id),0) category_affinity,
          COALESCE((SELECT AVG(a.affinity_score) FROM vibe_tag_map tm JOIN vibe_user_tag_affinity a ON a.tag_id=tm.tag_id AND a.user_id=$1 WHERE tm.vibe_id=v.id),0) tag_affinity,
          COALESCE((SELECT view_count FROM vibe_view_history h WHERE h.user_id=$1 AND h.vibe_id=v.id),0) prior_views,
          COALESCE((SELECT EXTRACT(EPOCH FROM (NOW()-last_viewed_at))/3600 FROM vibe_view_history h WHERE h.user_id=$1 AND h.vibe_id=v.id),99999) hours_since_view
          FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
          WHERE v.status='published' AND v.visibility='public' AND v.deleted_at IS NULL
            AND NOT EXISTS(SELECT 1 FROM vibe_not_interested ni WHERE ni.vibe_id=v.id AND ni.user_id=$1)
            AND NOT EXISTS(SELECT 1 FROM vibe_creator_blocks b WHERE b.blocker_user_id=$1 AND b.blocked_creator_user_id=v.creator_user_id)
          ORDER BY v.published_at DESC LIMIT $2`,[userId,candidateLimit]);
        rows=q.rows;
      }else{
        rows=(await pool.query(`${commonSelect},0 creator_affinity,0 category_affinity,0 tag_affinity,0 prior_views,99999 hours_since_view
          FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
          WHERE v.status='published' AND v.visibility='public' AND v.deleted_at IS NULL
          ORDER BY v.published_at DESC LIMIT $1`,[candidateLimit])).rows;
      }

      const explorationRate=clampV140H(prefs.exploration_rate,.05,.45);
      const scored=rows.map(row=>{
        const creatorAffinity=Number(row.creator_affinity||0);
        const categoryAffinity=Number(row.category_affinity||0);
        const tagAffinity=Number(row.tag_affinity||0);
        const quality=qualityScoreV140H(row);
        const freshness=freshnessScoreV140H(row.published_at)*Number(prefs.freshness_weight||1);
        const cat=primaryCategoryV140H(row);
        const creator=String(row.creator_user_id||'');
        const creatorFatigue=(recentCreators.get(creator)||0)*1.8*Number(prefs.diversity_strength||1);
        const categoryFatigue=(recentCategories.get(cat)||0)*.75*Number(prefs.diversity_strength||1);
        const priorViews=Number(row.prior_views||0);
        const hoursSince=Number(row.hours_since_view||99999);
        const repetitionPenalty=Boolean(prefs.reduce_repetition)?Math.min(15,priorViews*3 + (hoursSince<6?8:hoursSince<24?4:0)):0;
        const followBoost=followedCreators.has(creator)?4.5*Number(prefs.familiar_creator_bias||1):0;
        const learningMatch=row.is_learning_vibe?(preferLearning?5:Math.max(0,Number(profile?.learning_affinity||0)/20))*Number(prefs.learning_bias||1):0;
        const levelMatch=preferredLevel&&String(row.learning_difficulty||'').toLowerCase()===preferredLevel?2.5:0;
        const languageMatch=languageCodes.length&&languageCodes.includes(String(row.language_code||''))?2:0;
        const affinityBase=creatorAffinity*1.8 + categoryAffinity*1.5 + tagAffinity*.8;
        const lowAffinity=Math.abs(creatorAffinity)<2&&Math.abs(categoryAffinity)<2;
        const explorationBoost=lowAffinity?(4+quality*.35)*Number(prefs.new_creator_boost||1):0;
        const coldStartBoost=coldStart?(quality*.9+freshness*.5):0;
        const negativePenalty=Math.max(0,-creatorAffinity)*1.1+Math.max(0,-categoryAffinity)*.8;
        let finalScore=affinityBase+quality+freshness+followBoost+learningMatch+levelMatch+languageMatch+explorationBoost+coldStartBoost-creatorFatigue-categoryFatigue-repetitionPenalty-negativePenalty;
        if(String(prefs.content_mix)==='learning'&&row.is_learning_vibe)finalScore+=5;
        if(String(prefs.content_mix)==='fresh')finalScore+=freshness*.5;
        const reasons=[];
        if(creatorAffinity>=4)reasons.push('Creator you often enjoy');
        if(categoryAffinity>=4)reasons.push('Matches your interests');
        if(tagAffinity>=4)reasons.push('Topics you engage with');
        if(followBoost>0)reasons.push('From a creator you follow');
        if(learningMatch>=3)reasons.push('Matches your learning intent');
        if(levelMatch>0)reasons.push('Matches your learning level');
        if(languageMatch>0)reasons.push('Preferred language');
        if(quality>=7)reasons.push('Strong completion and save signals');
        if(freshness>=8)reasons.push('Fresh');
        if(lowAffinity)reasons.push('Explore something new');
        return {row,score:finalScore,cat,creator,explore:lowAffinity,components:{creatorAffinity,categoryAffinity,tagAffinity,quality,freshness,followBoost,learningMatch,levelMatch,languageMatch,explorationBoost,coldStartBoost,creatorFatigue,categoryFatigue,repetitionPenalty,negativePenalty},reasons:reasons.slice(0,4)};
      }).sort((a,b)=>b.score-a.score);

      // Diversity pass: limits creator/category streaks while reserving exploration slots.
      const selected=[]; const creatorCount=new Map(); const catCount=new Map();
      const explorationTarget=Math.max(1,Math.round(lim*explorationRate)); let explored=0;
      const poolRows=[...scored];
      while(selected.length<lim&&poolRows.length){
        const pos=selected.length;
        const explorationSlot=explored<explorationTarget && ((pos+1)%5===0 || (lim-selected.length)<=explorationTarget-explored);
        let idx=poolRows.findIndex(x=>{
          const cc=creatorCount.get(x.creator)||0, kc=catCount.get(x.cat)||0;
          if(cc>=2)return false;
          if(kc>=4 && Number(prefs.diversity_strength||1)>=.5)return false;
          return explorationSlot?x.explore:true;
        });
        if(idx<0)idx=poolRows.findIndex(x=>(creatorCount.get(x.creator)||0)<3);
        if(idx<0)idx=0;
        const x=poolRows.splice(idx,1)[0];
        if(!x)break;
        x.explored=Boolean(explorationSlot&&x.explore); if(x.explored)explored++;
        creatorCount.set(x.creator,(creatorCount.get(x.creator)||0)+1);
        catCount.set(x.cat,(catCount.get(x.cat)||0)+1);
        selected.push(x);
      }

      const serialized=await serializeVibeDiscoveryRows(selected.map(x=>x.row),viewer);
      const items=serialized.map((item,i)=>({...item,ranking:{mode:'howdi-ai-v1',position:i+1,score:Math.round(selected[i].score*100)/100,explored:selected[i].explored,reasons:selected[i].reasons,components:selected[i].components}}));

      await pool.query(`INSERT INTO vibe_ai_feed_requests(request_id,user_id,feed_type,candidate_count,returned_count,exploration_slots,cold_start,profile_snapshot)
        VALUES($1,$2,'for-you',$3,$4,$5,$6,$7::jsonb)`,[requestId,userId,rows.length,items.length,explored,coldStart,JSON.stringify({learningAffinity:Number(profile?.learning_affinity||0),explorationRate,contentMix:prefs.content_mix})]).catch(()=>{});
      for(let i=0;i<Math.min(items.length,40);i++){
        const x=selected[i];
        await pool.query(`INSERT INTO vibe_ai_candidate_logs(request_id,user_id,vibe_id,position,final_score,score_components,reasons,explored) VALUES($1,$2,$3,$4,$5,$6::jsonb,$7::jsonb,$8)`,[requestId,userId,x.row.id,i+1,x.score,JSON.stringify(x.components),JSON.stringify(x.reasons),x.explored]).catch(()=>{});
        await pool.query(`INSERT INTO vibe_ranking_snapshots(user_id,vibe_id,feed_type,creator_affinity,category_affinity,quality_score,freshness_score,diversity_score,negative_score,final_score,reasons) VALUES($1,$2,'for-you',$3,$4,$5,$6,$7,$8,$9,$10::jsonb)`,[userId,x.row.id,x.components.creatorAffinity,x.components.categoryAffinity,x.components.quality,x.components.freshness,-x.components.creatorFatigue,-(x.components.repetitionPenalty+x.components.negativePenalty),x.score,JSON.stringify(x.reasons)]).catch(()=>{});
      }
      return {items,requestId,coldStart,explorationSlots:explored,candidateCount:rows.length};
    }


