    async function getVibeQuantumPrefsV140I(userId){
      if(!userId)return {surprise_level:.72,usefulness_weight:1.2,novelty_weight:1.2,cross_interest_weight:1,new_creator_weight:1.15,local_discovery_weight:.8,learning_bridge_weight:1,freshness_weight:1,avoid_recent_categories:true,avoid_recent_creators:true,discovery_mode:'balanced'};
      await pool.query(`INSERT INTO vibe_quantum_preferences(user_id) VALUES($1) ON CONFLICT DO NOTHING`,[String(userId)]).catch(()=>{});
      return (await pool.query(`SELECT * FROM vibe_quantum_preferences WHERE user_id=$1`,[String(userId)])).rows[0];
    }

    function quantumFreshnessV140I(publishedAt){
      const h=Math.max(0,(Date.now()-new Date(publishedAt||0).getTime())/3600000);
      if(h<12)return 8;if(h<48)return 6;if(h<168)return 4;return Math.max(.5,2-h/1000);
    }

    async function getVibeQuantumFeedV140I(viewer,limit=24){
      const lim=Math.max(1,Math.min(50,Number(limit)||24));
      const uid=viewer?.id?String(viewer.id):null;
      const prefs=await getVibeQuantumPrefsV140I(uid);
      const requestId=`qnt-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;
      const candidateLimit=Math.max(100,Math.min(260,lim*8));
      let topCats=new Set(),topCreators=new Set(),recentCats=new Map(),recentCreators=new Map(),preferredLanguages=[];
      if(uid){
        const cats=(await pool.query(`SELECT c.slug FROM vibe_user_category_affinity a JOIN vibe_categories c ON c.id=a.category_id WHERE a.user_id=$1 AND a.affinity_score>1 ORDER BY a.affinity_score DESC LIMIT 6`,[uid]).catch(()=>({rows:[]}))).rows;
        topCats=new Set(cats.map(x=>String(x.slug)));
        const cr=(await pool.query(`SELECT creator_user_id FROM vibe_user_creator_affinity WHERE user_id=$1 AND affinity_score>2 ORDER BY affinity_score DESC LIMIT 8`,[uid]).catch(()=>({rows:[]}))).rows;
        topCreators=new Set(cr.map(x=>String(x.creator_user_id)));
        const recent=(await pool.query(`SELECT v.creator_user_id,COALESCE((SELECT c.slug FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id ORDER BY cm.is_primary DESC,c.sort_order LIMIT 1),'general') cat FROM vibe_view_history h JOIN vibes v ON v.id=h.vibe_id WHERE h.user_id=$1 ORDER BY h.last_viewed_at DESC LIMIT 24`,[uid]).catch(()=>({rows:[]}))).rows;
        recent.forEach((x,i)=>{recentCreators.set(String(x.creator_user_id),(recentCreators.get(String(x.creator_user_id))||0)+1);recentCats.set(String(x.cat),(recentCats.get(String(x.cat))||0)+1)});
        const dp=(await pool.query(`SELECT language_codes FROM vibe_discovery_preferences WHERE user_id=$1`,[uid]).catch(()=>({rows:[]}))).rows[0]||{};
        preferredLanguages=Array.isArray(dp.language_codes)?dp.language_codes.map(String):[];
      }
      const q=await pool.query(`SELECT v.*,
        COALESCE(s.impressions,0) impressions,COALESCE(s.plays,0) plays,COALESCE(s.completed_views,0) completed_views,COALESCE(s.likes,0) likes,COALESCE(s.comments,0) comments,COALESCE(s.saves,0) saves,COALESCE(s.shares,0) shares,
        COALESCE((SELECT json_agg(json_build_object('type',m.media_type,'url',m.media_url,'thumbnail',m.thumbnail_url,'width',m.width,'height',m.height,'durationMs',m.duration_ms) ORDER BY m.position) FROM vibe_media m WHERE m.vibe_id=v.id),'[]'::json) media,
        COALESCE((SELECT json_agg(json_build_object('id',c.id,'name',c.name,'slug',c.slug,'learning',c.is_learning) ORDER BY cm.is_primary DESC,c.sort_order) FROM vibe_category_map cm JOIN vibe_categories c ON c.id=cm.category_id WHERE cm.vibe_id=v.id),'[]'::json) categories,
        COALESCE((SELECT json_agg(t.tag ORDER BY t.tag) FROM vibe_tag_map tm JOIN vibe_tags t ON t.id=tm.tag_id WHERE tm.vibe_id=v.id),'[]'::json) tags,
        COALESCE((SELECT COUNT(*) FROM vibes vx WHERE vx.creator_user_id=v.creator_user_id AND vx.status='published' AND vx.deleted_at IS NULL),0) creator_published_count,
        COALESCE((SELECT shown_count FROM vibe_quantum_discovery_memory qm WHERE qm.user_id=$1 AND qm.vibe_id=v.id),0) quantum_seen
        FROM vibes v LEFT JOIN vibe_stats s ON s.vibe_id=v.id
        WHERE v.status='published' AND v.visibility='public' AND v.deleted_at IS NULL
          AND ($1::text IS NULL OR NOT EXISTS(SELECT 1 FROM vibe_not_interested ni WHERE ni.user_id=$1 AND ni.vibe_id=v.id))
          AND ($1::text IS NULL OR NOT EXISTS(SELECT 1 FROM vibe_creator_blocks b WHERE b.blocker_user_id=$1 AND b.blocked_creator_user_id=v.creator_user_id))
        ORDER BY v.published_at DESC LIMIT $2`,[uid,candidateLimit]);
      const rows=q.rows;
      const scored=rows.map(row=>{
        const cats=Array.isArray(row.categories)?row.categories:[];
        const cat=String(cats[0]?.slug||'general');
        const creator=String(row.creator_user_id||'');
        const plays=Math.max(1,Number(row.plays||0)),imps=Math.max(1,Number(row.impressions||0));
        const completion=Number(row.completed_views||0)/plays;
        const saves=Number(row.saves||0)/plays,shares=Number(row.shares||0)/plays,comments=Number(row.comments||0)/plays;
        const usefulness=Math.min(18,(completion*8+saves*28+shares*34+comments*10))*Number(prefs.usefulness_weight||1.2);
        const lowExposure=Math.max(0,10-Math.log10(imps+10)*3);
        const unseenCategory=!topCats.has(cat)?7:1.5;
        const unseenCreator=!topCreators.has(creator)?6:1;
        const crossInterest=(unseenCategory?unseenCategory:0)*Number(prefs.cross_interest_weight||1);
        const newCreator=Math.max(0,7-Math.log10(Number(row.creator_published_count||0)+2)*2.8)*Number(prefs.new_creator_weight||1.15);
        const novelty=(lowExposure+unseenCategory+unseenCreator+newCreator)*Number(prefs.novelty_weight||1.2);
        const fresh=quantumFreshnessV140I(row.published_at)*Number(prefs.freshness_weight||1);
        const learningBridge=row.is_learning_vibe?4*Number(prefs.learning_bridge_weight||1):0;
        const languageBridge=preferredLanguages.length&&preferredLanguages.includes(String(row.language_code||''))?1.5:0;
        const recentCatPenalty=Boolean(prefs.avoid_recent_categories)?Math.min(9,(recentCats.get(cat)||0)*2.2):0;
        const recentCreatorPenalty=Boolean(prefs.avoid_recent_creators)?Math.min(12,(recentCreators.get(creator)||0)*3):0;
        const memoryPenalty=Math.min(14,Number(row.quantum_seen||0)*5);
        const surprise=(crossInterest+unseenCreator*1.4+lowExposure*.8)*Number(prefs.surprise_level||.65);
        let score=usefulness+novelty+fresh+learningBridge+languageBridge+surprise-recentCatPenalty-recentCreatorPenalty-memoryPenalty;
        const mode=String(prefs.discovery_mode||'balanced');
        if(mode==='knowledge'&&row.is_learning_vibe)score+=7;
        if(mode==='unknown')score+=unseenCategory*1.1+unseenCreator*1.2;
        if(mode==='new-creators')score+=newCreator*1.8;
        if(mode==='fresh')score+=fresh*.8;
        const reasons=[];
        if(unseenCategory>=7)reasons.push('Outside your usual categories');
        if(unseenCreator>=6)reasons.push('Creator you have not explored');
        if(lowExposure>=5)reasons.push('Hidden gem');
        if(usefulness>=7)reasons.push('High usefulness signals');
        if(learningBridge>0)reasons.push('Knowledge bridge');
        if(fresh>=6)reasons.push('Fresh discovery');
        if(newCreator>=4)reasons.push('Emerging creator');
        return {row,score,cat,creator,surprise,usefulness,novelty,components:{usefulness,novelty,crossInterest,newCreator,fresh,learningBridge,languageBridge,recentCatPenalty,recentCreatorPenalty,memoryPenalty,surprise},reasons:reasons.slice(0,4)};
      }).sort((x,y)=>y.score-x.score);
      const selected=[],creatorCounts=new Map(),catCounts=new Map();
      for(const x of scored){
        if(selected.length>=lim)break;
        if((creatorCounts.get(x.creator)||0)>=1 && selected.length<Math.floor(lim*.75))continue;
        if((catCounts.get(x.cat)||0)>=3)continue;
        creatorCounts.set(x.creator,(creatorCounts.get(x.creator)||0)+1);catCounts.set(x.cat,(catCounts.get(x.cat)||0)+1);selected.push(x);
      }
      for(const x of scored){if(selected.length>=lim)break;if(!selected.includes(x))selected.push(x)}
      const serialized=await serializeVibeDiscoveryRows(selected.map(x=>x.row),viewer);
      const items=serialized.map((item,i)=>({...item,quantum:{mode:'howdi-quantum-v1',position:i+1,score:Math.round(selected[i].score*100)/100,surpriseScore:Math.round(selected[i].surprise*100)/100,usefulnessScore:Math.round(selected[i].usefulness*100)/100,noveltyScore:Math.round(selected[i].novelty*100)/100,reasons:selected[i].reasons,components:selected[i].components}}));
      await pool.query(`INSERT INTO vibe_quantum_feed_requests(request_id,user_id,candidate_count,returned_count,surprise_slots,profile_snapshot) VALUES($1,$2,$3,$4,$5,$6::jsonb)`,[requestId,uid,rows.length,items.length,items.filter(x=>Number(x.quantum?.surpriseScore||0)>6).length,JSON.stringify({mode:prefs.discovery_mode,surpriseLevel:Number(prefs.surprise_level||0)})]).catch(()=>{});
      for(let i=0;i<selected.length;i++){
        const x=selected[i];
        await pool.query(`INSERT INTO vibe_quantum_candidate_logs(request_id,user_id,vibe_id,position,quantum_score,surprise_score,usefulness_score,novelty_score,reasons,score_components) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10::jsonb)`,[requestId,uid,x.row.id,i+1,x.score,x.surprise,x.usefulness,x.novelty,JSON.stringify(x.reasons),JSON.stringify(x.components)]).catch(()=>{});
        if(uid)await pool.query(`INSERT INTO vibe_quantum_discovery_memory(user_id,vibe_id) VALUES($1,$2) ON CONFLICT(user_id,vibe_id) DO UPDATE SET last_shown_at=NOW(),shown_count=vibe_quantum_discovery_memory.shown_count+1`,[uid,x.row.id]).catch(()=>{});
      }
      return {items,requestId,candidateCount:rows.length};
    }



