    async function getVibeSafetyBundle(userId){
      await pool.query(`INSERT INTO vibe_safety_preferences(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING`,[userId]);
      await pool.query(`INSERT INTO vibe_creator_comment_filters(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING`,[userId]);
      const [p,k,t,f,s]=await Promise.all([
        pool.query(`SELECT * FROM vibe_safety_preferences WHERE user_id=$1`,[userId]),
        pool.query(`SELECT keyword FROM vibe_muted_keywords WHERE user_id=$1 ORDER BY created_at DESC`,[userId]),
        pool.query(`SELECT tag FROM vibe_muted_tags WHERE user_id=$1 ORDER BY created_at DESC`,[userId]),
        pool.query(`SELECT * FROM vibe_creator_comment_filters WHERE user_id=$1`,[userId]),
        pool.query(`SELECT strike_type,severity,reason,status,expires_at,created_at FROM vibe_creator_strikes WHERE user_id=$1 AND status='active' ORDER BY created_at DESC LIMIT 20`,[userId])
      ]);
      return {preferences:p.rows[0]||{},mutedKeywords:k.rows.map(x=>x.keyword),mutedTags:t.rows.map(x=>x.tag),commentFilters:f.rows[0]||{},activeStrikes:s.rows};
    }

