    const vibeRuntimeV140L = {
      startedAt: new Date(), requests: 0, feedRequests: 0, errors: 0,
      lastErrorAt: null, lastErrorMessage: null, recentLatencies: [], eventDedupeHits: 0,
      mediaRangeRequests: 0, healthChecks: 0
    };
    function vibeMetricV140L(kind, ms=0, error=null){
      vibeRuntimeV140L.requests += 1;
      if(kind==='feed') vibeRuntimeV140L.feedRequests += 1;
      if(Number.isFinite(ms) && ms>=0){ vibeRuntimeV140L.recentLatencies.push(Math.round(ms)); if(vibeRuntimeV140L.recentLatencies.length>300) vibeRuntimeV140L.recentLatencies.shift(); }
      if(error){ vibeRuntimeV140L.errors += 1; vibeRuntimeV140L.lastErrorAt=new Date(); vibeRuntimeV140L.lastErrorMessage=String(error.message||error).slice(0,500); }
    }
    function vibePercentileV140L(values,p){
      if(!values.length)return 0; const a=[...values].sort((x,y)=>x-y); return a[Math.min(a.length-1,Math.max(0,Math.ceil((p/100)*a.length)-1))]||0;
    }

