    async function getVibeCommerceLinksV150A(vibeId){
      const q=await pool.query(`
        SELECT l.id,l.vibe_id,l.entity_type,l.entity_id,l.display_order,l.cta_type,l.label,l.is_featured,l.metadata,
          p.id AS product_id,p.name AS product_name,p.sku,p.category,p.subcategory,p.price,p.mrp,p.stock,p.image_urls,p.variant_options,p.status AS product_status,
          p.vendor_offer_enabled,p.vendor_offer_type,p.vendor_offer_value,p.campaign_permission,
          vp.store_name,vp.status AS vendor_status
        FROM vibe_commerce_links l
        LEFT JOIN vendor_products p ON l.entity_type='product' AND p.id::text=l.entity_id
        LEFT JOIN vendor_profiles vp ON vp.id=COALESCE(l.vendor_profile_id,p.vendor_profile_id)
        WHERE l.vibe_id=$1 AND l.is_active=TRUE
        ORDER BY l.is_featured DESC,l.display_order,l.created_at
      `,[vibeId]);
      return q.rows.map(r=>{
        if(r.entity_type==='product' && r.product_id){
          const imgs=Array.isArray(r.image_urls)?r.image_urls:[];
          return {
            id:r.id,type:'product',entityId:String(r.product_id),label:r.label||r.product_name,cta:r.cta_type||'shop',
            featured:!!r.is_featured,
            product:{id:r.product_id,name:r.product_name,sku:r.sku,category:r.category,subcategory:r.subcategory,
              price:Number(r.price||0),mrp:Number(r.mrp||0),stock:Number(r.stock||0),image:imgs[0]||'',images:imgs,
              variants:r.variant_options||{},status:r.product_status,storeName:r.store_name||'',available:r.product_status==='published'&&Number(r.stock||0)>0,
              offer:r.vendor_offer_enabled?{type:r.vendor_offer_type,value:Number(r.vendor_offer_value||0)}:null}
          };
        }
        return {id:r.id,type:r.entity_type,entityId:r.entity_id,label:r.label||`${r.entity_type} ${r.entity_id}`,cta:r.cta_type||'view',featured:!!r.is_featured,metadata:r.metadata||{}};
      });
    }


