    async function syncVibeReverseLinksV150D(vibeId){
      const q=await pool.query(`SELECT entity_type,entity_id,creator_user_id FROM vibe_commerce_links WHERE vibe_id=$1 AND is_active=TRUE`,[vibeId]);
      await pool.query(`DELETE FROM vibe_product_reverse_links WHERE vibe_id=$1`,[vibeId]);
      for(const r of q.rows){
        await pool.query(`INSERT INTO vibe_product_reverse_links(entity_type,entity_id,vibe_id,creator_user_id) VALUES($1,$2,$3,$4)
          ON CONFLICT(entity_type,entity_id,vibe_id) DO UPDATE SET creator_user_id=EXCLUDED.creator_user_id,linked_at=NOW()`,
          [r.entity_type,r.entity_id,vibeId,r.creator_user_id]);
      }
    }

    async function getCreatorStorefrontV150D(creatorUserId,viewerUserId=null){
      const profile=(await pool.query(`
        SELECT cp.user_id,cp.display_name,cp.public_username,cp.bio,cp.avatar_url,cp.is_verified,
               vp.id AS vendor_profile_id,vp.store_name,vp.logo_url,vp.status AS vendor_status
        FROM vibe_creator_profiles cp
        LEFT JOIN vendor_profiles vp ON vp.user_id=cp.user_id::bigint
        WHERE cp.user_id=$1
      `,[String(creatorUserId)])).rows[0];
      if(!profile)return null;

      const settings=(await pool.query(`SELECT * FROM vibe_creator_storefront_settings WHERE creator_user_id=$1`,[String(creatorUserId)])).rows[0]||{
        enabled:true,headline:null,bio:null,cover_url:null,featured_vibe_id:null,show_seen_in_vibes:true,show_best_sellers:true,show_recent_vibes:true,show_learning:true,show_services:true,product_limit:24
      };

      const products=(await pool.query(`
        SELECT p.id,p.name,p.sku,p.category,p.subcategory,p.price,p.mrp,p.stock,p.image_urls,p.variant_options,p.status,
               p.vendor_offer_enabled,p.vendor_offer_type,p.vendor_offer_value,
               COUNT(DISTINCT rl.vibe_id)::int AS vibe_count,
               COALESCE(SUM(CASE WHEN e.event_type='add_to_cart' THEN 1 ELSE 0 END),0)::int AS cart_actions,
               COALESCE(SUM(CASE WHEN e.event_type='wishlist' THEN 1 ELSE 0 END),0)::int AS wishlist_actions
        FROM vendor_profiles vp
        JOIN vendor_products p ON p.vendor_profile_id=vp.id
        LEFT JOIN vibe_product_reverse_links rl ON rl.entity_type='product' AND rl.entity_id=p.id::text
        LEFT JOIN vibe_commerce_events e ON e.entity_type='product' AND e.entity_id=p.id::text
        WHERE vp.user_id=$1 AND p.status IN ('published','active')
        GROUP BY p.id
        ORDER BY vibe_count DESC,cart_actions DESC,p.updated_at DESC
        LIMIT $2
      `,[Number(creatorUserId),Math.max(1,Math.min(60,Number(settings.product_limit||24)))])).rows;

      const recentVibes=(await pool.query(`
        SELECT v.id,v.caption,v.cover_url,v.published_at,
               COALESCE(vs.views,0)::int AS views,COALESCE(vs.likes,0)::int AS likes,COALESCE(vs.saves,0)::int AS saves
        FROM vibes v LEFT JOIN vibe_stats vs ON vs.vibe_id=v.id
        WHERE v.creator_user_id=$1 AND v.status='published' AND COALESCE(v.visibility,'public')='public'
        ORDER BY v.published_at DESC NULLS LAST,v.created_at DESC LIMIT 12
      `,[String(creatorUserId)])).rows;

      const seenInVibes=(await pool.query(`
        SELECT p.id,p.name,p.price,p.mrp,p.stock,p.image_urls,
               COUNT(DISTINCT rl.vibe_id)::int AS vibe_count,
               MAX(rl.linked_at) AS last_seen_in_vibe_at
        FROM vibe_product_reverse_links rl
        JOIN vendor_products p ON rl.entity_type='product' AND p.id::text=rl.entity_id
        WHERE rl.creator_user_id=$1 AND p.status IN ('published','active')
        GROUP BY p.id
        ORDER BY vibe_count DESC,last_seen_in_vibe_at DESC LIMIT 20
      `,[String(creatorUserId)])).rows;

      return {
        creator:{displayName:profile.display_name,username:profile.public_username,avatarUrl:profile.avatar_url,bio:profile.bio,verified:!!profile.is_verified},
        store:{name:profile.store_name||profile.display_name,logoUrl:profile.logo_url||profile.avatar_url,status:profile.vendor_status||null},
        settings,
        products:products.map(p=>({...p,price:Number(p.price||0),mrp:Number(p.mrp||0),stock:Number(p.stock||0)})),
        seenInVibes:seenInVibes.map(p=>({...p,price:Number(p.price||0),mrp:Number(p.mrp||0),stock:Number(p.stock||0)})),
        recentVibes
      };
    }


