    async function getVibeCommerceRecommendationsV150G({viewerUserId=null,vibeId=null,linkId=null,productId=null,limit=12}={}){
      const safeLimit=Math.max(1,Math.min(24,Number(limit||12)));
      let source=null;
      if(productId){
        source=(await pool.query(`SELECT p.*,vp.store_name FROM vendor_products p LEFT JOIN vendor_profiles vp ON vp.id=p.vendor_profile_id WHERE p.id::text=$1 LIMIT 1`,[String(productId)])).rows[0];
      }
      if(!source&&linkId){
        source=(await pool.query(`SELECT p.*,vp.store_name FROM vibe_commerce_links l JOIN vendor_products p ON p.id::text=l.entity_id LEFT JOIN vendor_profiles vp ON vp.id=p.vendor_profile_id WHERE l.id=$1 AND l.entity_type='product' LIMIT 1`,[linkId])).rows[0];
      }
      if(!source)return [];

      const q=await pool.query(`
        WITH perf AS (
          SELECT entity_id,
            COUNT(*) FILTER(WHERE event_type='open')::numeric AS opens,
            COUNT(*) FILTER(WHERE event_type='add_to_cart')::numeric AS carts,
            COUNT(*) FILTER(WHERE event_type='purchase')::numeric AS purchases
          FROM vibe_commerce_events
          WHERE entity_type='product' AND created_at>=NOW()-INTERVAL '90 days'
          GROUP BY entity_id
        ),
        recent AS (
          SELECT product_id,seen_count,opened_count,cart_count FROM vibe_commerce_recent_products WHERE viewer_user_id=$1
        )
        SELECT p.id,p.name,p.category,p.subcategory,p.price,p.mrp,p.stock,p.image_urls,p.vendor_profile_id,vp.store_name,
          CASE WHEN p.vendor_profile_id=$2 THEN 18 ELSE 0 END +
          CASE WHEN LOWER(COALESCE(p.category,''))=LOWER(COALESCE($3,'')) THEN 24 ELSE 0 END +
          CASE WHEN LOWER(COALESCE(p.subcategory,''))=LOWER(COALESCE($4,'')) THEN 30 ELSE 0 END +
          LEAST(COALESCE(perf.carts,0)*2,20) + LEAST(COALESCE(perf.purchases,0)*5,30) +
          CASE WHEN recent.cart_count>0 THEN 10 WHEN recent.opened_count>0 THEN 5 ELSE 0 END AS growth_score
        FROM vendor_products p
        LEFT JOIN vendor_profiles vp ON vp.id=p.vendor_profile_id
        LEFT JOIN perf ON perf.entity_id=p.id::text
        LEFT JOIN recent ON recent.product_id=p.id::text
        WHERE p.status IN ('published','active') AND p.id::text<>$5 AND COALESCE(p.stock,0)>0
        ORDER BY growth_score DESC,p.updated_at DESC
        LIMIT $6
      `,[String(viewerUserId||''),source.vendor_profile_id,source.category,source.subcategory,String(source.id),safeLimit]);

      return q.rows.map((p,i)=>({...p,price:Number(p.price||0),mrp:Number(p.mrp||0),stock:Number(p.stock||0),
        growthScore:Number(p.growth_score||0),rank:i+1,
        recommendationType:String(p.subcategory||'').toLowerCase()===String(source.subcategory||'').toLowerCase()?'SIMILAR_STYLE':
          Number(p.vendor_profile_id)===Number(source.vendor_profile_id)?'CREATOR_CROSS_SELL':'DISCOVERY'}));
    }


