    async function getVibeMerchandisingV150H({viewerUserId=null,vibeId=null,linkId=null,productId=null}={}){
      const recommendations=await getVibeCommerceRecommendationsV150G({viewerUserId,vibeId,linkId,productId,limit:18});
      const source=productId?(await pool.query(`SELECT * FROM vendor_products WHERE id::text=$1 LIMIT 1`,[String(productId)])).rows[0]:null;
      if(!source)return {completeTheLook:[],frequentlyBought:[],smartUpsell:[],bundles:[]};

      const completeTheLook=recommendations.filter(p=>String(p.category||'').toLowerCase()!==String(source.category||'').toLowerCase()).slice(0,6);
      const frequentlyBought=(await pool.query(`
        WITH source_orders AS (
          SELECT DISTINCT oi.order_id FROM order_items oi JOIN orders o ON o.id=oi.order_id
          WHERE oi.product_id::text=$1 AND o.payment_status='PAID' AND o.created_at>=NOW()-INTERVAL '180 days'
        )
        SELECT p.id,p.name,p.category,p.subcategory,p.price,p.mrp,p.stock,p.image_urls,p.vendor_profile_id,COUNT(DISTINCT oi.order_id)::int AS together_count
        FROM source_orders so JOIN order_items oi ON oi.order_id=so.order_id
        JOIN vendor_products p ON p.id::text=oi.product_id::text
        WHERE p.id::text<>$1 AND p.status IN ('published','active') AND COALESCE(p.stock,0)>0
        GROUP BY p.id ORDER BY together_count DESC LIMIT 6
      `,[String(productId)])).rows.map(p=>({...p,price:Number(p.price||0),mrp:Number(p.mrp||0),recommendationType:'FREQUENTLY_BOUGHT'}));

      const basePrice=Number(source.price||0);
      const smartUpsell=recommendations.filter(p=>Number(p.price||0)>basePrice && Number(p.price||0)<=basePrice*1.35).slice(0,5);

      const bundles=(await pool.query(`
        SELECT b.*,json_agg(json_build_object('id',p.id,'name',p.name,'price',p.price,'mrp',p.mrp,'stock',p.stock,'image_urls',p.image_urls) ORDER BY bi.sort_order) AS products
        FROM vibe_commerce_bundle_items src JOIN vibe_commerce_bundle_definitions b ON b.id=src.bundle_id AND b.enabled=TRUE
        JOIN vibe_commerce_bundle_items bi ON bi.bundle_id=b.id JOIN vendor_products p ON p.id::text=bi.product_id
        WHERE src.product_id=$1 GROUP BY b.id ORDER BY b.updated_at DESC LIMIT 6
      `,[String(productId)])).rows;

      return {completeTheLook,frequentlyBought,smartUpsell,bundles};
    }


