    async function syncVibeCartSessionV150I({viewerUserId=null,sessionId,items=[]}={}){
      if(!sessionId)return null;
      const normalized=Array.isArray(items)?items:[];
      const vibeItems=normalized.filter(x=>x?.vibeAttribution?.vibeId||x?.vibe_attribution?.vibeId);
      const cartValue=normalized.reduce((s,x)=>s+Number(x.numericPrice??x.price??0)*Number(x.quantity||1),0);
      const vibeValue=vibeItems.reduce((s,x)=>s+Number(x.numericPrice??x.price??0)*Number(x.quantity||1),0);
      const first=vibeItems[0]?.vibeAttribution||vibeItems[0]?.vibe_attribution||null;
      const last=vibeItems[vibeItems.length-1]?.vibeAttribution||vibeItems[vibeItems.length-1]?.vibe_attribution||null;
      const client=await pool.connect();
      try{
        await client.query('BEGIN');
        const cart=(await client.query(`
          INSERT INTO vibe_commerce_cart_sessions(viewer_user_id,session_id,item_count,vibe_item_count,cart_value,vibe_cart_value,first_vibe_id,last_vibe_id)
          VALUES($1,$2,$3,$4,$5,$6,$7,$8)
          ON CONFLICT(session_id) DO UPDATE SET viewer_user_id=COALESCE(EXCLUDED.viewer_user_id,vibe_commerce_cart_sessions.viewer_user_id),
            item_count=EXCLUDED.item_count,vibe_item_count=EXCLUDED.vibe_item_count,cart_value=EXCLUDED.cart_value,vibe_cart_value=EXCLUDED.vibe_cart_value,
            first_vibe_id=COALESCE(vibe_commerce_cart_sessions.first_vibe_id,EXCLUDED.first_vibe_id),last_vibe_id=EXCLUDED.last_vibe_id,last_activity_at=NOW(),
            status=CASE WHEN vibe_commerce_cart_sessions.status='ABANDONED' AND EXCLUDED.item_count>0 THEN 'RECOVERED' ELSE vibe_commerce_cart_sessions.status END
          RETURNING *
        `,[viewerUserId?String(viewerUserId):null,String(sessionId),normalized.length,vibeItems.length,cartValue,vibeValue,first?.vibeId||null,last?.vibeId||null])).rows[0];

        for(const item of vibeItems){
          const a=item.vibeAttribution||item.vibe_attribution;
          const productId=String(item.product_id||item.id||'');
          if(!productId)continue;
          const link=a.linkId?(await client.query(`SELECT creator_user_id,vendor_profile_id FROM vibe_commerce_links WHERE id=$1 LIMIT 1`,[a.linkId])).rows[0]:null;
          const price=Number(item.numericPrice??item.price??0),qty=Number(item.quantity||1);
          await client.query(`
            INSERT INTO vibe_commerce_cart_items(cart_session_id,product_id,vibe_id,link_id,creator_user_id,vendor_profile_id,quantity,unit_price,price_when_added,stock_when_added,metadata)
            VALUES($1,$2,$3,$4,$5,$6,$7,$8,$8,$9,$10::jsonb)
            ON CONFLICT(cart_session_id,product_id) DO UPDATE SET quantity=EXCLUDED.quantity,unit_price=EXCLUDED.unit_price,
              vibe_id=EXCLUDED.vibe_id,link_id=EXCLUDED.link_id,status='IN_CART',updated_at=NOW()
          `,[cart.id,productId,a.vibeId||null,a.linkId||null,link?.creator_user_id||null,link?.vendor_profile_id||null,qty,price,
             item.stock==null?null:Number(item.stock),JSON.stringify({sourceType:a.sourceType||'vibe',playbackMs:a.playbackMs||0})]);
        }
        await client.query(`UPDATE vibe_commerce_cart_items SET status='REMOVED',updated_at=NOW() WHERE cart_session_id=$1 AND product_id<>ALL($2::text[])`,
          [cart.id,normalized.map(x=>String(x.product_id||x.id||'')).filter(Boolean)]);
        await client.query('COMMIT');
        return cart;
      }catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}
    }

    async function refreshVibeRecoverySignalsV150I(viewerUserId){
      if(!viewerUserId)return [];
      const q=await pool.query(`
        SELECT ci.*,p.price AS live_price,p.stock AS live_stock,p.name,p.image_urls,cs.session_id
        FROM vibe_commerce_cart_items ci JOIN vibe_commerce_cart_sessions cs ON cs.id=ci.cart_session_id
        JOIN vendor_products p ON p.id::text=ci.product_id
        WHERE cs.viewer_user_id=$1 AND ci.status='IN_CART' AND cs.status IN ('ACTIVE','ABANDONED','RECOVERED')
        ORDER BY ci.updated_at DESC LIMIT 50
      `,[String(viewerUserId)]);
      for(const x of q.rows){
        const livePrice=Number(x.live_price||0),oldPrice=Number(x.price_when_added||0),liveStock=Number(x.live_stock||0);
        const signals=[];
        if(livePrice>0&&oldPrice>0&&livePrice<oldPrice)signals.push(['PRICE_DROP',oldPrice,livePrice]);
        if(livePrice>oldPrice)signals.push(['PRICE_INCREASE',oldPrice,livePrice]);
        if(liveStock<=0)signals.push(['OUT_OF_STOCK',x.stock_when_added,liveStock]);
        else if(liveStock<=3)signals.push(['LOW_STOCK',x.stock_when_added,liveStock]);
        for(const [type,prev,current] of signals){
          const exists=(await pool.query(`SELECT id FROM vibe_commerce_recovery_signals WHERE cart_session_id=$1 AND product_id=$2 AND signal_type=$3 AND current_value=$4 AND status='NEW' LIMIT 1`,
            [x.cart_session_id,x.product_id,type,String(current)])).rows[0];
          if(!exists)await pool.query(`INSERT INTO vibe_commerce_recovery_signals(viewer_user_id,cart_session_id,product_id,signal_type,previous_value,current_value,metadata)
            VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)`,[String(viewerUserId),x.cart_session_id,x.product_id,type,String(prev??''),String(current),JSON.stringify({name:x.name,image_urls:x.image_urls})]);
        }
      }
      return q.rows;
    }


