    async function buildVibePostPurchaseV150J(viewerUserId,orderId){
      const order=(await pool.query(`SELECT * FROM orders WHERE id=$1 AND user_id::text=$2 LIMIT 1`,[orderId,String(viewerUserId)])).rows[0];
      if(!order)return null;
      const attrs=(await pool.query(`
        SELECT a.*,v.caption,v.creator_user_id,cp.display_name AS creator_name,cp.public_username,p.name AS product_name,p.image_urls
        FROM vibe_order_attribution a
        LEFT JOIN vibes v ON v.id=a.vibe_id
        LEFT JOIN vibe_creator_profiles cp ON cp.user_id=a.creator_user_id
        LEFT JOIN vendor_products p ON p.id::text=a.product_id
        WHERE a.order_id=$1 ORDER BY a.attributed_at ASC
      `,[orderId])).rows;
      const creatorMap=new Map();
      for(const a of attrs){
        if(!a.creator_user_id)continue;
        if(!creatorMap.has(String(a.creator_user_id)))creatorMap.set(String(a.creator_user_id),{
          creatorUserId:String(a.creator_user_id),creatorName:a.creator_name||a.public_username||'HOWDI Creator',username:a.public_username||null,
          vibeId:a.vibe_id,items:0,revenue:0,products:[]
        });
        const c=creatorMap.get(String(a.creator_user_id));c.items+=Number(a.quantity||1);c.revenue+=Number(a.net_revenue||a.attributed_line_amount||0);
        c.products.push({id:a.product_id,name:a.product_name,image:Array.isArray(a.image_urls)?a.image_urls[0]:null,vibeId:a.vibe_id});
      }
      const related=[];
      for(const c of creatorMap.values()){
        const q=await pool.query(`SELECT id,caption,media_type,media_url,thumbnail_url,created_at FROM vibes WHERE creator_user_id=$1 AND status='PUBLISHED' AND id<>$2 ORDER BY created_at DESC LIMIT 3`,
          [c.creatorUserId,c.vibeId||'00000000-0000-0000-0000-000000000000']);
        related.push(...q.rows.map(v=>({...v,creatorUserId:c.creatorUserId,creatorName:c.creatorName})));
      }
      return {order:{id:order.id,orderNumber:order.order_number,status:order.status,paymentStatus:order.payment_status,grandTotal:Number(order.grand_total||0)},
        creators:[...creatorMap.values()],relatedVibes:related.slice(0,8),attributedItems:attrs.length};
    }


