    async function getVibeOrderExperienceV150K(viewerUserId,orderId){
      const order=(await pool.query(`SELECT id,order_number,status,payment_status,grand_total,currency,created_at FROM orders WHERE id=$1 AND user_id::text=$2 LIMIT 1`,
        [orderId,String(viewerUserId)])).rows[0];
      if(!order)return null;
      await syncVibeOrderSourceSnapshotsV150K(orderId);
      const sources=(await pool.query(`
        SELECT s.*,oi.product_name,oi.image_url,oi.quantity,oi.line_total
        FROM vibe_commerce_order_source_snapshots s JOIN order_items oi ON oi.id=s.order_item_id
        WHERE s.order_id=$1 ORDER BY oi.created_at ASC
      `,[orderId])).rows;
      const creators=[];
      const seen=new Set();
      for(const s of sources){
        if(!s.creator_user_id||seen.has(String(s.creator_user_id)))continue;
        seen.add(String(s.creator_user_id));
        creators.push({creatorUserId:String(s.creator_user_id),name:s.creator_name||'HOWDI Creator',username:s.creator_username||null,vibeId:s.vibe_id,
          thumbnail:s.vibe_thumbnail_url||null,caption:s.vibe_caption||null});
      }
      const related=[];
      for(const c of creators){
        const q=await pool.query(`SELECT id,caption,media_type,media_url,thumbnail_url,created_at FROM vibes WHERE creator_user_id=$1 AND status='PUBLISHED' AND ($2::uuid IS NULL OR id<>$2) ORDER BY created_at DESC LIMIT 4`,
          [c.creatorUserId,c.vibeId||null]);
        related.push(...q.rows.map(v=>({...v,creatorUserId:c.creatorUserId,creatorName:c.name,creatorUsername:c.username})));
      }
      return {order:{...order,grand_total:Number(order.grand_total||0)},sources,creators,relatedVibes:related.slice(0,10),hasVibeSource:sources.length>0};
    }


