    async function getVibeSettlementSummaryV150M(creatorUserId){
      const creator=String(creatorUserId);
      const e=(await pool.query(`
        SELECT COALESCE(SUM(net_commission) FILTER(WHERE status='APPROVED' AND payable_at<=NOW()),0)::numeric AS payable,
          COALESCE(SUM(net_commission) FILTER(WHERE status='PENDING'),0)::numeric AS pending,
          COALESCE(SUM(net_commission) FILTER(WHERE status='PAID'),0)::numeric AS paid,
          COALESCE(SUM(reversed_commission),0)::numeric AS reversals
        FROM vibe_creator_earnings_ledger WHERE creator_user_id=$1
      `,[creator])).rows[0];
      const a=(await pool.query(`SELECT COALESCE(SUM(amount),0)::numeric AS adjustments FROM vibe_creator_settlement_adjustments WHERE creator_user_id=$1 AND status='APPROVED'`,[creator])).rows[0];
      const r=(await pool.query(`SELECT COALESCE(SUM(requested_amount),0)::numeric AS in_flight FROM vibe_creator_payout_requests WHERE creator_user_id=$1 AND status IN ('REQUESTED','UNDER_REVIEW','APPROVED','PROCESSING')`,[creator])).rows[0];
      const p=(await pool.query(`SELECT * FROM vibe_creator_payout_profiles WHERE creator_user_id=$1`,[creator])).rows[0];
      const payable=Number(e.payable||0),adjustments=Number(a.adjustments||0),inFlight=Number(r.in_flight||0);
      return {payable,pending:Number(e.pending||0),paid:Number(e.paid||0),reversals:Number(e.reversals||0),adjustments,inFlight,
        availableToRequest:Math.max(0,payable+adjustments-inFlight),profile:p||null};
    }


