    function vibeCreatorLevelV150N(xp){
      const n=Math.max(0,Number(xp||0));
      if(n>=25000)return 8;if(n>=12000)return 7;if(n>=6000)return 6;if(n>=3000)return 5;
      if(n>=1500)return 4;if(n>=700)return 3;if(n>=250)return 2;return 1;
    }
    function vibeCreatorTierV150N(level){return level>=8?'ICON':level>=6?'ELITE':level>=4?'PRO':level>=2?'RISING':'STARTER'}

    async function refreshVibeCreatorGrowthV150N(creatorUserId){
      const creator=String(creatorUserId);
      const sales=(await pool.query(`SELECT COUNT(DISTINCT order_id)::int AS orders,COALESCE(SUM(net_revenue),0)::numeric AS revenue FROM vibe_order_attribution
        WHERE creator_user_id=$1 AND attribution_status IN ('CONVERTED','PARTIALLY_REFUNDED')`,[creator])).rows[0];
      const vibes=(await pool.query(`SELECT COUNT(*)::int AS published FROM vibes WHERE creator_user_id=$1 AND status='PUBLISHED'`,[creator])).rows[0];
      const engagement=(await pool.query(`SELECT COUNT(*)::int AS events FROM vibe_commerce_events e JOIN vibes v ON v.id=e.vibe_id
        WHERE v.creator_user_id=$1 AND e.created_at>=NOW()-INTERVAL '30 days'`,[creator])).rows[0];
      const integrity=(await pool.query(`SELECT COUNT(*) FILTER(WHERE status IN ('OPEN','REVIEW'))::int AS open_cases FROM vibe_commerce_integrity_cases WHERE creator_user_id=$1`,[creator])).rows[0];
      const baseXp=Number(sales.orders||0)*80+Math.floor(Number(sales.revenue||0)/100)+Number(vibes.published||0)*25+Math.min(1500,Number(engagement.events||0));
      const integrityScore=Math.max(0,100-Number(integrity.open_cases||0)*10);
      const salesScore=Math.min(100,Number(sales.orders||0)*2+Number(sales.revenue||0)/5000);
      const qualityScore=Math.min(100,Number(vibes.published||0)*2.5);
      const engagementScore=Math.min(100,Number(engagement.events||0)/20);
      const profile=(await pool.query(`INSERT INTO vibe_creator_growth_profiles(creator_user_id,xp,level,creator_score,sales_score,quality_score,engagement_score,integrity_score,reward_tier)
        VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)
        ON CONFLICT(creator_user_id) DO UPDATE SET xp=EXCLUDED.xp,level=EXCLUDED.level,creator_score=EXCLUDED.creator_score,sales_score=EXCLUDED.sales_score,
          quality_score=EXCLUDED.quality_score,engagement_score=EXCLUDED.engagement_score,integrity_score=EXCLUDED.integrity_score,reward_tier=EXCLUDED.reward_tier,updated_at=NOW()
        RETURNING *`,[creator,baseXp,vibeCreatorLevelV150N(baseXp),Math.round((salesScore*.35+qualityScore*.2+engagementScore*.25+integrityScore*.2)*100)/100,
          salesScore,qualityScore,engagementScore,integrityScore,vibeCreatorTierV150N(vibeCreatorLevelV150N(baseXp))])).rows[0];

      const achievements=(await pool.query(`SELECT * FROM vibe_creator_achievements WHERE active=TRUE`)).rows;
      for(const a of achievements){
        let value=0;
        if(a.achievement_type==='SALES')value=Number(sales.orders||0);
        else if(a.achievement_type==='REVENUE')value=Number(sales.revenue||0);
        else if(a.achievement_type==='PUBLISH')value=Number(vibes.published||0);
        else if(a.achievement_type==='STREAK')value=Number(profile.current_streak||0);
        if(value>=Number(a.threshold||0)){
          const ins=await pool.query(`INSERT INTO vibe_creator_achievement_unlocks(creator_user_id,achievement_id,source_value) VALUES($1,$2,$3)
            ON CONFLICT DO NOTHING RETURNING achievement_id`,[creator,a.id,value]);
          if(ins.rowCount)await pool.query(`INSERT INTO vibe_creator_growth_events(creator_user_id,event_type,xp_delta,source_type,source_id,dedupe_key)
            VALUES($1,'ACHIEVEMENT_UNLOCKED',$2,'ACHIEVEMENT',$3,$4) ON CONFLICT(dedupe_key) DO NOTHING`,
            [creator,a.xp_reward,String(a.id),`achievement:${creator}:${a.id}`]);
        }
      }
      return profile;
    }


