    async function getEligibleVibeCampaignsV150O(creatorUserId){
      const profile=await refreshVibeCreatorGrowthV150N(creatorUserId);
      const rows=(await pool.query(`
        SELECT c.*,
          (SELECT COUNT(*) FROM vibe_brand_campaign_products cp WHERE cp.campaign_id=c.id)::int AS product_count,
          a.status AS application_status,a.id AS application_id
        FROM vibe_brand_campaigns c
        LEFT JOIN vibe_brand_campaign_applications a ON a.campaign_id=c.id AND a.creator_user_id=$1
        WHERE c.status='ACTIVE'
          AND (c.starts_at IS NULL OR c.starts_at<=NOW()) AND (c.ends_at IS NULL OR c.ends_at>=NOW())
          AND (c.application_deadline IS NULL OR c.application_deadline>=NOW())
          AND c.min_creator_level<=$2 AND c.min_creator_score<=$3 AND c.min_integrity_score<=$4
        ORDER BY c.created_at DESC LIMIT 100
      `,[String(creatorUserId),Number(profile.level||1),Number(profile.creator_score||0),Number(profile.integrity_score||0)])).rows;
      return {profile,campaigns:rows};
    }


