    async function buildVibeCampaignPerformanceV150P(campaignId,days=30){
      const d=Math.max(1,Math.min(365,Number(days||30)));
      const campaign=(await pool.query(`SELECT * FROM vibe_brand_campaigns WHERE id=$1`,[campaignId])).rows[0];
      if(!campaign)return null;
      const vibes=(await pool.query(`SELECT DISTINCT vibe_id,creator_user_id FROM vibe_brand_campaign_deliverables WHERE campaign_id=$1 AND vibe_id IS NOT NULL AND status='APPROVED'`,[campaignId])).rows;
      const vibeIds=vibes.map(x=>x.vibe_id);
      let funnel={impressions:0,views:0,qualified_views:0,watch_ms:0,completions:0,product_opens:0,wishlists:0,carts:0,checkouts:0};
      if(vibeIds.length){
        const q=(await pool.query(`SELECT
          COUNT(*) FILTER(WHERE event_type='impression')::int impressions,
          COUNT(*) FILTER(WHERE event_type IN ('view','open'))::int views,
          COUNT(*) FILTER(WHERE event_type='qualified_view')::int qualified_views,
          COALESCE(SUM(CASE WHEN event_type IN ('watch','watch_progress') THEN COALESCE((metadata->>'watch_ms')::bigint,0) ELSE 0 END),0)::bigint watch_ms,
          COUNT(*) FILTER(WHERE event_type='complete')::int completions,
          COUNT(*) FILTER(WHERE event_type='open')::int product_opens,
          COUNT(*) FILTER(WHERE event_type='wishlist')::int wishlists,
          COUNT(*) FILTER(WHERE event_type='add_to_cart')::int carts,
          COUNT(*) FILTER(WHERE event_type='checkout')::int checkouts
          FROM vibe_commerce_events WHERE vibe_id=ANY($1::uuid[]) AND created_at>=NOW()-($2||' days')::interval`,[vibeIds,String(d)])).rows[0];
        funnel={...funnel,...q};
      }
      const revenue=(await pool.query(`SELECT COUNT(DISTINCT a.order_id)::int orders,COALESCE(SUM(a.quantity),0)::bigint units,
        COALESCE(SUM(a.gross_revenue),0)::numeric gross_revenue,COALESCE(SUM(a.net_revenue),0)::numeric net_revenue,
        COALESCE(SUM(a.refunded_amount),0)::numeric refunds
        FROM vibe_order_attribution a WHERE a.vibe_id=ANY($1::uuid[]) AND a.attributed_at>=NOW()-($2||' days')::interval`,[vibeIds.length?vibeIds:['00000000-0000-0000-0000-000000000000'],String(d)])).rows[0];
      const costs=(await pool.query(`SELECT COALESCE(SUM(e.net_commission),0)::numeric creator_cost FROM vibe_creator_earnings_ledger e
        JOIN vibe_order_attribution a ON a.id=e.attribution_id WHERE a.vibe_id=ANY($1::uuid[]) AND e.created_at>=NOW()-($2||' days')::interval`,
        [vibeIds.length?vibeIds:['00000000-0000-0000-0000-000000000000'],String(d)])).rows[0];
      const spend=Number(costs.creator_cost||0),gross=Number(revenue.gross_revenue||0),net=Number(revenue.net_revenue||0),refunds=Number(revenue.refunds||0);
      const impressions=Number(funnel.impressions||0),orders=Number(revenue.orders||0);
      return {campaign,funnel:{...funnel,orders,units:Number(revenue.units||0)},financials:{grossRevenue:gross,netRevenue:net,refunds,creatorCost:spend,
        roas:spend>0?net/spend:0,roiPercent:spend>0?((net-spend)/spend)*100:0,conversionRate:impressions>0?(orders/impressions)*100:0,
        refundRate:gross>0?(refunds/gross)*100:0},vibeIds};
    }


