    async function buildVibeCreatorAudienceV150Q(creatorUserId,days=30){
      const creator=String(creatorUserId),d=Math.max(7,Math.min(365,Number(days||30)));
      const vibeRows=(await pool.query(`SELECT id FROM vibes WHERE creator_user_id=$1 AND status='PUBLISHED'`,[creator])).rows;
      const vibeIds=vibeRows.map(x=>x.id);
      if(!vibeIds.length)return {summary:{uniqueViewers:0,newViewers:0,returningViewers:0,engagedViewers:0,buyers:0,orders:0,revenue:0,returningRate:0,buyerRate:0,fanStrength:0,commerceStrength:0},categories:[],products:[],relatedCreators:[],segments:[]};
      const audience=(await pool.query(`
        WITH ev AS (
          SELECT COALESCE(viewer_user_id::text,metadata->>'viewer_user_id',metadata->>'session_id') viewer_key,
            COUNT(*) events,COUNT(DISTINCT vibe_id) vibes_seen,
            COUNT(*) FILTER(WHERE event_type IN ('wishlist','add_to_cart','checkout','share_product')) engaged,
            MIN(created_at) first_seen,MAX(created_at) last_seen
          FROM vibe_commerce_events WHERE vibe_id=ANY($1::uuid[]) AND created_at>=NOW()-($2||' days')::interval
          GROUP BY 1
        )
        SELECT COUNT(*) FILTER(WHERE viewer_key IS NOT NULL)::int unique_viewers,
          COUNT(*) FILTER(WHERE first_seen>=NOW()-INTERVAL '7 days')::int new_viewers,
          COUNT(*) FILTER(WHERE events>=2 OR vibes_seen>=2)::int returning_viewers,
          COUNT(*) FILTER(WHERE engaged>0)::int engaged_viewers FROM ev
      `,[vibeIds,String(d)])).rows[0];
      const commerce=(await pool.query(`SELECT COUNT(DISTINCT customer_user_id)::int buyers,COUNT(DISTINCT order_id)::int orders,
        COALESCE(SUM(net_revenue),0)::numeric revenue FROM vibe_order_attribution WHERE creator_user_id=$1 AND attributed_at>=NOW()-($2||' days')::interval
        AND attribution_status IN ('CONVERTED','PARTIALLY_REFUNDED')`,[creator,String(d)])).rows[0];
      const categories=(await pool.query(`SELECT COALESCE(p.category,'Other') affinity_key,COUNT(DISTINCT a.customer_user_id)::int buyers,
        COUNT(DISTINCT a.order_id)::int orders,COALESCE(SUM(a.net_revenue),0)::numeric revenue
        FROM vibe_order_attribution a LEFT JOIN vendor_products p ON p.id::text=a.product_id
        WHERE a.creator_user_id=$1 AND a.attributed_at>=NOW()-($2||' days')::interval GROUP BY p.category ORDER BY revenue DESC LIMIT 12`,[creator,String(d)])).rows;
      const products=(await pool.query(`SELECT a.product_id,COALESCE(p.name,'Product') product_name,COUNT(DISTINCT a.customer_user_id)::int buyers,
        COUNT(DISTINCT a.order_id)::int orders,COALESCE(SUM(a.net_revenue),0)::numeric revenue
        FROM vibe_order_attribution a LEFT JOIN vendor_products p ON p.id::text=a.product_id
        WHERE a.creator_user_id=$1 AND a.attributed_at>=NOW()-($2||' days')::interval GROUP BY a.product_id,p.name ORDER BY revenue DESC LIMIT 12`,[creator,String(d)])).rows;
      const u=Number(audience.unique_viewers||0),ret=Number(audience.returning_viewers||0),eng=Number(audience.engaged_viewers||0),buyers=Number(commerce.buyers||0);
      const returningRate=u?ret/u*100:0,buyerRate=u?buyers/u*100:0,engagementRate=u?eng/u*100:0;
      const fanStrength=Math.min(100,returningRate*.55+engagementRate*.45),commerceStrength=Math.min(100,buyerRate*5+Math.min(50,Number(commerce.orders||0)));
      const segments=[
        {code:'LOYAL_VIEWERS',name:'Loyal viewers',type:'LOYALTY',size:ret,strength:returningRate},
        {code:'ENGAGED_FANS',name:'Engaged fans',type:'ENGAGEMENT',size:eng,strength:engagementRate},
        {code:'VIBE_BUYERS',name:'Vibe buyers',type:'COMMERCE',size:buyers,strength:buyerRate},
        {code:'NEW_DISCOVERY',name:'New discovery audience',type:'DISCOVERY',size:Number(audience.new_viewers||0),strength:u?Number(audience.new_viewers||0)/u*100:0}
      ];
      for(const s of segments)await pool.query(`INSERT INTO vibe_creator_audience_segments(creator_user_id,segment_code,segment_name,segment_type,estimated_size,strength_score,description)
        VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(creator_user_id,segment_code) DO UPDATE SET estimated_size=EXCLUDED.estimated_size,strength_score=EXCLUDED.strength_score,updated_at=NOW()`,
        [creator,s.code,s.name,s.type,s.size,s.strength,`${s.name} calculated from privacy-safe aggregate Vibe activity.`]);
      const related=(await pool.query(`
        SELECT a2.creator_user_id related_creator_user_id,COALESCE(cp.display_name,cp.public_username,'HOWDI Creator') creator_name,
          COUNT(DISTINCT a1.customer_user_id)::int shared_buyers
        FROM vibe_order_attribution a1 JOIN vibe_order_attribution a2 ON a2.customer_user_id=a1.customer_user_id AND a2.creator_user_id<>a1.creator_user_id
        LEFT JOIN vibe_creator_profiles cp ON cp.user_id=a2.creator_user_id
        WHERE a1.creator_user_id=$1 AND a1.attributed_at>=NOW()-($2||' days')::interval
        GROUP BY a2.creator_user_id,cp.display_name,cp.public_username ORDER BY shared_buyers DESC LIMIT 12
      `,[creator,String(d)])).rows;
      return {summary:{uniqueViewers:u,newViewers:Number(audience.new_viewers||0),returningViewers:ret,engagedViewers:eng,buyers,orders:Number(commerce.orders||0),
        revenue:Number(commerce.revenue||0),returningRate,buyerRate,engagementRate,fanStrength,commerceStrength},categories,products,relatedCreators:related,segments};
    }


