    async function vibeClubEntitlementV150T(memberUserId,creatorUserId,minimumTierRank=1,requiredPlanId=null){
      const q=(await pool.query(`SELECT m.*,p.tier_rank,p.name plan_name,p.badge_label FROM vibe_creator_memberships m
        JOIN vibe_creator_membership_plans p ON p.id=m.plan_id
        WHERE m.member_user_id=$1 AND m.creator_user_id=$2 AND m.status='ACTIVE'
          AND (m.expires_at IS NULL OR m.expires_at>NOW()) AND p.active=TRUE
          AND p.tier_rank>=$3 AND ($4::uuid IS NULL OR p.id=$4::uuid)
        ORDER BY p.tier_rank DESC LIMIT 1`,[String(memberUserId),String(creatorUserId),Math.max(1,Number(minimumTierRank||1)),requiredPlanId||null])).rows[0];
      return q||null;
    }


