    async function canAccessVibeLiveV150U(userId,room){
      if(room.visibility==='PUBLIC')return {allowed:true,reason:'PUBLIC'};
      if(room.visibility==='MEMBERS_ONLY'){
        const ent=await vibeClubEntitlementV150T(userId,room.creator_user_id,room.minimum_tier_rank,room.required_plan_id);
        return {allowed:!!ent,reason:ent?'MEMBERSHIP':'MEMBERSHIP_REQUIRED',membership:ent||null};
      }
      return {allowed:false,reason:'INVITE_REQUIRED'};
    }


