    async function buildVibeLivePerformanceV150V(roomId){
      const room=(await pool.query(`SELECT * FROM vibe_live_rooms WHERE id=$1`,[roomId])).rows[0];if(!room)return null;
      const ev=(await pool.query(`SELECT COUNT(*) FILTER(WHERE interaction_type='PRODUCT_OPEN')::int product_opens,
        COUNT(*) FILTER(WHERE interaction_type='ADD_TO_CART')::int carts FROM vibe_live_interactions WHERE room_id=$1`,[roomId])).rows[0];
      const rsvps=Number((await pool.query(`SELECT COUNT(*)::int n FROM vibe_live_rsvps WHERE room_id=$1 AND status='GOING'`,[roomId])).rows[0].n||0);
      const checkouts=Number((await pool.query(`SELECT COUNT(*)::int n FROM vibe_live_cart_sessions WHERE room_id=$1 AND checkout_started_at IS NOT NULL`,[roomId])).rows[0].n||0);
      const sales=(await pool.query(`SELECT COUNT(DISTINCT customer_user_id)::int buyers,COUNT(DISTINCT order_id)::int orders,
        COALESCE(SUM(quantity),0)::bigint units,COALESCE(SUM(gross_revenue),0)::numeric gross,COALESCE(SUM(net_revenue),0)::numeric net,
        COALESCE(SUM(refunded_amount),0)::numeric refunds FROM vibe_live_order_attribution WHERE room_id=$1 AND status IN ('CONVERTED','PARTIALLY_REFUNDED','REFUNDED')`,[roomId])).rows[0];
      const viewers=Number(room.peak_viewers||room.viewer_count||0),buyers=Number(sales.buyers||0),net=Number(sales.net||0);
      return {room,viewers,peakViewers:Number(room.peak_viewers||0),rsvps,productOpens:Number(ev.product_opens||0),carts:Number(ev.carts||0),
        checkoutStarts:checkouts,buyers,orders:Number(sales.orders||0),units:Number(sales.units||0),grossRevenue:Number(sales.gross||0),
        netRevenue:net,refunds:Number(sales.refunds||0),conversionRate:viewers?buyers/viewers*100:0,revenuePerViewer:viewers?net/viewers:0};
    }


