    async function deliverVibeCreatorMessageV150W(messageId){
      const m=(await pool.query(`SELECT * FROM vibe_creator_messages WHERE id=$1`,[messageId])).rows[0];if(!m)return null;
      let recipients=[];
      if(m.audience_type==='MEMBERS'){
        recipients=(await pool.query(`SELECT DISTINCT member_user_id user_id FROM vibe_creator_memberships WHERE creator_user_id=$1 AND status='ACTIVE'`,[m.creator_user_id])).rows;
      }else if(m.audience_type==='PLAN_MEMBERS' && m.required_plan_id){
        recipients=(await pool.query(`SELECT DISTINCT member_user_id user_id FROM vibe_creator_memberships WHERE creator_user_id=$1 AND plan_id=$2 AND status='ACTIVE'`,[m.creator_user_id,m.required_plan_id])).rows;
      }else{
        recipients=(await pool.query(`SELECT DISTINCT fan_user_id user_id FROM vibe_fan_creator_affinity WHERE creator_user_id=$1 AND affinity_score>=15`,[m.creator_user_id])).rows;
      }
      let delivered=0;
      for(const r of recipients){
        const pref=(await pool.query(`SELECT * FROM vibe_creator_message_preferences WHERE user_id=$1 AND creator_user_id=$2`,[String(r.user_id),m.creator_user_id])).rows[0];
        if(pref?.quiet_mode)continue;
        const type=String(m.message_type||'ANNOUNCEMENT').toUpperCase();
        if((type==='LIVE_REMINDER'&&pref?.live_reminders===false)||(type==='DROP_ALERT'&&pref?.drop_alerts===false)||(type==='OFFER'&&pref?.offers===false)||(type==='MEMBERSHIP'&&pref?.membership_updates===false)||(type==='ANNOUNCEMENT'&&pref?.announcements===false))continue;
        const q=await pool.query(`INSERT INTO vibe_creator_message_deliveries(message_id,recipient_user_id) VALUES($1,$2) ON CONFLICT DO NOTHING RETURNING message_id`,[m.id,String(r.user_id)]);
        if(q.rowCount){delivered++;await pool.query(`INSERT INTO vibe_creator_inbox_threads(user_id,creator_user_id,last_message_id,last_message_at,unread_count)
          VALUES($1,$2,$3,NOW(),1) ON CONFLICT(user_id,creator_user_id,thread_type) DO UPDATE SET last_message_id=EXCLUDED.last_message_id,last_message_at=NOW(),
          unread_count=vibe_creator_inbox_threads.unread_count+1,updated_at=NOW()`,[String(r.user_id),m.creator_user_id,m.id]);}
      }
      await pool.query(`UPDATE vibe_creator_messages SET status='SENT',sent_at=COALESCE(sent_at,NOW()),updated_at=NOW() WHERE id=$1`,[m.id]);
      return {message:m,delivered};
    }


