    async function canAccessVibeCommunityV150X(userId,community){
      if(community.visibility==='PUBLIC')return {allowed:true,reason:'PUBLIC'};
      const member=(await pool.query(`SELECT * FROM vibe_creator_community_members WHERE community_id=$1 AND user_id=$2 AND status='ACTIVE'`,
        [community.id,String(userId)])).rows[0];
      if(member)return {allowed:true,reason:'COMMUNITY_MEMBER',member};
      if(community.visibility==='MEMBERS_ONLY'){
        const ent=await vibeClubEntitlementV150T(userId,community.creator_user_id,community.minimum_tier_rank,community.required_plan_id);
        return {allowed:!!ent,reason:ent?'CREATOR_MEMBERSHIP':'MEMBERSHIP_REQUIRED',membership:ent||null};
      }
      return {allowed:false,reason:'PRIVATE'};
    }


