    async function awardVibeCommunityReputationV150Y(communityId,userId,eventType,points,sourceType=null,sourceId=null,dedupeKey=null){
      const ev=await pool.query(`INSERT INTO vibe_community_reputation_events(community_id,user_id,event_type,points_delta,source_type,source_id,dedupe_key)
        VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(dedupe_key) DO NOTHING RETURNING id`,[communityId,String(userId),eventType,Number(points||0),sourceType,sourceId,dedupeKey]);
      if(!ev.rowCount)return null;
      const q=(await pool.query(`INSERT INTO vibe_community_reputation(community_id,user_id,reputation_score,contribution_points,last_contribution_date)
        VALUES($1,$2,GREATEST(0,$3),GREATEST(0,$3),CURRENT_DATE)
        ON CONFLICT(community_id,user_id) DO UPDATE SET reputation_score=GREATEST(0,vibe_community_reputation.reputation_score+$3),
        contribution_points=GREATEST(0,vibe_community_reputation.contribution_points+$3),
        streak_days=CASE WHEN vibe_community_reputation.last_contribution_date=CURRENT_DATE-1 THEN vibe_community_reputation.streak_days+1
          WHEN vibe_community_reputation.last_contribution_date=CURRENT_DATE THEN vibe_community_reputation.streak_days ELSE 1 END,
        last_contribution_date=CURRENT_DATE,updated_at=NOW() RETURNING *`,[communityId,String(userId),Number(points||0)])).rows[0];
      const trust=Math.max(1,Math.min(5,1+Math.floor(Number(q.reputation_score||0)/100)));
      await pool.query(`UPDATE vibe_community_reputation SET trust_level=$3,quality_score=LEAST(100,GREATEST(0,(reputation_score*0.5)+(helpful_votes*5)-(reports_upheld*10))),updated_at=NOW()
        WHERE community_id=$1 AND user_id=$2`,[communityId,String(userId),trust]);
      return q;
    }


