    async function buildVibeCommunityDiscoveryV150Z(userId,limit=30){
      const pref=(await pool.query(`SELECT * FROM vibe_discovery_preferences WHERE user_id=$1`,[String(userId)])).rows[0];
      const personalized=pref?.personalized_discovery!==false && pref?.community_recommendations!==false;
      const rows=(await pool.query(`
        WITH my_topics AS (
          SELECT topic_id,SUM(signal_weight*LEAST(10,occurrences)) score
          FROM vibe_user_interest_signals WHERE user_id=$1 GROUP BY topic_id
        ), joined AS (
          SELECT community_id FROM vibe_creator_community_members WHERE user_id=$1 AND status='ACTIVE'
        )
        SELECT c.id,c.community_code,c.name,c.description,c.visibility,c.member_count,c.creator_user_id,
          COALESCE(cp.display_name,cp.public_username,'HOWDI Creator') creator_name,cp.public_username,
          COALESCE(SUM(CASE WHEN $3 THEN COALESCE(mt.score,0)*cit.weight ELSE 0 END),0)::numeric interest_score,
          COALESCE(r.avg_rep,0)::numeric community_quality,
          CASE WHEN j.community_id IS NOT NULL THEN TRUE ELSE FALSE END already_joined
        FROM vibe_creator_communities c
        LEFT JOIN vibe_creator_profiles cp ON cp.user_id=c.creator_user_id
        LEFT JOIN vibe_community_interest_topics cit ON cit.community_id=c.id
        LEFT JOIN my_topics mt ON mt.topic_id=cit.topic_id
        LEFT JOIN joined j ON j.community_id=c.id
        LEFT JOIN (SELECT community_id,AVG(quality_score) avg_rep FROM vibe_community_reputation GROUP BY community_id) r ON r.community_id=c.id
        WHERE c.status='ACTIVE'
        GROUP BY c.id,cp.display_name,cp.public_username,r.avg_rep,j.community_id
        ORDER BY already_joined ASC,interest_score DESC,community_quality DESC,c.member_count DESC,c.created_at DESC
        LIMIT $2`,[String(userId),Math.max(1,Math.min(100,Number(limit||30))),personalized])).rows;
      return rows.map((x,i)=>({...x,discovery_score:Number(x.interest_score||0)+Math.min(20,Number(x.community_quality||0)/5)+Math.min(10,Math.log10(Number(x.member_count||0)+1)*3),
        reason_codes:Number(x.interest_score||0)>0?['MATCHES_INTERESTS','COMMUNITY_QUALITY']:['POPULAR_COMMUNITY','EXPLORE_NEW']}));
    }


