    function vibeAdminAuthorizedV151(req){
      const supplied=String(req.headers['x-howdi-admin-token']||'');
      const configured=String(process.env.HOWDI_ADMIN_TOKEN||process.env.ADMIN_TOKEN||'');
      if(!configured||supplied.length!==configured.length)return false;
      try{return require('crypto').timingSafeEqual(Buffer.from(supplied),Buffer.from(configured));}catch{return false;}
    }
    async function vibeHealthAuditV151(){
      const checks=[]; const push=(name,ok,detail='')=>checks.push({name,ok:!!ok,detail});
      try{
        const q=(await pool.query(`SELECT to_regclass('public.vibes') vibes,to_regclass('public.vibe_creator_profiles') creator_profiles,
          to_regclass('public.vendor_products') vendor_products,to_regclass('public.orders') orders,
          to_regclass('public.order_items') order_items,to_regclass('public.payment_transactions') payment_transactions,
          to_regclass('public.payment_refunds') payment_refunds`)).rows[0]||{};
        Object.entries(q).forEach(([k,v])=>push(`table:${k}`,!!v,v?'available':'missing'));
      }catch(e){push('database:catalog',false,e.message)}
      push('security:admin_token_configured',!!String(process.env.HOWDI_ADMIN_TOKEN||process.env.ADMIN_TOKEN||''),'configured token required');
      return {ok:checks.every(x=>x.ok),checks,checked_at:new Date().toISOString(),version:'V15.1'};
    }


    /* =========================================================
       HOWDI V15.1B — SECURITY + OWNERSHIP + SCHEMA HARDENING
       ========================================================= */
    const vibeV151BRateBuckets=new Map();
    function vibeRateLimitV151B(key,limit=60,windowMs=60000){
      const now=Date.now(),k=String(key||'anonymous'),old=vibeV151BRateBuckets.get(k);
      if(!old||now-old.startedAt>=windowMs){vibeV151BRateBuckets.set(k,{startedAt:now,count:1});return {allowed:true,remaining:limit-1};}
      old.count++;return {allowed:old.count<=limit,remaining:Math.max(0,limit-old.count),retryAfterMs:Math.max(0,windowMs-(now-old.startedAt))};
    }
    function vibeSafePublicUsernameV151B(v){return String(v||'').replace(/^@/,'').replace(/[^a-zA-Z0-9._-]/g,'').slice(0,40);}
    function vibeSafeEnumV151B(v,allowed,fallback){const x=String(v||fallback).toUpperCase();return allowed.includes(x)?x:fallback;}
    function vibeSafeTextV151B(v,max=1000){return String(v||'').trim().slice(0,max);}
    async function vibeCreatorContextV151B(req){
      const viewer=await getVibeViewer(req);if(!viewer)return null;
      let profile=null;
      try{profile=(await pool.query(`SELECT * FROM vibe_creator_profiles WHERE user_id=$1 LIMIT 1`,[String(viewer.id)])).rows[0]||null;}catch{}
      return {viewer,profile,creatorUserId:String(viewer.id),publicUsername:vibeSafePublicUsernameV151B(profile?.public_username)};
    }
    async function vibeRequireCreatorOwnershipV151B(req,res,ownerUserId){
      const ctx=await vibeCreatorContextV151B(req);
      if(!ctx){sendJSON(res,401,{status:'error',message:'Sign in required.'});return null;}
      if(String(ctx.creatorUserId)!==String(ownerUserId)){sendJSON(res,403,{status:'error',message:'Creator ownership required.'});return null;}
      return ctx;
    }
