      const m=await vibeCommunityMemberV151B(communityId,userId);
      if(!m||m.status!=='ACTIVE')return {allowed:false,reason:'MEMBERSHIP_REQUIRED'};
      if(m.muted_until&&new Date(m.muted_until)>new Date())return {allowed:false,reason:'MEMBER_MUTED'};
