    async function vibeSchemaCompatibilityV151B(){
      const required={
        vibes:['id'],vibe_creator_profiles:['user_id','public_username'],vibe_creator_memberships:['creator_user_id','status'],
        vendor_products:['id','vendor_profile_id','status'],orders:['id','user_id','status','payment_status'],
        order_items:['order_id','product_id','vendor_profile_id'],payment_transactions:['order_id','status','amount'],
        payment_refunds:['order_id','status','amount']
      },results=[];
      for(const [table,cols] of Object.entries(required)){
        try{
          const rows=(await pool.query(`SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=$1`,[table])).rows;
          const got=new Set(rows.map(x=>x.column_name)),missing=cols.filter(x=>!got.has(x));
          results.push({table,exists:rows.length>0,required_columns:cols,missing_columns:missing,compatible:rows.length>0&&missing.length===0});
        }catch(e){results.push({table,exists:false,required_columns:cols,missing_columns:cols,compatible:false,error:e.message});}
      }
      return results;
    }
