    async function vibeRouteGuardV151C(req,res,opts={}){
      const viewer=await getVibeViewer(req);
      if(opts.auth!==false&&!viewer){sendJSON(res,401,{status:'error',message:'Sign in required.'});return null;}
      if(viewer){
        const rate=vibeRateLimitV151B(`${opts.scope||'vibe'}:${viewer.id}`,opts.limit||90,opts.windowMs||60000);
        if(!rate.allowed){await vibeSecurityEventV151C(viewer.id,'RATE_LIMIT','WARN',opts.entityType,opts.entityId,'RATE_LIMIT');
          sendJSON(res,429,{status:'error',message:'Too many requests.',retry_after_ms:rate.retryAfterMs});return null;}
      }
      if(opts.targetUserId&&viewer&&await vibeBlockedEitherWayV151C(viewer.id,opts.targetUserId)){
        sendJSON(res,403,{status:'error',message:'This interaction is unavailable.'});return null;
      }
      if(opts.creatorUserId&&opts.policy&&!await vibeCreatorPolicyAllowsV151C(opts.creatorUserId,opts.policy)){
        sendJSON(res,403,{status:'error',message:'This creator feature is currently unavailable.'});return null;
      }
      if(opts.entityType&&opts.entityId&&!await vibeContentAllowedV151C(opts.entityType,opts.entityId)){
        sendJSON(res,403,{status:'error',message:'Content is unavailable.'});return null;
      }
      return {viewer};
    }
