    async function vibeAuthoritativeOrderV151D(orderId){
      const order=(await pool.query(`SELECT id,order_number,user_id,status,payment_status,grand_total,currency,cancelled_at,delivered_at FROM orders WHERE id=$1 LIMIT 1`,[orderId])).rows[0];
      if(!order)return null;
      const payments=(await pool.query(`SELECT id,status,amount,currency,paid_at,failed_at,refunded_at FROM payment_transactions WHERE order_id=$1 ORDER BY created_at`,[orderId])).rows;
      const refunds=(await pool.query(`SELECT id,status,amount,currency,reason,created_at FROM payment_refunds WHERE order_id=$1 ORDER BY created_at`,[orderId])).rows;
      const paid=payments.filter(x=>String(x.status).toUpperCase()==='PAID').reduce((a,x)=>a+Number(x.amount||0),0);
      const refunded=refunds.filter(x=>['PROCESSED','REFUNDED','SUCCESS'].includes(String(x.status).toUpperCase())).reduce((a,x)=>a+Number(x.amount||0),0);
      return {order,payments,refunds,paid_amount:paid,refunded_amount:refunded,net_paid:Math.max(0,paid-refunded)};
    }
