    async function vibeRefreshCreatorBalanceV151E(creatorUserId,currency='INR'){
      const cur=vibeCurrencyV151D(currency)||'INR';
      const q=(await pool.query(`SELECT
        COALESCE(SUM(CASE WHEN entry_type='EARNING' AND status='POSTED' THEN amount ELSE 0 END),0)::numeric earned,
        COALESCE(SUM(CASE WHEN entry_type IN('REVERSAL','CLAWBACK') AND status='POSTED' THEN amount ELSE 0 END),0)::numeric reversed
        FROM vibe_creator_finance_ledger WHERE creator_user_id=$1 AND currency=$2`,[String(creatorUserId),cur])).rows[0];
      const r=(await pool.query(`SELECT COALESCE(SUM(amount),0)::numeric reserved FROM vibe_payout_reservations WHERE creator_user_id=$1 AND currency=$2 AND status='RESERVED'`,
        [String(creatorUserId),cur])).rows[0];
      const paid=(await pool.query(`SELECT COALESCE(SUM(amount),0)::numeric paid FROM vibe_payout_reservations WHERE creator_user_id=$1 AND currency=$2 AND status='PAID'`,
        [String(creatorUserId),cur])).rows[0];
      return (await pool.query(`INSERT INTO vibe_creator_finance_balances(creator_user_id,currency,earned,reversed,reserved,paid)
        VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT(creator_user_id,currency) DO UPDATE SET earned=EXCLUDED.earned,reversed=EXCLUDED.reversed,
        reserved=EXCLUDED.reserved,paid=EXCLUDED.paid,updated_at=NOW() RETURNING *`,
        [String(creatorUserId),cur,q.earned||0,q.reversed||0,r.reserved||0,paid.paid||0])).rows[0];
    }
