    async function vibeProductIntegrityV151G(productId,quantity=1){
      try{
        const p=(await pool.query(`SELECT id,vendor_profile_id,name,sku,price,stock,status,currency,variant_options,campaign_permission
          FROM vendor_products WHERE id::text=$1 LIMIT 1`,[String(productId)])).rows[0];
        if(!p)return {ok:false,reason:'PRODUCT_NOT_FOUND'};
        if(String(p.status||'').toUpperCase()!=='ACTIVE'&&String(p.status||'').toUpperCase()!=='PUBLISHED')return {ok:false,reason:'PRODUCT_NOT_ACTIVE'};
        if(Number(p.stock||0)<Number(quantity||1))return {ok:false,reason:'INSUFFICIENT_STOCK',available:Number(p.stock||0)};
        const price=vibeMoneyV151D(p.price);if(price===null)return {ok:false,reason:'INVALID_PRICE'};
        return {ok:true,product:p,unit_price:price,currency:vibeCurrencyV151D(p.currency||'INR')||'INR'};
      }catch(e){
        /* Compatibility fallback: older vendor_products may not yet have currency/campaign_permission columns. */
        try{
          const p=(await pool.query(`SELECT id,vendor_profile_id,name,sku,price,stock,status,variant_options FROM vendor_products WHERE id::text=$1 LIMIT 1`,[String(productId)])).rows[0];
          if(!p)return {ok:false,reason:'PRODUCT_NOT_FOUND'};
          if(!['ACTIVE','PUBLISHED'].includes(String(p.status||'').toUpperCase()))return {ok:false,reason:'PRODUCT_NOT_ACTIVE'};
          if(Number(p.stock||0)<Number(quantity||1))return {ok:false,reason:'INSUFFICIENT_STOCK',available:Number(p.stock||0)};
          const price=vibeMoneyV151D(p.price);if(price===null)return {ok:false,reason:'INVALID_PRICE'};
          return {ok:true,product:p,unit_price:price,currency:'INR'};
        }catch{return {ok:false,reason:'PRODUCT_SCHEMA_INCOMPATIBLE'};}
      }
    }
