    function vibePaymentTransitionAllowedV151K(from,to){
      const f=String(from||'PENDING').toUpperCase(),t=String(to||'').toUpperCase();
      const map={PENDING:['PAID','FAILED','CANCELLED'],INITIATED:['PAID','FAILED','CANCELLED'],PAID:['PARTIALLY_REFUNDED','REFUNDED'],PARTIALLY_REFUNDED:['REFUNDED'],FAILED:[],REFUNDED:[],CANCELLED:[]};
      return f===t || (map[f]||[]).includes(t);
    }


