async function vibeCreatorCommerceSummaryV152F(creatorUserId,days=30){
  const safeDays=Math.max(1,Math.min(365,Number(days)||30)),creator=String(creatorUserId);
  const attribution=(await pool.query(`SELECT
    COUNT(DISTINCT order_id)::int orders,
    COUNT(DISTINCT order_id) FILTER(WHERE attribution_status='CONVERTED')::int converted_orders,
    COUNT(DISTINCT order_id) FILTER(WHERE attribution_status='PARTIALLY_REFUNDED')::int partially_refunded_orders,
    COUNT(DISTINCT order_id) FILTER(WHERE attribution_status='REFUNDED')::int refunded_orders,
    COUNT(DISTINCT order_id) FILTER(WHERE attribution_status='PAYMENT_FAILED')::int payment_failed_orders,
    COALESCE(SUM(net_revenue) FILTER(WHERE attribution_status IN ('CONVERTED','PARTIALLY_REFUNDED')),0)::numeric attributed_revenue
    FROM vibe_order_attribution WHERE creator_user_id::text=$1 AND created_at>=NOW()-($2::int*INTERVAL '1 day')`,[creator,safeDays])).rows[0];
  const earning=(await pool.query(`SELECT
    COALESCE(SUM(net_commission) FILTER(WHERE status IN ('APPROVED','PAID')),0)::numeric creator_revenue,
    COALESCE(SUM(net_commission) FILTER(WHERE status='REVERSED'),0)::numeric reversed_revenue
    FROM vibe_creator_earnings_ledger WHERE creator_user_id::text=$1 AND created_at>=NOW()-($2::int*INTERVAL '1 day')`,[creator,safeDays])).rows[0];
  return {period_days:safeDays,...attribution,...earning};
}


