  if(refundRate>=20&&orders>=3)return {type:'REFUND_RISK',priority:'HIGH',title:'Review before boosting',reason:`Refund rate is ${refundRate}% across ${orders} attributed orders.`,action:'Review product expectation, variant accuracy, quality and fulfillment before promoting this combination again.'};
  if(opens>=10&&openCart>=20&&carts>=5&&cartPaid<10)return {type:'HIGH_INTEREST_LOW_CONVERSION',priority:'HIGH',title:'Strong interest, weak paid conversion',reason:`${opens} product opens and ${carts} cart adds produced ${conv} paid conversions.`,action:'Improve product detail clarity, variant availability, delivery confidence and checkout friction before increasing reach.'};
  if(conv>=3&&cartPaid>=20&&refundRate<10)return {type:'HIGH_CONVERSION',priority:'MEDIUM',title:'High-converting content candidate',reason:`Cart-to-paid conversion is ${cartPaid}% with refund rate ${refundRate}%.`,action:'Consider featuring this product in similar future Vibes while preserving vendor campaign consent and current pricing.'};
  if(opens>=10&&openCart<10)return {type:'LOW_PRODUCT_INTENT',priority:'LOW',title:'Views are not becoming carts',reason:`Open-to-cart rate is ${openCart}%.`,action:'Test clearer product context, demonstration, benefits or creator storytelling rather than changing price automatically.'};
