async function setReturnDispositionV152V(client,{returnItemId,disposition,actor,note}){
  const d=String(disposition||'').toUpperCase();if(!['RESTOCK','QUARANTINE','DAMAGED','RETURN_TO_VENDOR'].includes(d))
    throw Object.assign(new Error('Invalid inventory disposition'),{statusCode:400});
  const ri=(await client.query(`SELECT ri.*,r.status return_status FROM order_return_items ri JOIN order_returns r ON r.id=ri.return_id WHERE ri.id=$1 FOR UPDATE OF ri`,[returnItemId])).rows[0];
  if(!ri)throw Object.assign(new Error('Return item not found'),{statusCode:404});
  if(String(ri.return_status).toUpperCase()!=='RECEIVED')throw Object.assign(new Error('Disposition requires RECEIVED return'),{statusCode:409});
  if(d==='RESTOCK'&&String(ri.qc_status||'').toUpperCase()!=='PASSED')throw Object.assign(new Error('Only QC-passed items can be restocked'),{statusCode:409});
  const updated=(await client.query(`UPDATE order_return_items SET inventory_disposition=$2 WHERE id=$1 RETURNING *`,[ri.id,d])).rows[0];
  await client.query(`INSERT INTO order_return_finance_events(return_id,return_item_id,event_type,actor,note) VALUES($1,$2,$3,$4,$5)`,
    [ri.return_id,ri.id,`DISPOSITION_${d}`,String(actor||'ADMIN'),String(note||'').slice(0,1000)]);
  return updated;
}
async function openReturnExceptionV152V(client,{returnItemId,refundId,type,details={}}){
  const ri=(await client.query(`SELECT * FROM order_return_items WHERE id=$1`,[returnItemId])).rows[0];if(!ri)return null;
  return (await client.query(`INSERT INTO return_finance_exceptions(return_id,return_item_id,payment_refund_id,exception_type,details)
    VALUES($1,$2,$3,$4,$5::jsonb) ON CONFLICT(return_item_id,payment_refund_id,exception_type) DO UPDATE SET details=EXCLUDED.details
    RETURNING *`,[ri.return_id,ri.id,refundId||null,String(type),JSON.stringify(details)])).rows[0];
}
async function syncReturnRefundExceptionV152V(client,refund){
  const state=String(refund.status||'').toUpperCase();if(!['FAILED','REJECTED'].includes(state))return 0;
  const items=(await client.query(`SELECT * FROM order_return_items WHERE payment_refund_id=$1 FOR UPDATE`,[refund.id])).rows;let n=0;
  for(const ri of items){
    await openReturnExceptionV152V(client,{returnItemId:ri.id,refundId:refund.id,type:`REFUND_${state}`,details:{refundStatus:state,amount:refund.amount}});
    await client.query(`UPDATE order_returns SET refund_status=$2,updated_at=NOW() WHERE id=$1`,[ri.return_id,state.toLowerCase()]);
    await client.query(`INSERT INTO order_return_finance_events(return_id,return_item_id,payment_refund_id,event_type,actor,note)
      VALUES($1,$2,$3,$4,'SYSTEM',$5)`,[ri.return_id,ri.id,refund.id,`REFUND_${state}`,`Refund entered ${state}; finance review required`]);n++;
  }return n;
}


/* HOWDI V15.2W — CUSTOMER RETURN STATUS + ELIGIBILITY + MY ORDERS READ MODEL */
async function ensureVibeCommerceV152WSchema(){
  await pool.query(`ALTER TABLE order_returns ADD COLUMN IF NOT EXISTS eligibility_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb`);
  console.log("✅ HOWDI V15.2W Customer Return Timeline + Eligibility Read Model ready");
}
function returnEligibilityV152W(){
  throw Object.assign(new Error('Legacy fixed return eligibility is retired; use returnEligibilityV153I'),{statusCode:500});
}
async function customerReturnReadModelV152W(client,{orderId,userId}){
  const order=(await client.query(`SELECT * FROM orders WHERE id=$1 AND user_id=$2`,[orderId,userId])).rows[0];if(!order)return null;
  const items=(await client.query(`SELECT id,product_id,product_name,quantity,fulfillment_status FROM order_items WHERE order_id=$1 ORDER BY created_at,id`,[order.id])).rows;
  const returns=(await client.query(`SELECT r.id,r.status,r.refund_status,r.created_at,r.received_at,r.updated_at,
    COALESCE(json_agg(json_build_object('id',ri.id,'order_item_id',ri.order_item_id,'quantity',ri.quantity,'qc_status',ri.qc_status,
    'refund_amount',ri.refund_amount,'refund_requested_at',ri.refund_requested_at,'refund_processed_at',ri.refund_processed_at))
    FILTER(WHERE ri.id IS NOT NULL),'[]'::json) items FROM order_returns r LEFT JOIN order_return_items ri ON ri.return_id=r.id
    WHERE r.order_id=$1 GROUP BY r.id ORDER BY r.created_at DESC`,[order.id])).rows;
  const timeline=[];
  for(const r of returns){timeline.push({type:'RETURN_REQUESTED',at:r.created_at});if(r.received_at)timeline.push({type:'RETURN_RECEIVED',at:r.received_at});
    for(const x of (r.items||[])){if(x.qc_status)timeline.push({type:`QC_${x.qc_status}`,at:r.updated_at||r.received_at});
      if(x.refund_requested_at)timeline.push({type:'REFUND_REQUESTED',at:x.refund_requested_at,amount:x.refund_amount});
      if(x.refund_processed_at)timeline.push({type:'REFUND_PROCESSED',at:x.refund_processed_at,amount:x.refund_amount});}}
  timeline.sort((a,b)=>new Date(a.at||0)-new Date(b.at||0));
  const eligibility=await returnEligibilityV153I(client,order,items);
  return {order:{id:order.id,order_number:order.order_number,status:order.status,payment_status:order.payment_status},
    coupon:await couponLifecycleSummaryV153L(client,order.id),
    eligibility,returns:returns.map(r=>({status:r.status,refund_status:r.refund_status,created_at:r.created_at,
      items:(r.items||[]).map(x=>({return_item_id:x.id,quantity:Number(x.quantity||0),qc_status:x.qc_status||null,refund_amount:Number(x.refund_amount||0)}))})),
    recovery:{retry_items:(await client.query(`SELECT ri.id return_item_id FROM order_return_items ri JOIN order_returns r ON r.id=ri.return_id
      JOIN payment_refunds pr ON pr.id=ri.payment_refund_id WHERE r.order_id=$1 AND ri.qc_status='PASSED' AND pr.status IN ('FAILED','REJECTED')`,[order.id])).rows},
    timeline:timeline.map(safeReturnTimelineEventV153I)};
}


