    async function vibeIntegrityScanV140L(runBy='system'){
      const started=Date.now(), findings=[];
      const checks=[
        ['published_without_media','critical',`SELECT v.id::text entity_id,'Published Vibe has no media' message FROM vibes v WHERE v.status='published' AND v.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM vibe_media m WHERE m.vibe_id=v.id) LIMIT 200`],
        ['orphan_media','high',`SELECT m.id::text entity_id,'Media row points to missing Vibe' message FROM vibe_media m LEFT JOIN vibes v ON v.id=m.vibe_id WHERE v.id IS NULL LIMIT 200`],
        ['orphan_category_map','medium',`SELECT m.vibe_id::text entity_id,'Category map points to missing Vibe/category' message FROM vibe_category_map m LEFT JOIN vibes v ON v.id=m.vibe_id LEFT JOIN vibe_categories c ON c.id=m.category_id WHERE v.id IS NULL OR c.id IS NULL LIMIT 200`],
        ['stats_without_vibe','medium',`SELECT s.vibe_id::text entity_id,'Stats row points to missing Vibe' message FROM vibe_stats s LEFT JOIN vibes v ON v.id=s.vibe_id WHERE v.id IS NULL LIMIT 200`],
        ['invalid_public_username','medium',`SELECT user_id entity_id,'Creator public username is invalid or missing' message FROM vibe_creator_profiles WHERE COALESCE(public_username,'') !~ '^[a-z0-9._]{3,30}$' LIMIT 200`],
        ['duplicate_public_username','high',`SELECT MIN(user_id) entity_id,'Duplicate public username: '||LOWER(public_username) message FROM vibe_creator_profiles WHERE public_username IS NOT NULL GROUP BY LOWER(public_username) HAVING COUNT(*)>1 LIMIT 200`],
        ['negative_stats','high',`SELECT vibe_id::text entity_id,'Vibe stats contain negative counters' message FROM vibe_stats WHERE impressions<0 OR plays<0 OR likes<0 OR saves<0 OR shares<0 OR comments<0 LIMIT 200`],
        ['stale_processing_vibe','medium',`SELECT id::text entity_id,'Vibe has remained in processing/draft state for over 24h' message FROM vibes WHERE status IN ('processing','uploading') AND updated_at < NOW()-INTERVAL '24 hours' LIMIT 200`]
      ];
      for(const [type,severity,sql] of checks){
        const q=await pool.query(sql).catch(()=>({rows:[]}));
        for(const r of q.rows){
          const key=`${type}:${r.entity_id||'global'}`; findings.push({key,type,severity,entityId:r.entity_id||null,message:r.message});
          await pool.query(`INSERT INTO vibe_integrity_findings(finding_key,severity,entity_type,entity_id,finding_type,message,last_seen_at,status) VALUES($1,$2,'vibe',$3,$4,$5,NOW(),'open') ON CONFLICT(finding_key) DO UPDATE SET severity=EXCLUDED.severity,message=EXCLUDED.message,last_seen_at=NOW(),status='open',resolved_at=NULL`,[key,severity,r.entity_id||null,type,r.message]).catch(()=>{});
        }
      }
      const liveKeys=findings.map(x=>x.key);
      if(liveKeys.length) await pool.query(`UPDATE vibe_integrity_findings SET status='resolved',resolved_at=NOW() WHERE status='open' AND finding_key <> ALL($1::text[])`,[liveKeys]).catch(()=>{});
      else await pool.query(`UPDATE vibe_integrity_findings SET status='resolved',resolved_at=NOW() WHERE status='open'`).catch(()=>{});
      const critical=findings.filter(x=>x.severity==='critical').length, high=findings.filter(x=>x.severity==='high').length;
      await pool.query(`INSERT INTO vibe_release_checks(check_group,check_name,status,details,duration_ms,run_by) VALUES('integrity','full_scan',$1,$2::jsonb,$3,$4)`,[(critical||high)?'attention':'pass',JSON.stringify({findings:findings.length,critical,high}),Date.now()-started,runBy]).catch(()=>{});
      return {findings,summary:{total:findings.length,critical,high,medium:findings.filter(x=>x.severity==='medium').length,durationMs:Date.now()-started}};
    }
