                const commissionValue=Math.max(0,Number(body.commission_value||0));
                const holdDays=Math.max(0,Math.min(365,Number(body.settlement_hold_days||0)));
                const gatewayPct=Math.max(0,Number(body.payment_gateway_fee_percent||0));
                const gatewayFlat=Math.max(0,Number(body.payment_gateway_fee_flat||0));
