              const totals=(await pool.query(`SELECT COALESCE(SUM(gross_amount),0)::numeric gross,COALESCE(SUM(platform_fee),0)::numeric fees,COALESCE(SUM(net_amount),0)::numeric net FROM howdi_connect_creator_revenue_ledger WHERE creator_user_id=$1 AND status='COMPLETED'`,[uid])).rows[0];
