              if(!uid||!title)return sendJSON(res,400,{status:"error",message:"Perk title required"});
              const row=(await pool.query(`INSERT INTO howdi_connect_creator_perks(creator_user_id,perk_code,perk_title,perk_description) VALUES($1,$2,$3,$4)
                ON CONFLICT(creator_user_id,perk_code) DO UPDATE SET perk_title=EXCLUDED.perk_title,perk_description=EXCLUDED.perk_description,is_active=TRUE RETURNING *`,[uid,code,title,description])).rows[0];
              return sendJSON(res,201,{status:"success",perk:row});
