              const communityId=Number(m?.[1]),targetUserId=Number(m?.[2]);
              const body=await getBody(req),moderatorUserId=Number(body.userId??body.user_id),muted=body.muted!==false;
              const room=(await pool.query(`SELECT owner_user_id,community_type FROM howdi_connect_communities WHERE id=$1`,[communityId])).rows[0];
              const moderator=room&&(Number(room.owner_user_id)===moderatorUserId||(await pool.query(`SELECT 1 FROM howdi_connect_realtime_participants WHERE community_id=$1 AND user_id=$2 AND participant_role='COHOST' AND left_at IS NULL`,[communityId,moderatorUserId])).rows.length>0);
              if(!room||room.community_type!=='SPACE'||!moderator)return sendJSON(res,403,{status:"error",message:"Host or co-host permission required"});
              if(targetUserId===Number(room.owner_user_id))return sendJSON(res,403,{status:"error",message:"Host cannot be muted by another participant"});
              const row=(await pool.query(`UPDATE howdi_connect_realtime_participants SET is_muted_by_host=$3,moderation_note=$4 WHERE community_id=$1 AND user_id=$2 AND left_at IS NULL RETURNING user_id,is_muted_by_host`,[communityId,targetUserId,muted,muted?'Muted by Space moderator':null])).rows[0];
              if(!row)return sendJSON(res,404,{status:"error",message:"Participant not found"});
              await pool.query(`INSERT INTO howdi_connect_realtime_signals(community_id,from_user_id,to_user_id,signal_type,payload) VALUES($1,$2,$3,$4,$5::jsonb)`,
                [communityId,moderatorUserId,targetUserId,muted?'MOD_MUTE':'MOD_UNMUTE',JSON.stringify({muted})]);
              return sendJSON(res,200,{status:"success",muted});
