              const body=await getBody(req),moderatorUserId=Number(body.userId??body.user_id);
              const room=(await pool.query(`SELECT owner_user_id,community_type FROM howdi_connect_communities WHERE id=$1`,[communityId])).rows[0];
              const moderator=room&&(Number(room.owner_user_id)===moderatorUserId||(await pool.query(`SELECT 1 FROM howdi_connect_realtime_participants WHERE community_id=$1 AND user_id=$2 AND participant_role='COHOST' AND left_at IS NULL`,[communityId,moderatorUserId])).rows.length>0);
              if(!room||room.community_type!=='SPACE'||!moderator)return sendJSON(res,403,{status:"error",message:"Host or co-host permission required"});
              if(targetUserId===Number(room.owner_user_id))return sendJSON(res,403,{status:"error",message:"Host cannot be removed"});
              await pool.query(`INSERT INTO howdi_connect_realtime_signals(community_id,from_user_id,to_user_id,signal_type,payload) VALUES($1,$2,$3,'MOD_KICK',$4::jsonb)`,
                [communityId,moderatorUserId,targetUserId,JSON.stringify({message:'You were removed from this Space by a moderator.'})]);
              await pool.query(`UPDATE howdi_connect_realtime_participants SET left_at=NOW(),moderation_note='Removed by Space moderator' WHERE community_id=$1 AND user_id=$2`,[communityId,targetUserId]);
