              const body=await getBody(req),userId=Number(body.userId??body.user_id),text=clean(body.messageText??body.message_text??"").trim();
              if(!text||text.length>1000)return sendJSON(res,400,{status:"error",message:"Message must contain 1 to 1000 characters"});
              const roomChat=(await pool.query(`SELECT owner_user_id,chat_mode,chat_slow_seconds FROM howdi_connect_communities WHERE id=$1`,[communityId])).rows[0];
              const memberRow=(await pool.query(`SELECT participant_role FROM howdi_connect_realtime_participants WHERE community_id=$1 AND user_id=$2 AND left_at IS NULL`,[communityId,userId])).rows[0];
              if(!memberRow)return sendJSON(res,403,{status:"error",message:"Join the session before chatting"});
              const isMod=Number(roomChat?.owner_user_id)===userId||memberRow.participant_role==='COHOST';
              if(roomChat?.chat_mode==='HOST_ONLY'&&!isMod)return sendJSON(res,403,{status:"error",message:"Chat is currently host-only"});
              if(roomChat?.chat_mode==='SUBSCRIBERS'&&!isMod){
                const sub=(await pool.query(`SELECT status,current_period_end FROM howdi_connect_creator_subscriptions WHERE creator_user_id=$1 AND subscriber_user_id=$2`,[roomChat.owner_user_id,userId])).rows[0];
                if(sub?.status!=='ACTIVE'||(sub.current_period_end&&new Date(sub.current_period_end)<=new Date()))return sendJSON(res,403,{status:"error",message:"Chat is for creator subscribers"});
              }
              if(!isMod&&Number(roomChat?.chat_slow_seconds||0)>0){
                const last=(await pool.query(`SELECT created_at FROM howdi_connect_space_chat WHERE community_id=$1 AND user_id=$2 ORDER BY id DESC LIMIT 1`,[communityId,userId])).rows[0];
                if(last&&Date.now()-new Date(last.created_at).getTime()<Number(roomChat.chat_slow_seconds)*1000)return sendJSON(res,429,{status:"error",message:`Slow mode: wait ${roomChat.chat_slow_seconds}s between messages`});
              }
              const row=(await pool.query(`INSERT INTO howdi_connect_space_chat(community_id,user_id,message_text) VALUES($1,$2,$3) RETURNING *`,[communityId,userId,text])).rows[0];
              return sendJSON(res,201,{status:"success",message:row});
