              const creatorStats=(await pool.query(`SELECT COUNT(*) FILTER(WHERE status IN('ACTIVE','TRIALING'))::int active_subscribers,COUNT(*)::int total_subscriptions,COALESCE(SUM(amount) FILTER(WHERE status IN('ACTIVE','TRIALING')),0)::numeric active_value FROM howdi_connect_subscriptions WHERE creator_user_id=$1`,[userId])).rows[0];
