              if(!option)return sendJSON(res,400,{status:"error",message:"Invalid poll option"});
              await pool.query(`INSERT INTO howdi_connect_poll_votes(poll_id,option_id,user_id) VALUES($1,$2,$3)
                ON CONFLICT(poll_id,user_id) DO UPDATE SET option_id=EXCLUDED.option_id,created_at=NOW()`,[poll.id,optionId,userId]);
              const options=(await pool.query(`SELECT po.id,po.option_text text,po.position,
                (SELECT COUNT(*)::int FROM howdi_connect_poll_votes pv WHERE pv.option_id=po.id) votes
                FROM howdi_connect_poll_options po WHERE po.poll_id=$1 ORDER BY po.position,po.id`,[poll.id])).rows;
              const totalVotes=options.reduce((n,o)=>n+Number(o.votes||0),0);
