              const body=await getBody(req);
              if(!Number.isInteger(userId)||userId<=0) return sendJSON(res,400,{status:"error",message:"Valid user ID is required"});

              const allowedBoolean=[
                "email_orders","email_offers","email_news",
                "sms_orders","sms_offers",
                "push_orders","push_offers",
                "personalized_recommendations",
                "activity_personalization","data_sharing_analytics"
              ];

              const updates=[];
              const values=[userId];
              let index=2;

              for(const key of allowedBoolean){
                if(typeof body[key]==="boolean"){
                  updates.push(`${key}=$${index++}`);
                  values.push(body[key]);
                }
              }

              if(body.saved_size_preference!==undefined){
                updates.push(`saved_size_preference=$${index++}`);
                values.push(body.saved_size_preference ? clean(String(body.saved_size_preference)).slice(0,40) : null);
              }

