    // ================================================================
    // V16.1C — HOWDI WORKS BOOKING JOURNEY COMPLETION
    // Reschedule ledger + customer lifecycle + invoice/receipt foundation.
    // Existing Works order, offer, journey, PIN, payment, review and case
    // ledgers remain the source of truth; this layer composes them safely.
    // ================================================================
    async function ensureWorksRescheduleV161C(){
      await pool.query(`CREATE TABLE IF NOT EXISTS works_reschedule_requests (
        id BIGSERIAL PRIMARY KEY,
        request_code VARCHAR(80) UNIQUE NOT NULL,
        work_order_id BIGINT NOT NULL REFERENCES works_work_orders(id) ON DELETE CASCADE,
        customer_user_id BIGINT NOT NULL,
        worker_id BIGINT REFERENCES works_workers(id) ON DELETE SET NULL,
        requested_date DATE NOT NULL,
        requested_time TIME NOT NULL,
        reason TEXT,
        status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')),
        responded_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )`);
      await pool.query(`CREATE INDEX IF NOT EXISTS works_reschedule_work_idx ON works_reschedule_requests(work_order_id,created_at DESC)`);
    }
    ensureWorksRescheduleV161C().catch(e=>console.error("[V16.1C] Works reschedule schema bootstrap failed:",e.message));

    app.get('/api/works/customer/bookings/:workCode/lifecycle-v161c', async (req,res)=>{
      try{
        const userId=String(req.query.userId||'').trim(), workCode=String(req.params.workCode||'').trim();
        if(!/^\d+$/.test(userId)) return res.status(400).json({status:'error',message:'Valid customer user ID is required'});
        const wo=(await pool.query(`SELECT * FROM works_work_orders WHERE work_code=$1 AND customer_user_id=$2 LIMIT 1`,[workCode,userId])).rows[0];
        if(!wo) return res.status(404).json({status:'error',message:'Works booking not found'});
        const [journey,payment,completion,review,cases,reschedules]=await Promise.all([
          pool.query(`SELECT j.*,w.worker_code,w.full_name worker_name,w.rating worker_rating FROM works_job_journeys j LEFT JOIN works_workers w ON w.id=j.worker_id WHERE j.work_order_id=$1 LIMIT 1`,[wo.id]),
          pool.query(`SELECT payment_code,payment_kind,amount,method,status,provider_reference,created_at,updated_at FROM works_payments WHERE work_order_id=$1 ORDER BY created_at DESC`,[wo.id]),
          pool.query(`SELECT status,note,created_at FROM works_completion_confirmations WHERE work_order_id=$1 LIMIT 1`,[wo.id]),
          pool.query(`SELECT rating,review,created_at FROM works_reviews WHERE work_order_id=$1 LIMIT 1`,[wo.id]),
          pool.query(`SELECT case_code,case_type,reason,priority,status,created_at,updated_at FROM works_cases WHERE work_order_id=$1 ORDER BY created_at DESC`,[wo.id]),
          pool.query(`SELECT request_code,requested_date,requested_time,reason,status,responded_at,created_at FROM works_reschedule_requests WHERE work_order_id=$1 ORDER BY created_at DESC`,[wo.id])
        ]);
        const j=journey.rows[0]||null;
        const stage=String(j?.stage||wo.status||'open').toLowerCase();
        return res.json({status:'success',version:'16.1C',booking:worksOrderRow(wo),journey:j?{stage,workerCode:j.worker_code||'',workerName:j.worker_name||'',workerRating:Number(j.worker_rating||0),pinVerified:j.pin_verified===true,etaMinutes:j.eta_minutes==null?null:Number(j.eta_minutes),acceptedAt:j.accepted_at||null,journeyStartedAt:j.journey_started_at||null,arrivedAt:j.arrived_at||null,workStartedAt:j.work_started_at||null,completedAt:j.completed_at||null,customerConfirmedAt:j.customer_confirmed_at||null,checkedOutAt:j.checked_out_at||null,closedAt:j.closed_at||null}:null,payments:payment.rows.map(x=>({...x,amount:Number(x.amount||0)})),completion:completion.rows[0]||null,review:review.rows[0]||null,cases:cases.rows,reschedules:reschedules.rows,actions:{canReschedule:['open','offered','accepted'].includes(stage),canCancel:['open','offered','accepted','en_route','arrived'].includes(stage),canVerifyPin:stage==='arrived'&&!j?.pin_verified,canPay:['completed','customer_confirmed','checked_out','closed'].includes(stage),canReview:['customer_confirmed','checked_out','closed'].includes(stage)}});
      }catch(e){return res.status(500).json({status:'error',message:'Unable to load Works lifecycle',detail:e.message||null});}
    });

    app.post('/api/works/customer/bookings/:workCode/reschedule-v161c', async (req,res)=>{
      try{
        const b=req.body||{}, userId=String(b.customerUserId||'').trim(), workCode=String(req.params.workCode||'').trim();
        const requestedDate=String(b.scheduleDate||'').trim(), requestedTime=String(b.scheduleTime||'').trim(), reason=String(b.reason||'').trim();
        if(!/^\d+$/.test(userId)||!/^\d{4}-\d{2}-\d{2}$/.test(requestedDate)||!/^\d{2}:\d{2}/.test(requestedTime)) return res.status(400).json({status:'error',message:'Customer, date and time are required'});
        const wo=(await pool.query(`SELECT * FROM works_work_orders WHERE work_code=$1 AND customer_user_id=$2 LIMIT 1`,[workCode,userId])).rows[0];
        if(!wo) return res.status(404).json({status:'error',message:'Works booking not found'});
        const j=(await pool.query(`SELECT * FROM works_job_journeys WHERE work_order_id=$1 LIMIT 1`,[wo.id])).rows[0];
        const stage=String(j?.stage||wo.status||'open').toLowerCase();
        if(!['open','offered','accepted'].includes(stage)) return res.status(409).json({status:'error',message:'This booking can no longer be self-rescheduled. Use HOWDI Support.'});
        const pending=(await pool.query(`SELECT 1 FROM works_reschedule_requests WHERE work_order_id=$1 AND status='pending' LIMIT 1`,[wo.id])).rows[0];
        if(pending) return res.status(409).json({status:'error',message:'A reschedule request is already pending'});
        const code=`HOWDI-RSCH-${Date.now().toString().slice(-10)}`;
        const row=(await pool.query(`INSERT INTO works_reschedule_requests(request_code,work_order_id,customer_user_id,worker_id,requested_date,requested_time,reason) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *`,[code,wo.id,userId,j?.worker_id||wo.preferred_worker_id||null,requestedDate,requestedTime,reason||null])).rows[0];
        return res.status(201).json({status:'success',message:'Reschedule request sent to the worker.',request:row});
      }catch(e){return res.status(500).json({status:'error',message:'Unable to request reschedule',detail:e.message||null});}
    });

    app.get('/api/works/customer/bookings/:workCode/invoice-v161c', async (req,res)=>{
      try{
        const userId=String(req.query.userId||'').trim(), workCode=String(req.params.workCode||'').trim();
        if(!/^\d+$/.test(userId)) return res.status(400).json({status:'error',message:'Valid customer user ID is required'});
        const wo=(await pool.query(`SELECT wo.*,w.worker_code,w.full_name worker_name FROM works_work_orders wo LEFT JOIN works_job_journeys j ON j.work_order_id=wo.id LEFT JOIN works_workers w ON w.id=j.worker_id WHERE wo.work_code=$1 AND wo.customer_user_id=$2 LIMIT 1`,[workCode,userId])).rows[0];
        if(!wo) return res.status(404).json({status:'error',message:'Works booking not found'});
        const pays=(await pool.query(`SELECT payment_code,payment_kind,amount,method,status,provider_reference,created_at FROM works_payments WHERE work_order_id=$1 ORDER BY created_at`,[wo.id])).rows;
        const service=pays.find(x=>x.payment_kind==='service'&&x.status==='success');
        if(!service) return res.status(409).json({status:'error',message:'Invoice becomes available after successful service payment'});
        const tip=pays.filter(x=>x.payment_kind==='tip'&&x.status==='success').reduce((s,x)=>s+Number(x.amount||0),0);
        return res.json({status:'success',invoice:{invoiceNumber:`HWI-WORKS-${String(wo.id).padStart(8,'0')}`,workCode:wo.work_code,issuedAt:service.created_at,customer:{name:wo.customer_name||'',city:wo.city||'',pincode:wo.pincode||''},worker:{workerCode:wo.worker_code||'',name:wo.worker_name||wo.preferred_worker_name||''},service:wo.service_name||wo.title||'HOWDI Works service',serviceAmount:Number(service.amount||0),tipAmount:tip,totalPaid:Number(service.amount||0)+tip,paymentMethod:service.method,paymentReference:service.provider_reference||service.payment_code,status:'PAID',note:'Tax/GST fields must be populated from the applicable HOWDI legal entity and worker tax profile before production invoicing.'}});
      }catch(e){return res.status(500).json({status:'error',message:'Unable to load Works invoice',detail:e.message||null});}
    });

    console.log('✅ HOWDI Works V16.1C active — booking lifecycle + reschedule + invoice foundation');

    startHowdiServer();
    console.log("✅ HOWDI Backend V37 active — booking SQL/trigger diagnostics enabled");

    console.log("✅ HOWDI Backend V38 loaded — root booking fix active");

    console.log("✅ HOWDI Backend V39 loaded — Worker Connect live");

    console.log("✅ HOWDI Backend V40 loaded — single header + Connect health");

    console.log("✅ HOWDI Backend V41 loaded — Worker Profile + Availability Transparency");

    console.log("✅ HOWDI Connect V16.0F loaded — Connect Home Final Completion");


