async function ensureWorksWorkerSideV161D() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS howdi_works_worker_availability (
      worker_user_id UUID NOT NULL,
      work_date DATE NOT NULL,
      start_time TIME NOT NULL,
      end_time TIME NOT NULL,
      is_available BOOLEAN NOT NULL DEFAULT TRUE,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY (worker_user_id, work_date, start_time, end_time)
    );
    CREATE TABLE IF NOT EXISTS howdi_works_worker_job_events (
      id BIGSERIAL PRIMARY KEY,
      booking_id BIGINT NOT NULL,
      worker_user_id UUID NOT NULL,
      event_type VARCHAR(40) NOT NULL,
      note TEXT,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
    CREATE INDEX IF NOT EXISTS works_worker_job_events_booking_idx
      ON howdi_works_worker_job_events(booking_id, created_at DESC);
    CREATE TABLE IF NOT EXISTS howdi_works_worker_payout_ledger (
      id BIGSERIAL PRIMARY KEY,
      worker_user_id UUID NOT NULL,
      booking_id BIGINT,
      gross_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
      platform_fee NUMERIC(12,2) NOT NULL DEFAULT 0,
      net_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
      payout_status VARCHAR(24) NOT NULL DEFAULT 'PENDING',
      payout_reference VARCHAR(120),
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      paid_at TIMESTAMPTZ
    );
  `);
}
ensureWorksWorkerSideV161D().catch((e) =>
  console.error("[V16.1D] Works worker-side schema:", e.message)
);

app.get("/api/works/worker/dashboard", async (req, res) => {
  try {
    const workerId = String(req.query.workerId || req.user?.id || "").trim();
    if (!workerId) return res.status(400).json({ ok:false, error:"workerId required" });
    const jobs = await pool.query(`
      SELECT b.*
      FROM howdi_works_bookings b
      WHERE b.worker_user_id=$1
      ORDER BY b.created_at DESC LIMIT 100
    `, [workerId]);
    const earnings = await pool.query(`
      SELECT COALESCE(SUM(net_amount) FILTER (WHERE payout_status='PAID'),0) paid,
             COALESCE(SUM(net_amount) FILTER (WHERE payout_status<>'PAID'),0) pending
      FROM howdi_works_worker_payout_ledger WHERE worker_user_id=$1
    `, [workerId]);
    res.json({ ok:true, jobs:jobs.rows, earnings:earnings.rows[0] || {paid:0,pending:0} });
  } catch (e) { res.status(500).json({ok:false,error:e.message}); }
});

