app.patch("/api/works/worker/jobs/:bookingId/action", async (req,res) => {
  const client=await pool.connect();
  try {
    const workerId=String(req.body.workerId||req.user?.id||"").trim();
    const action=String(req.body.action||"").toUpperCase();
    const allowed={ACCEPT:"ACCEPTED",REJECT:"REJECTED",START_JOURNEY:"ON_THE_WAY",ARRIVE:"ARRIVED",COMPLETE:"COMPLETED",CANCEL:"CANCELLED"};
    if(!allowed[action]) return res.status(400).json({ok:false,error:"Unsupported worker action"});
    await client.query("BEGIN");
    const b=await client.query(`SELECT * FROM howdi_works_bookings WHERE id=$1 AND worker_user_id=$2 FOR UPDATE`,
      [req.params.bookingId,workerId]);
    if(!b.rowCount){await client.query("ROLLBACK");return res.status(404).json({ok:false,error:"Booking not found"});}
    await client.query(`UPDATE howdi_works_bookings SET status=$1,updated_at=NOW() WHERE id=$2`,
      [allowed[action],req.params.bookingId]);
    await client.query(`INSERT INTO howdi_works_worker_job_events(booking_id,worker_user_id,event_type,note)
      VALUES($1,$2,$3,$4)`,[req.params.bookingId,workerId,action,String(req.body.note||"").slice(0,1000)]);
    await client.query("COMMIT");
    res.json({ok:true,status:allowed[action]});
  } catch(e){await client.query("ROLLBACK").catch(()=>{});res.status(500).json({ok:false,error:e.message});}
  finally{client.release();}
});

app.post("/api/works/worker/jobs/:bookingId/start-with-pin", async (req,res) => {
  try {
    const workerId=String(req.body.workerId||req.user?.id||"").trim();
    const pin=String(req.body.pin||"").trim();
    const b=await pool.query(`SELECT * FROM howdi_works_bookings WHERE id=$1 AND worker_user_id=$2`,
      [req.params.bookingId,workerId]);
    if(!b.rowCount) return res.status(404).json({ok:false,error:"Booking not found"});
    const expected=String(b.rows[0].job_pin||b.rows[0].start_pin||"");
    if(!expected || pin!==expected) return res.status(403).json({ok:false,error:"Invalid Job PIN"});
    await pool.query(`UPDATE howdi_works_bookings SET status='IN_PROGRESS',updated_at=NOW() WHERE id=$1`,[req.params.bookingId]);
    await pool.query(`INSERT INTO howdi_works_worker_job_events(booking_id,worker_user_id,event_type)
      VALUES($1,$2,'PIN_VERIFIED_START')`,[req.params.bookingId,workerId]);
    res.json({ok:true,status:"IN_PROGRESS"});
  } catch(e){res.status(500).json({ok:false,error:e.message});}
});

