async function ensureWorksCompletionV161E() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS howdi_works_booking_messages (
      id BIGSERIAL PRIMARY KEY,
      booking_id BIGINT NOT NULL,
      sender_user_id UUID NOT NULL,
      message_text TEXT NOT NULL,
      message_type VARCHAR(24) NOT NULL DEFAULT 'TEXT',
      is_read BOOLEAN NOT NULL DEFAULT FALSE,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
    CREATE INDEX IF NOT EXISTS works_booking_messages_idx ON howdi_works_booking_messages(booking_id,created_at);

    CREATE TABLE IF NOT EXISTS howdi_works_favourites (
      customer_user_id UUID NOT NULL,
      worker_user_id UUID NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY(customer_user_id,worker_user_id)
    );

    CREATE TABLE IF NOT EXISTS howdi_works_support_tickets (
      id BIGSERIAL PRIMARY KEY,
      booking_id BIGINT,
      opened_by_user_id UUID NOT NULL,
      issue_type VARCHAR(60) NOT NULL,
      priority VARCHAR(16) NOT NULL DEFAULT 'NORMAL',
      status VARCHAR(24) NOT NULL DEFAULT 'OPEN',
      description TEXT,
      evidence_json JSONB NOT NULL DEFAULT '[]'::jsonb,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );

    CREATE TABLE IF NOT EXISTS howdi_works_incidents (
      id BIGSERIAL PRIMARY KEY,
      booking_id BIGINT NOT NULL,
      reporter_user_id UUID NOT NULL,
      incident_type VARCHAR(60) NOT NULL,
      details TEXT,
      status VARCHAR(24) NOT NULL DEFAULT 'REPORTED',
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );

    CREATE TABLE IF NOT EXISTS howdi_works_reviews (
      id BIGSERIAL PRIMARY KEY,
      booking_id BIGINT NOT NULL UNIQUE,
      customer_user_id UUID NOT NULL,
      worker_user_id UUID NOT NULL,
      rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),
      review_text TEXT,
      is_visible BOOLEAN NOT NULL DEFAULT TRUE,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );

    CREATE TABLE IF NOT EXISTS howdi_works_user_blocks (
      blocker_user_id UUID NOT NULL,
      blocked_user_id UUID NOT NULL,
      reason VARCHAR(120),
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY(blocker_user_id,blocked_user_id)
    );

    CREATE TABLE IF NOT EXISTS howdi_works_notifications (
      id BIGSERIAL PRIMARY KEY,
      recipient_user_id UUID NOT NULL,
      booking_id BIGINT,
      notification_type VARCHAR(50) NOT NULL,
      title VARCHAR(160) NOT NULL,
      body TEXT,
      is_read BOOLEAN NOT NULL DEFAULT FALSE,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
  `);
}
ensureWorksCompletionV161E().catch(e=>console.error("[V16.1E] schema",e.message));

