app.get("/api/shop/v162a/discover",async(req,res)=>{
 try{
  const q=String(req.query.q||"").trim();
  const category=String(req.query.category||"").trim();
  const sort=String(req.query.sort||"relevance").toLowerCase();
  const minPrice=Number(req.query.minPrice||0), maxPrice=Number(req.query.maxPrice||999999999);
  const order=sort==="price_asc"?"price ASC":sort==="price_desc"?"price DESC":
              sort==="newest"?"created_at DESC":sort==="rating"?"rating DESC NULLS LAST":"created_at DESC";
  // Uses the established product table/read model where available.
  const r=await pool.query(`
    SELECT * FROM howdi_products
    WHERE ($1='' OR LOWER(COALESCE(name,'')) LIKE LOWER('%'||$1||'%')
      OR LOWER(COALESCE(description,'')) LIKE LOWER('%'||$1||'%'))
      AND ($2='' OR LOWER(COALESCE(category,''))=LOWER($2))
      AND COALESCE(price,0) BETWEEN $3 AND $4
    ORDER BY ${order} LIMIT 120`,[q,category,minPrice,maxPrice]);
  res.json({ok:true,products:r.rows});
 }catch(e){res.status(500).json({ok:false,error:e.message});}
});

