async function ensureHPayV164A(){
 await pool.query(`
  CREATE TABLE IF NOT EXISTS howdi_hpay_wallets_v164a(
    user_id UUID PRIMARY KEY, currency VARCHAR(8) NOT NULL DEFAULT 'INR',
    available_balance NUMERIC(14,2) NOT NULL DEFAULT 0,
    held_balance NUMERIC(14,2) NOT NULL DEFAULT 0,
    status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',
    kyc_status VARCHAR(24) NOT NULL DEFAULT 'NOT_STARTED',
    payment_pin_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    daily_debit_limit NUMERIC(14,2), daily_transfer_limit NUMERIC(14,2),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_ledger_v164a(
    id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL, direction VARCHAR(8) NOT NULL,
    event_type VARCHAR(50) NOT NULL, amount NUMERIC(14,2) NOT NULL,
    currency VARCHAR(8) NOT NULL DEFAULT 'INR', reference_type VARCHAR(40),
    reference_id VARCHAR(160), idempotency_key VARCHAR(180),
    status VARCHAR(24) NOT NULL DEFAULT 'POSTED', note TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE UNIQUE INDEX IF NOT EXISTS hpay_ledger_idempotency_idx
    ON howdi_hpay_ledger_v164a(idempotency_key) WHERE idempotency_key IS NOT NULL;
  CREATE TABLE IF NOT EXISTS howdi_hpay_payment_intents_v164a(
    id BIGSERIAL PRIMARY KEY, payer_user_id UUID NOT NULL, module VARCHAR(24) NOT NULL,
    reference_id VARCHAR(160), amount NUMERIC(14,2) NOT NULL, currency VARCHAR(8) NOT NULL DEFAULT 'INR',
    payment_source VARCHAR(24) NOT NULL DEFAULT 'WALLET', provider_reference VARCHAR(180),
    idempotency_key VARCHAR(180) UNIQUE, status VARCHAR(24) NOT NULL DEFAULT 'PENDING',
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_transfers_v164a(
    id BIGSERIAL PRIMARY KEY, sender_user_id UUID NOT NULL, receiver_user_id UUID NOT NULL,
    amount NUMERIC(14,2) NOT NULL, currency VARCHAR(8) NOT NULL DEFAULT 'INR',
    note TEXT, status VARCHAR(24) NOT NULL DEFAULT 'PENDING',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_refunds_v164a(
    id BIGSERIAL PRIMARY KEY, payment_intent_id BIGINT, user_id UUID NOT NULL,
    amount NUMERIC(14,2) NOT NULL, reason TEXT, status VARCHAR(24) NOT NULL DEFAULT 'REQUESTED',
    provider_reference VARCHAR(180), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_escrow_v164a(
    id BIGSERIAL PRIMARY KEY, owner_user_id UUID NOT NULL, beneficiary_user_id UUID,
    module VARCHAR(24) NOT NULL, reference_id VARCHAR(160), amount NUMERIC(14,2) NOT NULL,
    status VARCHAR(24) NOT NULL DEFAULT 'HELD', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    released_at TIMESTAMPTZ
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_settlements_v164a(
    id BIGSERIAL PRIMARY KEY, beneficiary_user_id UUID NOT NULL, beneficiary_type VARCHAR(30) NOT NULL,
    module VARCHAR(24) NOT NULL, reference_id VARCHAR(160),
    gross_amount NUMERIC(14,2) NOT NULL DEFAULT 0, platform_fee NUMERIC(14,2) NOT NULL DEFAULT 0,
    commission_amount NUMERIC(14,2) NOT NULL DEFAULT 0, net_amount NUMERIC(14,2) NOT NULL DEFAULT 0,
    status VARCHAR(24) NOT NULL DEFAULT 'PENDING', payout_reference VARCHAR(180),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), settled_at TIMESTAMPTZ
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_risk_events_v164a(
    id BIGSERIAL PRIMARY KEY, user_id UUID, transaction_reference VARCHAR(180),
    risk_type VARCHAR(60) NOT NULL, risk_score NUMERIC(6,2) NOT NULL DEFAULT 0,
    device_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, status VARCHAR(24) NOT NULL DEFAULT 'REVIEW',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_hpay_admin_queue_v164a(
    id BIGSERIAL PRIMARY KEY, queue_type VARCHAR(60) NOT NULL, reference_id VARCHAR(180),
    priority VARCHAR(16) NOT NULL DEFAULT 'NORMAL', status VARCHAR(24) NOT NULL DEFAULT 'OPEN',
    notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
 `);
}
