async function ensureCrossPillarV165A(){
 await pool.query(`
  CREATE TABLE IF NOT EXISTS howdi_cross_pillar_capabilities_v165a(
    module VARCHAR(30) PRIMARY KEY, version VARCHAR(30), status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',
    capabilities JSONB NOT NULL DEFAULT '[]'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_cross_pillar_activity_v165a(
    id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL, module VARCHAR(30) NOT NULL,
    event_type VARCHAR(60) NOT NULL, reference_type VARCHAR(50), reference_id VARCHAR(180),
    title VARCHAR(220), metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE INDEX IF NOT EXISTS cross_activity_user_idx
    ON howdi_cross_pillar_activity_v165a(user_id,created_at DESC);
  CREATE TABLE IF NOT EXISTS howdi_unified_saved_items_v165a(
    user_id UUID NOT NULL, item_type VARCHAR(30) NOT NULL, item_id VARCHAR(180) NOT NULL,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(user_id,item_type,item_id)
  );
  CREATE TABLE IF NOT EXISTS howdi_unified_notifications_v165a(
    id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL, module VARCHAR(30) NOT NULL,
    type VARCHAR(60) NOT NULL, title VARCHAR(220) NOT NULL, body TEXT,
    reference_type VARCHAR(50), reference_id VARCHAR(180),
    is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE INDEX IF NOT EXISTS unified_notifications_user_idx
    ON howdi_unified_notifications_v165a(user_id,is_read,created_at DESC);
  CREATE TABLE IF NOT EXISTS howdi_cross_pillar_links_v165a(
    id BIGSERIAL PRIMARY KEY, source_module VARCHAR(30) NOT NULL, source_type VARCHAR(50) NOT NULL,
    source_id VARCHAR(180) NOT NULL, target_module VARCHAR(30) NOT NULL,
    target_type VARCHAR(50) NOT NULL, target_id VARCHAR(180) NOT NULL,
    relation_type VARCHAR(60) NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_payment_reference_bridge_v165a(
    id BIGSERIAL PRIMARY KEY, module VARCHAR(30) NOT NULL, reference_type VARCHAR(50) NOT NULL,
    reference_id VARCHAR(180) NOT NULL, hpay_reference_type VARCHAR(50) NOT NULL,
    hpay_reference_id VARCHAR(180) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'LINKED',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(module,reference_type,reference_id,hpay_reference_type,hpay_reference_id)
  );
  CREATE TABLE IF NOT EXISTS howdi_cross_pillar_events_v165a(
    id BIGSERIAL PRIMARY KEY, event_name VARCHAR(100) NOT NULL, actor_user_id UUID,
    source_module VARCHAR(30) NOT NULL, reference_type VARCHAR(50), reference_id VARCHAR(180),
    payload JSONB NOT NULL DEFAULT '{}'::jsonb, processed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
  CREATE TABLE IF NOT EXISTS howdi_integration_issue_queue_v165a(
    id BIGSERIAL PRIMARY KEY, module VARCHAR(30), issue_type VARCHAR(80) NOT NULL,
    reference_id VARCHAR(180), severity VARCHAR(16) NOT NULL DEFAULT 'NORMAL',
    status VARCHAR(24) NOT NULL DEFAULT 'OPEN', details TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );
 `);

 const caps=[
  ["CONNECT","16.0F",["social-graph","groups","channels","calls","articles","subscriptions","home"]],
  ["SHOP","16.2D",["discovery","checkout","orders","seller","inventory","reviews","disputes"]],
  ["WORKS","16.1F",["discovery","booking","journey","worker","quotes","marketplace"]],
  ["LEARN","16.3C",["learning","studio","live","community","subscriptions","institutions"]],
  ["HPAY","16.4B",["wallet","payments","escrow","settlements","merchant","risk"]]
 ];
 for(const c of caps){
   await pool.query(`INSERT INTO howdi_cross_pillar_capabilities_v165a(module,version,capabilities)
    VALUES($1,$2,$3::jsonb)
    ON CONFLICT(module) DO UPDATE SET version=EXCLUDED.version,capabilities=EXCLUDED.capabilities,updated_at=NOW()`,
    [c[0],c[1],JSON.stringify(c[2])]);
 }
}
ensureCrossPillarV165A().catch(e=>console.error("[V16.5A] integration schema",e.message));

