// =====================================================
// HOWDI V16.6J — MY HOWDI ROLE CENTER
// Public capability roles only. Internal staff RBAC is never returned here.
// Storefront remains a Shop surface, not an account type or top-level pillar.
// =====================================================
const HOWDI_PUBLIC_ROLE_ORDER = ['CUSTOMER','CREATOR','VENDOR','WORKER','LEARNER','TEACHER'];
const HOWDI_ROLE_CENTER_CONFIG = {
  CUSTOMER:{label:'Customer',description:'Shop, book services, learn and participate across HOWDI.',mode:'BASE',publicBadge:false},
  CREATOR:{label:'Creator',description:'Publish Vibes, Stories, Articles and build a public creator presence.',mode:'INSTANT',publicBadge:true},
  VENDOR:{label:'Vendor',description:'Sell through a HOWDI Shop storefront after business onboarding.',mode:'ONBOARDING',publicBadge:true},
  WORKER:{label:'Worker',description:'Offer verified local services through HOWDI Works.',mode:'ONBOARDING',publicBadge:true},
  LEARNER:{label:'Learner',description:'Build learning progress, projects and a verified Skill Passport.',mode:'INSTANT',publicBadge:false},
  TEACHER:{label:'Teacher',description:'Teach verified HOWDI learning programs after approval.',mode:'ONBOARDING',publicBadge:true}
};

async function getHowdiRoleCenter(userId){
  const q=await pool.query(`
    SELECT r.code,r.name,r.description,
           ur.role_status,ur.is_primary,ur.requested_at,ur.decided_at,
           ur.rejection_reason,ur.onboarding_state,ur.role_metadata
    FROM roles r
    LEFT JOIN user_roles ur ON ur.role_id=r.id AND ur.user_id=$1
    WHERE r.code=ANY($2::varchar[]) AND r.is_active=TRUE
  `,[userId,HOWDI_PUBLIC_ROLE_ORDER]);
  const byCode=new Map(q.rows.map(row=>[String(row.code).toUpperCase(),row]));
  const [vendorProfile,vendorApplication,workerApplication,teacherProfile]=await Promise.all([
    pool.query(`SELECT status,created_at FROM vendor_profiles WHERE user_id=$1 ORDER BY created_at DESC LIMIT 1`,[userId]).then(x=>x.rows[0]||null).catch(()=>null),
    pool.query(`SELECT a.status,a.review_note,a.created_at,a.updated_at,v.status vendor_status,v.kyc_status vendor_kyc_status,v.payout_status vendor_payout_status FROM howdi_vendor_applications a LEFT JOIN howdi_vendors v ON v.id=a.converted_vendor_id WHERE a.user_id=$1 ORDER BY a.created_at DESC LIMIT 1`,[userId]).then(x=>x.rows[0]||null).catch(()=>null),
    pool.query(`SELECT a.status,a.review_note,a.created_at,a.updated_at,w.kyc_status worker_kyc_status,w.skill_status worker_skill_status,w.account_status worker_account_status FROM works_worker_applications a LEFT JOIN works_workers w ON w.id=a.converted_worker_id WHERE a.user_id=$1 ORDER BY a.created_at DESC LIMIT 1`,[userId]).then(x=>x.rows[0]||null).catch(()=>null),
    pool.query(`SELECT application_status,rejection_reason,created_at,updated_at FROM learning_teacher_profiles WHERE user_id=$1 LIMIT 1`,[userId]).then(x=>x.rows[0]||null).catch(()=>null)
  ]);
  return HOWDI_PUBLIC_ROLE_ORDER.map(code=>{
    const row=byCode.get(code)||{};
    const cfg=HOWDI_ROLE_CENTER_CONFIG[code];
    let status=code==='CUSTOMER'?'ACTIVE':(row.role_status||'AVAILABLE');
    let rejectionReason=row.rejection_reason||null;
    let onboardingState=row.onboarding_state||null;
    if(code==='VENDOR'){
      if(vendorProfile&&String(vendorProfile.status||'').toLowerCase()==='active')status='ACTIVE';
      else if(vendorApplication){
        const x=String(vendorApplication.status||'').toLowerCase();
        const verified=x==='approved'&&String(vendorApplication.vendor_status||'').toLowerCase()==='active'&&['verified','approved'].includes(String(vendorApplication.vendor_kyc_status||'').toLowerCase());
        status=verified?'ACTIVE':x==='rejected'?'REJECTED':['new','in_review','under_review','submitted','approved'].includes(x)?'PENDING':status;
        rejectionReason=vendorApplication.review_note||rejectionReason;onboardingState=status==='ACTIVE'?'COMPLETE':x==='approved'?'VERIFICATION':'SUBMITTED';
      }
    }
    if(code==='WORKER'&&workerApplication){
      const x=String(workerApplication.status||'').toLowerCase();
      const verified=x==='approved'&&String(workerApplication.worker_kyc_status||'').toLowerCase()==='verified'&&String(workerApplication.worker_skill_status||'').toLowerCase()==='verified'&&String(workerApplication.worker_account_status||'').toLowerCase()==='active';
      status=verified?'ACTIVE':x==='rejected'?'REJECTED':['new','in_review','under_review','submitted','approved'].includes(x)?'PENDING':status;
      rejectionReason=workerApplication.review_note||rejectionReason;onboardingState=status==='ACTIVE'?'COMPLETE':x==='approved'?'VERIFICATION':'SUBMITTED';
    }
    if(code==='TEACHER'&&teacherProfile){const x=String(teacherProfile.application_status||'').toUpperCase();status=x==='APPROVED'?'ACTIVE':x==='REJECTED'?'REJECTED':['SUBMITTED','UNDER_REVIEW','CHANGES_REQUIRED'].includes(x)?'PENDING':status;rejectionReason=teacherProfile.rejection_reason||rejectionReason;onboardingState=status==='ACTIVE'?'COMPLETE':x;}
    const next=code==='CREATOR'?{area:'connect',view:'vibe'}:
      code==='VENDOR'?{area:'shop',view:'vendor'}:
      code==='WORKER'?{area:'works',view:'become'}:
      code==='LEARNER'?{area:'learn',view:'my-learning'}:
      code==='TEACHER'?{area:'learn',view:'home'}:{area:'myhowdi',view:'overview'};
    return {
      code,label:cfg.label,description:cfg.description,mode:cfg.mode,
      status,isPrimary:Boolean(row.is_primary),publicBadge:cfg.publicBadge,
      requestedAt:row.requested_at||null,decidedAt:row.decided_at||null,
      rejectionReason,onboardingState,next
    };
  });
}

app.get('/api/my-howdi/roles',async(req,res)=>{
  const user=await getSessionUserFromRequest(req);
  if(!user)return res.status(401).json({status:'error',message:'Please sign in to open My Roles.'});
  // Self-heal the permanent CUSTOMER capability for legacy accounts.
  await pool.query(`
    INSERT INTO user_roles(user_id,role_id,is_primary,role_status,requested_at,decided_at,onboarding_state)
    SELECT $1,r.id,NOT EXISTS(SELECT 1 FROM user_roles x WHERE x.user_id=$1 AND x.is_primary=TRUE),'ACTIVE',NOW(),NOW(),'COMPLETE'
    FROM roles r WHERE r.code='CUSTOMER'
    ON CONFLICT(user_id,role_id) DO UPDATE SET role_status='ACTIVE',onboarding_state='COMPLETE',rejection_reason=NULL,updated_at=NOW()
  `,[user.id]);
  const roles=await getHowdiRoleCenter(user.id);
  return res.status(200).json({status:'success',roles,publicIdentity:user.public_username||null,internalIdentityExposed:false});
});

app.post('/api/my-howdi/roles/:role/activate',async(req,res)=>{
  const user=await getSessionUserFromRequest(req);
  if(!user)return res.status(401).json({status:'error',message:'Please sign in to manage your HOWDI roles.'});
  const code=String(req.params.role||'').trim().toUpperCase();
  const cfg=HOWDI_ROLE_CENTER_CONFIG[code];
  if(!cfg)return res.status(404).json({status:'error',message:'Unknown HOWDI role.'});
  if(code==='CUSTOMER')return res.status(200).json({status:'success',message:'Customer is your permanent base HOWDI role.',roles:await getHowdiRoleCenter(user.id)});

  // Verified roles must begin in their real onboarding flow. Role Center never
  // bypasses KYC, worker verification, vendor approval or teacher approval.
  if(cfg.mode==='ONBOARDING'){
    const next=code==='VENDOR'?{area:'shop',view:'vendor'}:code==='WORKER'?{area:'works',view:'become'}:{area:'learn',view:'home'};
    return res.status(409).json({status:'onboarding_required',message:`Complete ${cfg.label} onboarding before this role can become active.`,role:code,next});
  }

  const role=(await pool.query(`SELECT id FROM roles WHERE code=$1 AND is_active=TRUE LIMIT 1`,[code])).rows[0];
  if(!role)return res.status(409).json({status:'error',message:'This HOWDI role is not currently available.'});
  await pool.query(`
    INSERT INTO user_roles(user_id,role_id,is_primary,role_status,requested_at,decided_at,onboarding_state,rejection_reason)
    VALUES($1,$2,FALSE,'ACTIVE',NOW(),NOW(),'COMPLETE',NULL)
    ON CONFLICT(user_id,role_id) DO UPDATE SET
      role_status='ACTIVE',requested_at=COALESCE(user_roles.requested_at,NOW()),decided_at=NOW(),
      onboarding_state='COMPLETE',rejection_reason=NULL,updated_at=NOW()
  `,[user.id,role.id]);
  if(code==='CREATOR') await ensureVibeCreatorProfile(user);
  return res.status(200).json({status:'success',message:`${cfg.label} role activated.`,roles:await getHowdiRoleCenter(user.id)});
});

