// ============================================================================
// HOWDI V16.6A — INTEGRATION REPAIR + CANONICAL SCHEMA RECONCILIATION
// Compatibility layer for legacy/new Works naming, canonical references,
// schema diagnostics, route inventory, module reference validation.
// IMPORTANT: non-destructive bridge; legacy tables are not dropped.
// ============================================================================

async function ensureIntegrationRepairV166A(){
 await pool.query(`
  CREATE TABLE IF NOT EXISTS howdi_schema_aliases_v166a(
    alias_module VARCHAR(30) NOT NULL,
    alias_name VARCHAR(120) NOT NULL,
    canonical_name VARCHAR(120) NOT NULL,
    strategy VARCHAR(30) NOT NULL DEFAULT 'COMPATIBILITY',
    notes TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY(alias_module,alias_name)
  );

  CREATE TABLE IF NOT EXISTS howdi_integration_diagnostics_v166a(
    id BIGSERIAL PRIMARY KEY,
    check_key VARCHAR(120) NOT NULL,
    module VARCHAR(30) NOT NULL,
    severity VARCHAR(16) NOT NULL DEFAULT 'INFO',
    status VARCHAR(24) NOT NULL DEFAULT 'OPEN',
    details JSONB NOT NULL DEFAULT '{}'::jsonb,
    checked_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );

  CREATE TABLE IF NOT EXISTS howdi_canonical_reference_map_v166a(
    id BIGSERIAL PRIMARY KEY,
    module VARCHAR(30) NOT NULL,
    reference_type VARCHAR(50) NOT NULL,
    legacy_reference VARCHAR(180),
    canonical_reference VARCHAR(180) NOT NULL,
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(module,reference_type,legacy_reference,canonical_reference)
  );
 `);

 const aliases=[
   ["WORKS","howdi_works_bookings","works_work_orders","COMPATIBILITY","V16.1D/E/F compatibility bridge"],
   ["WORKS","howdi_works_worker_job_events","works_job_journeys","COMPATIBILITY","Journey/event compatibility"],
   ["WORKS","howdi_works_worker_payout_ledger","works_payments","COMPATIBILITY","Payment/payout compatibility"],
   ["SHOP","howdi_shop_payment_intents_v162b","howdi_hpay_payment_intents_v164a","REFERENCE_BRIDGE","Shop→HPay"],
   ["LEARN","howdi_teacher_earnings_v163b","howdi_creator_settlements_v163c","REFERENCE_BRIDGE","Learning earnings→settlements"],
   ["PLATFORM","public_username","public_username","CANONICAL","Public-facing identity; internal HOWDI ID remains private"]
 ];
 for(const a of aliases){
   await pool.query(`INSERT INTO howdi_schema_aliases_v166a
    (alias_module,alias_name,canonical_name,strategy,notes)
    VALUES($1,$2,$3,$4,$5)
    ON CONFLICT(alias_module,alias_name) DO UPDATE SET
    canonical_name=EXCLUDED.canonical_name,strategy=EXCLUDED.strategy,
    notes=EXCLUDED.notes,updated_at=NOW()`,a);
 }
}
ensureIntegrationRepairV166A().catch(e=>console.error("[V16.6A] repair schema",e.message));

async function howdiTableExistsV166A(tableName){
 const r=await pool.query(`SELECT EXISTS(
   SELECT 1 FROM information_schema.tables
   WHERE table_schema='public' AND table_name=$1
 ) AS exists`,[tableName]);
 return !!r.rows[0]?.exists;
}

async function howdiColumnsV166A(tableName){
 const r=await pool.query(`SELECT column_name,data_type
   FROM information_schema.columns
   WHERE table_schema='public' AND table_name=$1 ORDER BY ordinal_position`,[tableName]);
 return r.rows;
}

