app.post("/api/platform/v166b/integrity/run",async(req,res)=>{
 try{
  const actual=await howdiRuntimeTableSetV166B();
  const registry=await pool.query(`SELECT object_name,module,canonical FROM howdi_schema_registry_v166b`);
  const deps=await pool.query(`SELECT method,route_path,module,table_dependencies FROM howdi_api_dependency_registry_v166b`);
  const findings=[];
  for(const x of registry.rows){
   if(!actual.has(x.object_name)){
    findings.push({checkType:"MISSING_REGISTERED_TABLE",module:x.module,objectName:x.object_name,
      severity:x.canonical?"HIGH":"NORMAL",details:{canonical:x.canonical}});
   }
  }
  for(const d of deps.rows){
   for(const t of (d.table_dependencies||[])){
    if(!actual.has(t)) findings.push({checkType:"API_MISSING_TABLE",module:d.module,objectName:t,
      severity:"HIGH",details:{method:d.method,routePath:d.route_path}});
   }
  }
  for(const f of findings){
   await pool.query(`INSERT INTO howdi_integrity_findings_v166b
    (check_type,module,object_name,severity,details) VALUES($1,$2,$3,$4,$5::jsonb)`,
    [f.checkType,f.module,f.objectName,f.severity,JSON.stringify(f.details)]);
  }
  res.json({ok:true,checkedAt:new Date().toISOString(),findingCount:findings.length,findings,
    destructiveChangesPerformed:false});
 }catch(e){res.status(500).json({ok:false,error:e.message});}
});

