function howdiAuthUserIdV166C(req){
  const id=req?.user?.id || req?.auth?.userId || req?.session?.user?.id || null;
  return id ? String(id) : null;
}
function howdiRequireAuthV166C(req,res){
  const uid=howdiAuthUserIdV166C(req);
  if(!uid){ res.status(401).json({ok:false,error:"Authentication required"}); return null; }
  return uid;
}
function howdiRolesV166C(req){
  const raw=req?.user?.roles || req?.auth?.roles || req?.session?.user?.roles || [];
  return (Array.isArray(raw)?raw:[raw]).filter(Boolean).map(x=>String(x).toUpperCase());
}
function howdiRequireRoleV166C(req,res,allowed){
  const uid=howdiRequireAuthV166C(req,res); if(!uid)return null;
  const roles=howdiRolesV166C(req);
  const ok=allowed.map(x=>String(x).toUpperCase()).some(x=>roles.includes(x));
  if(!ok){res.status(403).json({ok:false,error:"Insufficient permission"});return null;}
  return {uid,roles};
}
function howdiPublicSafeV166C(value){
  if(Array.isArray(value)) return value.map(howdiPublicSafeV166C);
  if(value && typeof value==="object"){
    const out={};
    for(const [k,v] of Object.entries(value)){
      if(["howdi_id","howdiId","internal_howdi_id","internalHowdiId","master_id","masterId"].includes(k)) continue;
      out[k]=howdiPublicSafeV166C(v);
    }
    return out;
  }
  return value;
}

