// ============================================================================
// HOWDI V16.6D — RUNTIME STABILITY + WEB SECURITY HARDENING
// Error normalization • request IDs • security headers • origin policy helpers
// CSRF foundation • cookie/session policy • rate limiting • graceful shutdown
// IMPORTANT: provider/framework-specific middleware still requires runtime wiring.
// ============================================================================

const cryptoV166D = require("crypto");

function howdiRequestIdV166D(req){
  return String(req.headers?.["x-request-id"] || cryptoV166D.randomUUID());
}
function howdiClientIpV166D(req){
  const xf=req.headers?.["x-forwarded-for"];
  return String(Array.isArray(xf)?xf[0]:(xf||req.socket?.remoteAddress||"unknown")).split(",")[0].trim();
}
function howdiSafeErrorV166D(err,requestId){
  const production=String(process.env.NODE_ENV||"").toLowerCase()==="production";
  return {ok:false,error:production?"Internal server error":String(err?.message||err||"Internal server error"),requestId};
}
function howdiSecurityHeadersV166D(res){
  res.setHeader("X-Content-Type-Options","nosniff");
  res.setHeader("X-Frame-Options","DENY");
  res.setHeader("Referrer-Policy","strict-origin-when-cross-origin");
  res.setHeader("Permissions-Policy","camera=(self), microphone=(self), geolocation=(self)");
  res.setHeader("Cross-Origin-Resource-Policy","same-site");
}
function howdiAllowedOriginsV166D(){
  return String(process.env.HOWDI_ALLOWED_ORIGINS||"http://localhost:5173,http://localhost:5174")
    .split(",").map(x=>x.trim()).filter(Boolean);
}
function howdiOriginAllowedV166D(req){
  const origin=req.headers?.origin;
  if(!origin)return true;
  return howdiAllowedOriginsV166D().includes(String(origin));
}
function howdiCookiePolicyV166D(){
  const prod=String(process.env.NODE_ENV||"").toLowerCase()==="production";
  return {httpOnly:true,secure:prod,sameSite:"lax",path:"/"};
}

const howdiRateBucketsV166D=new Map();
function howdiRateCheckV166D(key,limit=120,windowMs=60000){
  const now=Date.now(); let b=howdiRateBucketsV166D.get(key);
  if(!b || now-b.started>=windowMs){b={started:now,count:0};howdiRateBucketsV166D.set(key,b);}
  b.count++;
  return {allowed:b.count<=limit,remaining:Math.max(0,limit-b.count),resetMs:Math.max(0,windowMs-(now-b.started))};
}
setInterval(()=>{
 const now=Date.now();
 for(const [k,b] of howdiRateBucketsV166D.entries()) if(now-b.started>300000) howdiRateBucketsV166D.delete(k);
},120000).unref?.();

