// ============================================================================
// HOWDI V16.6G — DATABASE PERFORMANCE + PAGINATION + CACHE FOUNDATION
// Query telemetry • safe pagination • cache metadata • index recommendation
// registry • slow-query observations. Non-destructive: no blind indexes created.
// ============================================================================

function howdiPageV166G(req,{defaultLimit=30,maxLimit=100}={}){
  const rawLimit=Number(req?.query?.limit||defaultLimit);
  const rawOffset=Number(req?.query?.offset||0);
  const limit=Math.min(maxLimit,Math.max(1,Number.isFinite(rawLimit)?Math.floor(rawLimit):defaultLimit));
  const offset=Math.max(0,Number.isFinite(rawOffset)?Math.floor(rawOffset):0);
  return {limit,offset};
}
function howdiCursorV166G(req){
  const c=req?.query?.cursor;
  return c?String(c):null;
}
function howdiCacheControlV166G(res,{scope="private",maxAge=30,staleWhileRevalidate=30}={}){
  res.setHeader("Cache-Control",`${scope}, max-age=${Math.max(0,maxAge)}, stale-while-revalidate=${Math.max(0,staleWhileRevalidate)}`);
}
async function howdiTimedQueryV166G(label,text,params=[]){
  const started=Date.now();
  try{
    const result=await pool.query(text,params);
    const durationMs=Date.now()-started;
    if(durationMs>=Number(process.env.HOWDI_SLOW_QUERY_MS||750)){
      pool.query(`INSERT INTO howdi_query_observations_v166g
        (query_label,duration_ms,row_count,status) VALUES($1,$2,$3,'SLOW')`,
        [label,durationMs,result?.rowCount||0]).catch(()=>{});
    }
    return result;
  }catch(e){
    const durationMs=Date.now()-started;
    pool.query(`INSERT INTO howdi_query_observations_v166g
      (query_label,duration_ms,row_count,status,error_code) VALUES($1,$2,0,'ERROR',$3)`,
      [label,durationMs,String(e?.code||"UNKNOWN")]).catch(()=>{});
    throw e;
  }
}

