function howdiTextV166I(v,{max=5000,required=false}={}){
  if(v===undefined||v===null||v===""){
    if(required) throw new Error("Required field missing");
    return null;
  }
  const s=String(v).trim();
  if(s.length>max) throw new Error(`Field exceeds ${max} characters`);
  return s;
}
function howdiIntV166I(v,{min=0,max=1000000,required=false}={}){
  if(v===undefined||v===null||v===""){
    if(required) throw new Error("Required number missing");
    return null;
  }
  const n=Number(v);
  if(!Number.isInteger(n)||n<min||n>max) throw new Error("Invalid integer value");
  return n;
}
function howdiSafeFilenameV166I(name){
  return String(name||"file").replace(/[^a-zA-Z0-9._-]/g,"_").slice(0,180);
}
function howdiUploadPolicyV166I(){
  return {
    maxBytes:Number(process.env.HOWDI_UPLOAD_MAX_BYTES||10485760),
    imageMime:["image/jpeg","image/png","image/webp"],
    documentMime:["application/pdf"],
    executableBlocked:true
  };
}
function howdiValidationErrorV166I(res,e,requestId=null){
  return res.status(400).json({ok:false,error:{code:"VALIDATION_ERROR",message:String(e?.message||"Invalid input")},requestId});
}

