app.post("/api/platform/v166i/validate-upload-metadata",(req,res)=>{
 const requestId=howdiRequestIdV166D(req);
 try{
  const b=req.body||{}, policy=howdiUploadPolicyV166I();
  const filename=howdiSafeFilenameV166I(howdiTextV166I(b.filename,{max:180,required:true}));
  const mime=howdiTextV166I(b.mime,{max:100,required:true});
  const size=howdiIntV166I(b.size,{min:1,max:policy.maxBytes,required:true});
  const allowed=[...policy.imageMime,...policy.documentMime].includes(mime);
  if(!allowed) throw new Error("Unsupported upload type");
  res.json({ok:true,validated:{filename,mime,size},requestId,
    note:"Metadata validation only; server-side byte signature scanning remains required at actual upload handler."});
 }catch(e){return howdiValidationErrorV166I(res,e,requestId);}
});

